template<typename T>
struct Segtree{
    using F=function<T(T,T)>;
    int siz;
    vector<T> dat;
    const F f;
    const T t1;
    Segtree(int n,const F f,const T &t1):f(f),t1(t1){
        siz=1;
        while(siz<n)siz<<=1;
        dat.assign(2*siz,t1);
    }
    void set(int k,const T &tt){
        dat[k+siz]=tt;
    }
    void build(){
        for(int k=siz-1;k>0;k--){
            dat[k]=f(dat[2*k+0],dat[2*k+1]);
        }
    }
    void update(int k,const T &tt){
        k+=siz;
        dat[k]=tt;
        while(k>>=1){
            dat[k]=f(dat[2*k],dat[2*k+1]);
        }
    }
    T query(int a,int b){
        T l1=t1;T r1=t1;
        for(a+=siz,b+=siz;a<b;a>>=1,b>>=1){
            if(a&1){
                l1=f(l1,dat[a++]);
            }
            if(b&1){
                r1=f(dat[--b],r1);
            }
        }
        return f(l1,r1);
    }
    T operator[](const int &k) const{
        return dat[k+siz];
    }
};
