using namespace std;

class BinaryIndexedTree {
public:
    unsigned int n = 0;
    vector<long long> a;

    BinaryIndexedTree(unsigned int n) : n(n) {
        this->a = vector<long long>(n, 0);
    }

    // sum[0, i)
    long long sum(int i) {
        assert(0 <= i && i < this->n);

        long long s = 0;
        i -= 1;
        while (i >= 0) {
            s += this->a[i];
            i = (i & (i + 1)) - 1;
        }
        return s;
    }

    // a[i] += x(0-origin)
    void add(int i, int x) {
        assert(0 <= i && i < this->n);

        while (i < this->n) {
            this->a[i] += x;
            i |= i + 1;
        }
    }
};



