template<typename T>
struct BinaryIndexedTree {
    std::vector<T> data;

    explicit BinaryIndexedTree(i32 sz) { data.assign(++sz, 0); }

    T sum(i32 k) {
        T ret = 0;
        for (++k; k > 0; k -= k & -k) ret += data[k];
        return ret;
    }

    void add(i32 k, T x) {
        for (++k; k < SZ(data); k += k & -k) data[k] += x;
    }
};

