struct BIT{
    int N;
    vector<int> dat;
    BIT() {}
    BIT(int n) {
		N = n;
		dat.resize(N + 1);
    }
    // update k th element (0-index)
	void add(int k, int x){
        k++;
		while(k <= N){
			dat[k] += x;
			k += k&-k;
		}
	}
	// sum [0, k) (0-index)
	int sum(int k){
		int s = 0;
		while(k > 0){
			s += dat[k];
			k -= k&-k;
		}
		return s;
	}
	// sum [a, b) (0-index)
	int query(int a, int b){
		return sum(b) - sum(a);
	}
};

