class BIT
{
private:
	std::vector<LL>dat;

public:
	void init(LL size)
	{
		dat.resize(size + 1, 0);
	}

	void update(LL k, LL x)
	{
		if (k >= dat.size()) return;
		dat[k] += x;
		update(k + (k & -k), x);
	}

	LL sum(LL k)
	{
