template<typename T>
struct BIT {

	int n;
	vector<T> node;
	function<T(T, T)> f;//operator
	function<T(T, T)> g;//update

	BIT(const vector<T> &a, function<T(T, T)> f, function<T(T, T)> g) :n(a.size() + 1),f(f), g(g) {
		node.resize(n + 1,0);
	}

	void update(int i, T x) {
		while (i <= n) {
			node[i] = f(node[i], x);
			i += i & -i;
		}
	}

	T get(int i) {
		T acc = 0;
		while (i > 0) {
			acc = g(acc,node[i]);
			i -= i & -i;
		}
		return acc;
	}
};


template<typename T>
struct SegmentTree {

	int n_bot;
	vi node;
	T e;
	function<T(T, T)> f;//operator
	function<T(T, T)> g;//update

	T rec(int x, int y, int i, int l, int r) {
		if (r < x || y < l)return e;
		if (x <= l && r <= y)return node[i];
		int child_l = rec(x, y, 2 * i, l, (l + r) / 2);
		int child_r = rec(x, y, 2 * i + 1, (l + r + 1) / 2, r);
		return f(child_l, child_r);
	}

	//データ、初期値(単位元)、取得に使う演算、更新に使う演算
	SegmentTree(const vector<T> &a, T e, function<T(T, T)> f, function<T(T, T)> g) :e(e), f(f), g(g) {
		int n = a.size();
		n_bot = 1;
		while (n_bot < n)n_bot *= 2;
		node.resize(2 * n_bot, e);
		rep(i, n) {
			node[i + n_bot] = a[i];
		}
	}

	void update(int i, T x) {
		i += n_bot;
		node[i] = g(node[i], x);
		while (i > 0) {
			i /= 2;
			node[i] = f(node[2 * i], node[2 * i + 1]);
		}
	}

	T get(int x, int y) {
		return rec(x, y, 1, 0, n_bot - 1);
	}

	friend ostream& operator<<(ostream& out, const SegmentTree<T> &seg) {
		rep(i, seg.n_bot)cout << seg.node[i + seg.n_bot] << " ";
		return out;
	}

};


