void init(int n){
    int nn = 1;
    while(nn < n) nn *= 2;
    fill(st, st + 2 * nn - 1, 0);
}

void add(int i, ll a, int k, int l, int r){
    if(i < l || r <= i) return;
    if(r - l == 1) st[k] += a;
    else{
        int chl = 2 * k + 1;
        int chr = 2 * k + 2;
        add(i, a, chl, l, (l + r) / 2);
        add(i, a, chr, (l + r) / 2, r);
        st[k] = st[chl] + st[chr];
    }
}

ll get_sum(int a, int b, int k, int l, int r){
    if(r <= a || b <= l) return 0;
    if(a <= l && r <= b) return st[k];
    ll res_l = get_sum(a, b, 2 * k + 1, l, (l + r) / 2);
    ll res_r = get_sum(a, b, 2 * k + 2, (l + r) / 2, r);
    return res_l + res_r;
}

