#define MAX_N 500000
int bit_[MAX_N + 1], n_;

int sum(int i) {
  int s = 0;
  while (i > 0) {
    s += bit_[i];
    i -= i & -i;
  }
  return s;
}
void add(int i, int x) {
  while (i <= n_) {
    bit_[i] += x;
    i += i & -i;
  }
}

