constexpr int sqrtN = 512;

struct SqrtDecomposition {

    int N, K;
    vector<int> data;
    vector<int> bucket;

    SqrtDecomposition(int N) : N(N) {
        K = (N + sqrtN - 1) / sqrtN;
        data.assign(K * sqrtN, 0);
        bucket.assign(K, 0);
    }

    void add(int pos, int x) {
        int k = pos / sqrtN;
        data[pos] += x;
        int sum = 0;
        for (int i = k * sqrtN; i < (k + 1) * sqrtN; i++) {
            sum += data[i];
        }
        bucket[k] = sum;
    }

    int get(int a, int b) {
        int ret = 0;
        for (int k = 0; k < K; k++) {
            int l = k * sqrtN;
            int r = (k + 1) * sqrtN;
            if (r <= a or b <= l) continue;
            if (a <= l and r <= b) ret += bucket[k];
            else {
                for (int i = max(a, l); i < min(b, r); i++) {
                    ret += data[i];
                }
            }
        }
        return ret;
    }

};

int main() {

    int N, Q;
    cin >> N >> Q;

    SqrtDecomposition deco(N);

    while (Q--) {
        int w;
        cin >> w;
        if (w == 0) {
            int x, y;
            cin >> x >> y;
            deco.add(x - 1, y);
        } else {
            int x, y;
            cin >> x >> y;
            cout << deco.get(x - 1, y) << endl;
        }
    }

}

