template <typename T>
class SegmentTree {
  using func_t = function<T(T, T)>;
  const int n;
  const T id;
  func_t merge;
  vector<T> data;
  T sub(int l, int r, int node, int lb, int ub) {
    if (ub <= l || r <= lb) return id;
    if (l <= lb && ub <= r) return data[node];
    T vl = sub(l, r, node * 2 + 0, lb, (lb + ub) / 2);
    T vr = sub(l, r, node * 2 + 1, (lb + ub) / 2, ub);
    return merge(vl, vr);
  }
  int size(int n) {
    return n == 1 ? n : size((n + 1) / 2) * 2;
  }
public:
  SegmentTree(int n, T id, func_t merge) :
    n(size(n)), id(id), merge(merge), data(n * 2, id) {}
  void add(int p, T val) {
    assert (0 <= p && p < n);
    p += n;
    data[p] = val;
    while (p /= 2) {
      int l = p * 2, r = p * 2 + 1;
      data[p] = merge(data[l], data[r]);
    }
  }
  T find(int l, int r) {
    return sub(l, r, 1, 0, n);
  }
};

int main() {
  int n, q, com, x, y;
  cin >> n >> q;
  SegmentTree<int> seg(n, 0, [](int a, int b){return a+b;});
  while (q--) {
    cin >> com >> x >> y;
    if (com) cout << seg.find(x, y+1) << endl;
    else seg.add(x, y);
  }
  return 0;
}

#include <iostream>
using namespace std;

const int N_MAX = 100000;
int dat[N_MAX * 4];

int n;
int n_add;

void init() {
	int k = 0;
	while ((n - 1) >> k) k++;
	n_add = (1 << k) - 1;
	for (int i = 0; i < n_add * 2; ++i) {
		dat[i] = 0;
	}
}

void add(int x, int y) {
	x += n_add;
	while (x > 0) {
		dat[x] += y;
		x = x / 2;
	}
}

int getSum(int x, int y) {
	x = x + n_add;
	y = y + n_add;

	int sum = 0;
	while (true) {
		if (x > y)
			return sum;
		else if (x == y)
			return sum + dat[x];

		bool xodd = x % 2;
		bool yodd = y % 2;
		if (xodd && yodd) {
			sum += dat[x];
			x = x / 2 + 1;
			y = y / 2;
		} else if (xodd && !yodd) {
			sum += dat[x] + dat[y];
			x = x / 2 + 1;
			y = y / 2 - 1;
		} else if (!xodd && yodd) {
			x = x / 2;
			y = y / 2;
		} else {
			sum += dat[y];
			x = x / 2;
			y = y / 2 - 1;
		}
	}
}

int main() {
	int q;
	cin >> n >> q;
	init();
	for (int i = 0; i < q; ++i) {
		int c, x, y;
		cin >> c >> x >> y;
		if (c == 0)
			add(x, y);
		else
			cout << getSum(x, y) << endl;
	}
}

