class SegmentTree {
private:
    using T = Monoid::T;
    std::vector<T> seg;
    Monoid ope;
    const int size;
    const int cap;
public:
    SegmentTree() : size(0), cap(0) {}
    SegmentTree(const int &sz) : size(sz), cap(sz << 1), seg(sz << 1, ope.identity()) {}
    void update(int idx, const T &val) {
        seg[idx += size] = val;
        while (idx >>= 1) seg[idx] = ope(seg[idx << 1], seg[(idx << 1) + 1]);
    }
    // range is [left, right) !!!!!!!!
    T get(int left, int right) {
        T leftRes = ope.identity(), rightRes = ope.identity();
        for (left += size, right += size; left < right; left >>= 1, right >>= 1) {
            if (left & 1) leftRes = ope(leftRes, seg[left++]);
            if (right & 1) rightRes = ope(rightRes, seg[--right]);
        }
        return ope(leftRes, rightRes);
    }
};

