	int n, q;
	cin >> n >> q;
	root = init(1, n);
	for (int i = 0; i < q; ++i) {
		int com, x, y;
		cin >> com >> x >> y;
		if (com == 0)
			add(root, x, y);
		else
			cout << getSum(root,x, y) << endl;
	}
}

