// Binary Indexed Tree (BIT)
// 1-indexed
template<typename T>
struct BIT{
private:
    vector<T> array;
    const int n;

public:
    // 初期化
    BIT(int _n) : array(_n + 1, 0), n(_n) {}

    // [1, i]までの累積和を求める
    T sum(int i) {
        T s = 0;
        while(i > 0){
            s += array[i];
            i -= i & -i;
        }
        return s;
    }

    // [i, j]の要素の総和
    T sum(int i, int j) {
        T ret_i = sum(i-1);
        T ret_j = sum(j);
        return ret_j - ret_i;
    }

    // i番目に要素xを追加
    void add(int i, T x){
        while(i <= n) {
            array[i] += x;
            i += i & -i;
        }
    }
};


