void bitInit(int n){
	fill(BIT, BIT + n, 0);
	bit_size = n;
}

int bitSum(int n){
	int ans = 0;
	while(n > 0){
		ans += BIT[n];
		n &= n-1;
	}
	return ans;
}

void bitAdd(int n, int v){
	while(n < bit_size) { 
		BIT[n] += v;
		n += n & (-n);
	}
}

