	node.resize(2*n-1, 0);
}

void add(int x, int val) {
    x += (n - 1);
    node[x] += val;
    while(x > 0) {
        x = (x - 1) / 2;
        node[x] = node[2*x+1] + node[2*x+2];
    }
}

int getsum(int a, int b, int k=0, int l=0, int r=-1) {
    if(r < 0) r = n;
    if(r <= a || b <= l) return 0;
    if(a <= l && r <= b) return node[k];
    int vl = getsum(a, b, 2*k+1, l, (l+r)/2);
    int vr = getsum(a, b, 2*k+2, (l+r)/2, r);
    return (vl + vr);
}

