	M e;//単位元

	segment_tree(int N, vector<M> &data, F f, M e) : f(f), e(e){
		size = 1;
		while(size < N) size *= 2;
		val.assign(2 * size, e);
		for(int i = 0; i < N; i++) val[size + i] = data[i];
		for(int i = N; i < size; i++) val[size + i] = e;
		for(int i = size - 1; i > 0; i--) val[i] = f(val[2 * i], val[2 * i + 1]);
	}

	//k番目の要素をxに変更する
	void update(int k, M x){
		k += size;
		val[k] = x;
		while(k /= 2) val[k] = f(val[2 * k], val[2 * k + 1]);
	}

	//[a, b)の演算の結果を返す
	M query(int a, int b){
		M L = e, R = e;
		for(a += size, b += size; a < b; a /= 2, b /= 2){
			if(a & 1) L = f(L, val[a++]);
			if(b & 1) R = f(val[--b], R);
		}
		return f(L, R);
	}
};

int sum(int x, int y){
	return x + y;
}

