template<typename T> 
struct BIT{
  int n;
  vector<T> bit;
  //1-indexed
  BIT():n(-1){}
  BIT(int n,T d):n(n),bit(n+1,d){}

  T sum(int i){
    T s=0;
    for(int x=i;x>0;x-=(x&-x))
      s+=bit[x];
    return s;
  }
  void add(int i,T a){
    if(i==0) return;
    for(int x=i;x<=n;x+=(x&-x))
      bit[x]+=a;
  }

  T query(int l,int r){
    return sum(r-1)-sum(l-1);
  }

  void rebuild(){
    vector<T> prev(bit);
    vector<T> dump(n+1);
    for(int i=1;i<=n;i++) dump[i]=query(i,i+1);
    bit.assign(n+1,0);

    for(int i=1;i<=n;i++){
      bit[i]+=dump[i];
      if(i+(i&-i)<=n) bit[i+(i&-i)]+=bit[i];
    }
    for(int i=1;i<=n;i++) assert(prev[i]==bit[i]);
  }
};
