// T: モノイド
template<typename T>
class SegmentTree {
    int n;
    const T ZERO;
    std::vector<T> data;
public:
    // 要素数を指定し、全要素加法単位元で初期化
    SegmentTree(int n_, T ZERO) : ZERO(ZERO) {
        n = 1;
        while (n < n_)n <<= 1;
        data.resize(2 * n);
        std::fill(data.begin(), data.end(), ZERO);
    }

    // 元となるstd::vectorを用意して初期化
    SegmentTree(std::vector<T> source, T ZERO) : ZERO(ZERO) {
        n = 1;
        while (n < source.size())n <<= 1;
        data.resize(2 * n);
        std::copy(source.begin(), source.end(), data.begin() + n);
        for (int i = n - 1; i > 0; i--)data[i] = data[2 * i] + data[2 * i + 1];
    }

    // [l, r)の区間和を取得
    T getSum(int l, int r) const {
        l += n, r += n;
        T ret = ZERO;
        while (l < r) {
            if (l & 1)ret += data[l], l++;
            if (r & 1)ret += data[r - 1];
            l >>= 1, r >>= 1;
        }
        return ret;
    }

    // 要素iをxに更新
    void update(int i, T x) {
        i += n;
        data[i] = x;
        while (i > 1) {
            i >>= 1;
            data[i] = data[2 * i] + data[2 * i + 1];
        }
    }
};

