    for(int i=0; i<q; i++){
        int c, x, y;
        cin >> c >> x >> y;
        if(c){
            cout << seg.query(x-1, y) << endl;
        }
        else{
            seg.add_val(x-1, y);
        }
    }
    return 0;
}

