class BIT {
public:
	std::vector<int> bit;//[1,n]
	int n;

	BIT() {};
	BIT(int N) { n = N; bit.assign(n + 1, 0); }

	//iまでの和を求めるためにはiから初めて0に到達するまでiから最下位bitを取り除きながら場所iに格納されている値を足していく
	int sum(int i) {
		int s = 0;
		while (i > 0) {
			s += bit[i];
			i = (i & (i - 1));//最下位bitを取り除く
		}
		return s;
	}

	//bit[i]の値をxに書き換える。
	// iからはじめて、iの再開ビットを加算しながら場所iの値にxを加えていく
	void add(int i, int x) {
		while (i <= n) {
			bit[i] += x;
			i += (i & -i);//最下位bitを足す
		}
	}

	int rangesum(int from, int to) {
		if (from == 0) { return sum(to); }
		else { return sum(to) - sum(from - 1); }
	}
};
int main() {
	int N, Q;
	cin >> N >> Q;
	BIT bit(N);
	REP(q, Q) {
		int a, x, y;
		cin >> a >> x >> y;
		if (a == 0) {
			bit.add(x, y);
		}
		else {
			cout << bit.rangesum(x, y) << endl;
		}
	}
}

