template <typename Abelian> class FenwickTree {
	using uint32 = std::uint_fast32_t;

public:
	using value_type = Abelian;
	using reference = Abelian &;
	using const_reference = const Abelian &;

private:
	using F = std::function<value_type(const_reference, const_reference)>;
	const value_type neutral_;
	const F p, m;
	const uint32 size_;
	std::vector<value_type> tree;
	static uint32 getsize(const uint32 size) {
		uint32 ret = 1;
		while (ret < size)
			ret <<= 1;
		return ret;
	}

public:
	FenwickTree(const uint32 size, const_reference neutral = value_type(),
		const F &p = std::plus<value_type>(),
		const F &m = std::minus<value_type>())
		: neutral_(neutral), p(p), m(m), size_(getsize(size)),
		tree(size_ + 1, neutral_) {}
	FenwickTree(const uint32 size, const_reference neutral, const F &p,
		const std::function<value_type(const_reference)> &n)
		: neutral_(neutral), p(p),
		m([&p, &n](const_reference l, const_reference r) {
		return p(l, n(r));
	}),
		size_(getsize(size)), tree(size_ + 1, neutral_) {}
	void add(uint32 index, const_reference diff) {
		assert(index < size_);
		for (++index; index <= size_; index += index & ~index + 1)
			tree[index] = p(tree[index], diff);
	}
	void subtract(uint32 index, const_reference diff) {
		assert(index < size_);
		for (++index; index <= size_; index += index & ~index + 1)
			tree[index] = m(tree[index], diff);
	}
	value_type range(uint32 end) const {
		assert(end <= size_);
		value_type ret = neutral_;
		do
			ret = p(tree[end], ret);
		while (end &= end - 1);
		return ret;
	}
	value_type range(uint32 begin, uint32 end) const {
		assert(begin <= end);
		return m(range(end), range(begin));
	}
	uint32 search(const std::function<bool(const_reference)> &b) const {
		if (!b(tree.back()))
			return size_;
		uint32 i = size_ >> 1;
		value_type acc = neutral_;
		for (uint32 k = size_ >> 1; k; k >>= 1)
			if (!b(p(acc, tree[i -= k])))
				acc = p(acc, tree[i]), i += k;
		return i - 1;
	}
	value_type operator[](uint32 index) const {
		assert(index < size_);
		return range(index, index + 1);
	}
};

