void add(int x,int y, int n, int* A)
{
  for(; x<n; x = x + (x & -x))
    A[x] += y;
}

int getSum(int a, int* A)
{
  int ans = 0;
  for(; a>0; a = a - (a & -a))
    ans += A[a];
  return ans;
}

