struct ADD {
	int64 e;
	ADD(int64 t = 0) { e = t; }
	ADD operator*(const ADD &other) {
		return ADD(e + other.e);
	}
};

struct SUM {
	int64 e;
	int64 s;
	SUM(int64 x = 0, int64 y = 1) { e = x;s = y; }
	void set() { e = 0; s = 1; }
	void reverse(void) {}
	SUM operator+(const SUM &other) {
		return  SUM(e + other.e, s + other.s);
	};
	SUM operator*(const ADD &other) {
		return SUM(e + (s*other.e), s);
	}
};

int main(void) {
	std::ios::sync_with_stdio(false);
	std::cin.tie(0);
	avl_tree<SUM> T;
	uint32 n, q;
	std::cin >> n >> q;
	avl_tree<SUM>::set();
	for (uint32 i = 0;i < n;++i) {
		T = T.insert(0, SUM());
	}
