	while (q--) {
		std::cin >> c >> x >> y;
		//T.show();
		if (c) {
			auto U = T.split(x - 1);
			auto V = U.second.split(y - x + 1);
			std::cout << V.first.fold().e << "\n";
		}
		else {
			auto U = T.split(x - 1);
			//U.first.show();
			//U.second.show();
			auto V = U.second.split(1);
			//V.second.show();
			auto W = avl_tree<SUM>::singlton(V.first.fold() + SUM(y));
			T = avl_tree<SUM>::merge(avl_tree<SUM>::merge(U.first, W), V.second);
		}
		//T.show();
	}
	return 0;
}

