vector<ll> dat;
int N;

void update(int k, int a) {
  k += N - 1;
  dat[k] += a;
  while (k > 0) {
    k = (k - 1) / 2;
    dat[k] += a;
  }
}

int find(int a, int b, int k, int l, int r) {
  // [a, b) での最小値。[l, r) と節点kが対応
  if (r <= a || b <= l) return 0;
  if (a <= l && r <= b) return dat[k];
  else {
    int vl = find(a, b, k * 2 + 1, l, (l + r) / 2);
    int vr = find(a, b, k * 2 + 2, (l + r) / 2, r);
    return vl + vr;
  }
}

