template<typename T> class BIT
{
   private:
      vector<T> bit;
      int len;
   public:
      BIT(int n) {
         len = n+1;
         bit.resize(len);
      }
      void add(int i, T x) {
         i += 1;
         while (i < len) {
            bit[i] += x;
            i += i & -i;
         }
      }
      int sum(int i) {
         i += 1;
         T s = 0;
         while (i > 0) {
            s += bit[i];
            i -= i & -i;
         }
         return s;
      }
};
template<typename T> class RSQ {
   private:
      BIT<T> bit;
   public:
      RSQ(int n) : bit(n) {}
      void add(int i, int x) {
         bit.add(i, x);
      }
      T sum(int l, int r) {
         // return sum[l,r]
         return bit.sum(r) - bit.sum(l-1);
      }
};

