void RSQuery::updateST( vector<int> &st, int ix )
{
  if ( ix == 0 ) return;
  int p = (ix - 1) / 2;

  while ( true )
    {
      st[p] = st[2 * p + 1] + st[2 * p + 2];
      if ( p == 0 ) break;
      p = (p - 1) / 2;
    }

  return;
}

int RSQuery::getSum( vector<int> &st, int x, int y , int ix, int l, int r )
{
  if ( r <= x || y <= l ) return 0;
  if ( x <= l && r <= y )
    return st[ix];
  else
    return getSum( st, x, y, 2 * ix + 1, l, (l + r) / 2 ) + getSum(st, x, y, 2 * ix + 2, (l + r) / 2, r );
  return 0;
}

