//平方分割
const int sqrtN = 1024;

template<typename T>
struct SqrtDecomposition {
	//RSQ(平方分割)
private:
	T N, K;
	vector<T> data;
	vector<T> bucketSum;
public:
	SqrtDecomposition(T n) : N(n) {
		K = (N + sqrtN - 1) / sqrtN;
		data.assign(K * sqrtN, 0);
		bucketSum.assign(K, 0);
	}
	void add(T x, T y) {
		T k = x / sqrtN;
		data[x] += y;
		T sum = 0;
		for (T i = k * sqrtN; i < (k + 1) * sqrtN; ++i) {
			sum += data[i];
		}
		bucketSum[k] = sum;
	}
	// [x, y)
	T getSum(T x, T y) {
		int sum = 0;
		for (int k = 0; k < K; ++k) {
			T l = k * sqrtN, r = (k + 1) * sqrtN;
			if (r <= x || y <= l)
				continue;
			if (x <= l && r <= y) {
				sum += bucketSum[k];
			}
			else {
				for (T i = max(x, l); i < min(y, r); ++i) {
					sum += data[i];
				}
			}
		}
		return sum;
	}
};



