template <class T>
class SegTree {
    int n;
    vector<T> data;
    T def;
    function<T(T, T)> operation;
    function<T(T, T)> update;

    // 区間[a,b)の処理。ノードk=[l,r)に着目
    // 要素の取得は最上段から再帰していく
    // [a,b):クエリの要求範囲, [l,r):ノードの対象範囲, k:高さ
    T _query(int a, int b, int k, int l, int r) {
        if(r <= a || b <= l) return def;    // 要求区間外は単位元
        if(a <= l && r <= b) return data[k];    // 要求区間を完全に包含
        else {
            // 要求区間が対象区間を一部含むときは子を辿る
            T c1 = _query(a, b, 2*k+1, l, (l+r)/2);
            T c2 = _query(a, b, 2*k+2, (l+r)/2, r);
            return operation(c1, c2);
        }
    }

  public:
    // _n:必要サイズ, _def:初期値または単位元, _operation:クエリ関数
    // _update:更新関数
    SegTree(size_t _n, T _def, function<T(T, T)> _operation, function<T(T, T)> _update)
        : def(_def), operation(_operation), update(_update) {
        n = 1;
        while(n < _n) {
            n *= 2;
        }
        data = vector<T>(2*n-1, def);
    }

    // 場所i(0-indexed)の値をxで更新
    void change(int i, T x) {
        i += n-1;
        data[i] = update(data[i], x);
        while(i > 0) {
            i = (i-1) / 2;
            data[i] = operation(data[2*i+1], data[2*i+2]);
        }
    }

    // [a,b)の区間クエリを実行
    T query(int a, int b) {
        return _query(a, b, 0, 0, n);
    }

    // 添え字でアクセス
    T operator[](int i) {
        return data[i+n-1];
    }
};

int main() {
    int N, q; cin >> N >> q;
    SegTree<ll> seg(N, 0,
