using ll = long long;

// 1-indexed
class BinaryIndexedTree{
    public:
    ll size;
    vector<ll> bit;

    BinaryIndexedTree(ll n){
        size = n;
        bit = vector<ll>(size + 1, 0LL);
    }

    // Get a_1 + ... + a_idx
    ll getSum(ll idx){
        ll acc = 0;
        while(idx > 0){
            acc += bit[idx];
            idx -= (idx & -idx);
        }
        return acc;
    }

    void add(ll idx, ll x){
        while(idx <= size){
            bit[idx] += x;
            idx += (idx & -idx);
        }
    }
};

