int sqrtN;
int N, Q;
vector<int> data, backet;

int getSum(int l, int r) {
    int res = 0;
    for (int i = l; i <= r; ++i) {
        if (i % sqrtN == 0 && i + sqrtN <= r) {
            res += backet[i / sqrtN];
            i += sqrtN - 1;
        } else {
            res += data[i];
        }
    }
    return res;
}

void update(int p, int val) {
    data[p] += val;
    backet[p / sqrtN] += val;
}

