struct RSQ{
  ll size;
  ll *tree;
  RSQ(ll sz){
    ll logsize; for(logsize=0;(1ll<<logsize)<sz;logsize++);
    size=(1ll<<logsize);
    cout<<size<<endl;
    tree=new ll[size*2-1];
    REP(i,size*2-1) tree[i]=0;
  }
  void add(ll i,ll x){
    ll k=i+size-1;
    tree[k]+=x;
    while(k>0){
      k=(k-1)/2;
      tree[k]+=x;
    }
  }
  ll getSum(ll s,ll t,ll l,ll r,ll k){
    if(t<=l||r<=s||l>=r) return 0;
    if(l+1==r) return tree[k];
