void add(ll ind,ll v){
  ind+=(1LL<<20);
  seg[ind]+=v;
  while(1){
    ind/=2;
    if(ind==0) break;
    seg[ind]=seg[ind*2]+seg[ind*2+1];
  }
}

ll sum(ll l,ll r){
  l+=(1LL<<20);
  r+=(1LL<<20);
  ll ans=0;
  while(l<r){
    if(l%2==1){
      ans+=seg[l];
      l++;
    }
    l/=2;
    if(r%2==1){
      ans+=seg[r-1];
      r--;
    }
    r/=2;
  }
  return ans;
}

