struct RSQ{
    int N;
    vector<int> Tree;
    RSQ(int size){
        N=1;
        while(N<size) N*=2;
        Tree.resize(2*N-1, 0);
    }

    void update(int pos, int val){
        pos += N-1;
        Tree[pos] += val;
        while(pos>0){
            pos = (pos-1)/2;
            Tree[pos] = Tree[pos*2+1] + Tree[pos*2+2];
        }
    }

    int getSum(int a, int b, int k=0, int l=0, int r=-1){
        if(r<0) r = N;
        if(r<=a or b<=l) return 0;
        if(a<=l and r<=b) return Tree[k];
        else{
            int lval = getSum(a, b, 2*k+1, l, (l+r)/2);
            int rval = getSum(a, b, 2*k+2, (l+r)/2, r);
            return lval + rval;
        }
    }
};

