using namespace std;

class SegTree {
public:
    int m_n;
    vector<int> m_data;
    vector<int> m_lazy;

    SegTree( int n ) { Init( n ); }

    void Init( int n ) {

	m_n = 1;
	while ( m_n < n ) m_n <<= 1;

	m_data.resize( 2*m_n - 1 );
	m_lazy.resize( 2*m_n - 1 );	
    }


    void Add( int k, int val ) {

	k += m_n - 1;

	m_data[k] += val;

	while ( k > 0 ) {
	    k = ( k - 1 )/2;
	    m_data[k] = m_data[2*k+1] + m_data[2*k+2];
	}
    }

    void Add( int a, int b, int val ) {
	update( a, b + 1, 0, 0, m_n, val );
    }

    int Sum( int a, int b ) {
	return query( a, b + 1, 0, 0, m_n );
    }

protected:

    void eval( int k, int l, int r ) {

	if ( m_lazy[k] != 0 ) {

	    m_data[k] += m_lazy[k];

	    if ( r - l > 1 ) {
		m_lazy[2*k+1] += m_lazy[k];
		m_lazy[2*k+2] += m_lazy[k];
	    }

	    m_lazy[k] = 0;
	}
    }

    void update( int a, int b, int k, int l, int r, int val ) {

	eval( k, l, r );

	if ( b <= l || a >= r ) return;

	if ( a <= l && r <= b ) {
	    m_lazy[k] += val;
	    eval( k, l, r );
	}
	else {
	    update( a, b, 2*k+1, l, (l+r)/2, val );
	    update( a, b, 2*k+2, (l+r)/2, r, val );
	    m_data[k] = m_data[2*k+1] + m_data[2*k+2];
	}

    }

    int query( int a, int b, int k, int l, int r ) {

	eval( k, l, r );

	if ( b <= l || a >= r ) return 0;

	if ( a <= l && r <= b ) return m_data[k];

	int left = query( a, b, 2*k+1, l, (l+r)/2 );
	int right = query( a, b, 2*k+2, (l+r)/2, r );

	return left + right;
    }

};


int main() {

    int n, q;

    cin >> n >> q;

    SegTree seg( n );

    int c, x, y;
    for ( int i=0; i<q; ++i ) {

	cin >> c >> x >> y;
	if ( c == 0 ) seg.Add( x, x, y );
	else cout << seg.Sum( x, y ) << endl;

    }

    return 0;
}

