using namespace std;
class SegmentTree {
private:
	int siz;
	vector<int> dat;

public:
	SegmentTree(vector<int> v) {
		siz = 1;
		while(siz < (int) v.size()) siz <<= 1;
		dat.resize(2 * siz - 1, 0);
		for(int idx = 0; idx < (int) v.size(); idx++) {
			dat[idx + siz - 1] = v[idx];
		}
		for(int idx = siz - 2; idx >= 0; idx--) {
			dat[idx] = dat[2 * idx + 1] + dat[2 * idx + 2];
		}
	}

	void add(int idx, int val) {
		idx += (siz - 1);
		dat[idx] += val;
		while(idx > 0) {
			idx = (idx - 1) / 2;
			dat[idx] = dat[2 * idx + 1] + dat[2 * idx + 2];
		}
	}
	int get(int a, int b, int idx = 0, int l = 0, int r = -1) {
		if(r < 0) r = siz;
		if(r <= a || b <= l) return 0;
		if(a <= l && r <= b) return dat[idx];
		int val1 = get(a, b, 2 * idx + 1, l, (l + r) / 2);
		int val2 = get(a, b, 2 * idx + 2, (l + r) / 2, r);
		return val1 + val2;
	}
};
