class SegTree {
public:
	int data[1<<(depth+1)];
	SegTree() { for (int i = 0; i < (1<<(depth+1)); i++) data[i] = 0; }
	void add(int pos, int x) {
		pos = (1<<depth) - 1 + pos;
		data[pos] += x;
		while (pos > 0) {
			pos = (pos - 1) / 2;
			data[pos] += x;
		}
