void update (intt v, intt l, intt r, intt i, intt val) {
    if (i < l || i > r)
        return;
    if (l == r) {
        t[v] = val;
        return;
    }
    intt mid = (l + r) >> 1;
    update (v << 1, l, mid, i, val);
    update (v << 1 | 1, mid + 1, r, i, val);
    t[v] = t[v << 1] + t[v << 1 | 1];
}

