struct segTree{
	vi val;
	int N;
	segTree(int n){
		N=1;
		while(N<n)N*=2;
		val.resize(N*2);
		fill(all(val),0);
	}

	void add(int k, int a){
		k+=N;
		val[k]=a;
		while(k){
			k/=2;
			val[k]=val[k*2]+val[k*2+1];
		}
	}
	int sum(int a, int b){return sum(a,b,1,0,N);}
	int sum(int a, int b, int k, int l, int r){
		if(r<=a or l>=b) return 0;
		if(a<=l and r<=b) return val[k];
		int m=(l+r)/2;
		return sum(a,b,k*2,l,m)+sum(a,b,k*2+1,m,r);
	}	
};


