		r = T.insert(r, SUM(0, 1), 0);
	}
	rep(i, 0, q) {
		std::cin >> com >> x >> y;
		if (com == 0) {
			y = y + T.access(r, x - 1)->value.e;
			r = T.erase(r, x - 1);
			//T.show(r);
