int getSum(int x, int y, int id, int nx, int ny){//a_xからa_yまでのsum,今はseg[id],seg[id] = a_nxからa_nyのsum
	if((ny <= x) || (y <= nx))//今いるところが完全範囲外
		return 0;

	if((x <= nx) && (ny <= y))//完全範囲内
		return seg[id];
	else{//一部範囲内
		int left = getSum(x, y, 2 * id + 1, nx, (nx + ny) / 2);
		int right = getSum(x, y, 2 * id + 2, (nx + ny) / 2, ny);
		return left + right;
	}

}


