class BIT
{
    private:
        vi node;
        int n;
    public:
        BIT(int n_) {
            n = n_;
            node.resize(n + 1);
        }

        void add(int i, int x) {
            while (i <= n) {
                node[i] += x;
                i += (i & (-i));
            }
        }

        int sum(int i) {
            int sum = 0;
            while (i > 0) {
                sum += node[i];
                i -= (i & (-i));
            }
            return sum;
        }

        int sum(int a, int b) {
            return sum(b) - sum(a - 1);
        }
};

