struct SegTree {
    int n;
    vi v;

    int pow2fit(int sz){
        int ret = 1;
        while(ret < sz) ret *= 2;
        return ret;
    }

    SegTree(int sz){
        n = pow2fit(sz);
        v = vi(2 * n - 1);
    }

    // v[a] = x
    int update(int a, int x){
        int idx = n - 1 + a;
        v[idx] = x;

        while(idx > 0){
            idx = (idx - 1) / 2;
            v[idx] = v[2 * idx + 1] + v[2 * idx + 2];
        }
    }

    // sum [a, b)
    int getsum(int a, int b, int k = 0, int l = 0, int r = -1){
        if(r < 0) r = n;

        if(a >= r or l >= b) return 0;
        if(a <= l and r <= b) return v[k];

        return getsum(a, b, 2 * k + 1, l, (l + r) / 2) 
             + getsum(a, b, 2 * k + 2, (l + r) / 2, r);
    }
};

