typedef long long int ll;

class RSQ{
	public:
	int n;
	vector<ll> dat;
	RSQ(){}
	RSQ(int size){
		n = 1;
		while(n < size) n *= 2;
		dat.resize(2 * n - 1, 0);
	}
	void add(int k, ll a){
		k += n - 1;
		dat[k] += a;
		while(k > 0){
			k = (k - 1) / 2;
			dat[k] += a;
		}
	}
	ll getSum(int s, int t){
		return query(s, t + 1, 0, 0, n);
	}
	ll query(int a, int b, int k, int l, int r){
		if(r <= a || b <= l) return 0;
		if(a <= l && r <= b) return dat[k];
		else{
			ll vl = query(a, b, 2 * k + 1, l, (l + r) / 2);
			ll vr = query(a, b, 2 * k + 2, (l + r) / 2, r);
			return vl + vr;
		}
	}
};

