struct Query{
  int c, x, y;
  Query(int c, int x, int y) : c(c), x(x), y(y){}
};

vector<Query> query;

#define SEG_LEN (1 << 18) 

int seg[SEG_LEN * 2];

void  add(int i, int x){
  i += SEG_LEN;
  seg[i] += x;
  while(true){
    i /= 2; 
    if(i == 0)break; 
    seg[i] = seg[i * 2] + seg[i * 2 + 1]; // ノードiの左右の子ノードの番号はそれぞれ 2i, 2i + 1
  }
}

int getSum(int l, int r){
  l += SEG_LEN;
  r += SEG_LEN;
  int ans = 0;
  while(l < r){ 
    if(l % 2){
      ans += seg[l];
      ++l; 
    }
    l /= 2;
    if(r % 2){
      ans += seg[r - 1];
      r--;
    }
    r /= 2;
  }
  return ans;
}

int main(){
  int n, q;
  cin >> n >> q;
  for(int i = 0; i < q; ++i){
    int c, x, y;
    cin >> c >> x >> y;
    query.push_back(Query(c, x, y));
  }

  for(auto qry : query){
    if(qry.c == 0)add(qry.x, qry.y);
    else cout << getSum(qry.x, qry.y + 1) << endl;
  }

  return 0;
}

