class SqrtDecomposition{
private:
    int n; //元の配列のサイズ
    int sz; //1つのバケットが担当する区間の長さ
    int num; //バケットの個数
    vector<int> v,bucket;
    int init;

    int combine(int a, int b){
        //return min(a,b);
        //return max(a,b);
        return a+b;
    }

    int idx(int i){
        return i/sz;
    }
    void build(){
        sz = sqrt(n);
        num = (n + sz-1)/sz;
        bucket = vector<int>(num,init);
        //bucketの更新
        for(int i = 0; i < n; i++){
            bucket[idx(i)] = combine(bucket[idx(i)], v[i]);
        }
    }
    void recalc(int id){
        bucket[id] = init;
        for(int i = id*sz; i < min((id+1)*sz,n); i++){
            bucket[id] = combine(bucket[id], v[i]);
        }
    }
public:
    SqrtDecomposition(){
    }
    SqrtDecomposition(int size, int initial){
        n = size;
        init = initial;
        v = vector<int> (n,init);
        build();
    }
    SqrtDecomposition(vector<int> in, int initial){
        n = in.size();
        init = initial;
        v = in;
        build();
    }
    void update(int ind, int x){
        //v[ind]をxに変更する
        v[ind] = x;
        recalc(idx(ind));
    }
    void add(int ind, int x){
        //v[ind]にxを足す
        v[ind] += x;
        recalc(idx(ind));
    }
    int query_min(int l, int r){
        //[l,r)の最小値を求める
        int ret = init;
        int lid = idx(l);
        int rid = idx(r);
        if(lid == rid){
            for(int i = l; i < r; i++){
                ret = min(ret, v[i]);
            }
            return ret;
        }
        for(int i = l; i < (lid+1)*sz; i++){
            ret = min(ret, v[i]);
        }
        for(int i = lid+1; i < rid; i++){
            ret = min(ret, bucket[i]);
        }
        for(int i = rid*sz; i < r; i++){
            ret = min(ret, v[i]);
        }
        return ret;
    }
    int query_sum(int l, int r){
        //[l,r)の総和を求める
        int ret = init;
        int lid = idx(l);
        int rid = idx(r);
        if(lid == rid){
            for(int i = l; i < r; i++){
                ret += v[i];
            }
            return ret;
        }
        for(int i = l; i < (lid+1)*sz; i++){
            ret += v[i];
        }
        for(int i = lid+1; i < rid; i++){
            ret += bucket[i];
        }
        for(int i = rid*sz; i < r; i++){
            ret += v[i];
        }
        return ret;
    }
    void show(){
        cout << endl;
        cout << "n = " << n;
        cout << ", sz = " << sz;
        cout << ", num = " << num;
        cout << endl;
        cout << "v:";
        for(int i = 0; i < n; i++)cout << " " << v[i];cout << endl;
        cout << "bucket:";
        for(int i = 0; i < num; i++)cout << " " << bucket[i];cout << endl;
        cout << endl;
    }
};


