struct BIT {
    vector<int> data;
    int n;
    BIT(int n) : data(n+1), n(n+1) {}

    void update(int i,int x){
        for(; i <= n; i += i & -i) data[i] += x;
    }

    int query(int i){
        int ret = 0;
        for(; i > 0; i -= i & -i) ret += data[i];
        return ret;
    }
};

