  if(b==1){
    return a;
  }else if(b==0){
    return 1;
  }
  static int modmode=0;//%d9_7するのかどうか
  if(b%2==1){
    ll tmp = digitpower(a,(b-1)/2);
    if(modmode==1){
      tmp%=d9_7;
    }
    tmp*=tmp;
    if(modmode==1){
      tmp%=d9_7;
    }
    tmp*=a;
    if(modmode==1){
     return (tmp)%d9_7;
