	update_list.push_back(query{ x, y });
}

inline void update(int x) {
	if (x < min_updated)
		return;
	min_updated = 100001;

	sort(begin(update_list), end(update_list));
	int sum = 0;
	int sum_index = 1;
	for (query it : update_list) {
		while (sum_index < it.x) {
			dat[sum_index] += sum;
			sum_index = sum_index + sum_index&(-sum_index);
		}
		while (sum_index > it.x) {
			dat[it.x] += it.y;
			it.x += it.x & (-it.x);
		}
		//sum_index == it.x
		sum += it.y;
	}
	update_list.clear();
	while (sum_index <= n) {
		dat[sum_index] += sum;
		sum_index += sum_index&(-sum_index);
	}
}

