struct BIT {
    int size;
    int pow2_less;
    vi data;

    BIT(int N) : size(N + 1), data(N + 1, 0) {
        pow2_less = 1;
        while ((pow2_less << 1) <= size) {
            pow2_less <<= 1;
        }
    }

    // 1-indexed
    void add(int idx, int value) {
        while (idx < size) {
            data[idx] += value;
            idx += idx & -idx;
        }
    }

    // 1-indexed
    int sum(int idx) {
        int ret = 0;
        while (idx > 0) {
            ret += data[idx];
            idx -= idx & -idx;
        }
        return ret;
    }

    // sum(x) >= value となる最小のxを返す
    int lower_bound(int value) {
        if (value <= 0) {
            return 0;
        }
        int pos = 0;
        for (int k = pow2_less; k > 0; k >>= 1) {
            if (pos + k < size && data[pos + k] < value) {
                value -= data[pos + k];
                pos += k;
            }
        }
        return pos + 1;
    }
};

