ostream& operator<<(ostream& os, const Seg<T> &seg){ return os<<"("<<seg.s<<")";}

template<class Seg>
struct SegTree{
	vector<Seg> segs;

	void upd_node(int k){segs[k]=segs[2*k+1]+segs[2*k+2];}
	Seg query(int l,int r,int k,int a,int b){
		if(b<=l || r<=a)return Seg::e; 
		if(l<=a && b<=r){return segs[k];}
		int m=(a+b)/2;
		Seg vl=query(l,r,2*k+1,a,m);
		Seg vr=query(l,r,2*k+2,m,b);
		upd_node(k);
		return vl+vr;
	}
	void add(int k,const Seg &seg){
		k+=segs.size()/2-1;
		segs[k]=segs[k]+seg;
		while(k>0){
			k=(k-1)/2;
			upd_node(k);
		}
	}
	void upd(int k,const Seg &seg){
		k+=segs.size()/2-1;
		segs[k]=seg;
		while(k>0){
			k=(k-1)/2;
			upd_node(k);
		}
	}
	struct Updater{
		SegTree &st;
		int k;
		Seg operator+=(const Seg &seg){ st.add(k,seg);}
		Seg operator=(const Seg &seg){ st.upd(k,seg);}
	};

	SegTree(int n){
		int pw=1;
		while(pw<n) pw*=2;
		segs.resize(2*pw);
	}
	Seg operator()(int l,int r){ return query(l,r,0,0,segs.size()/2);};
	Updater operator[](int k){ return Updater{*this,k};}
};

