        ++i;
        while(i <= sz){
            data[i] += x;
            i += i & - i;
        }
        return;
    }

    int getSum(int i){
        ++i;
        int res = 0;
        while(i > 0){
            res += data[i];
            i -= i & -i;
        }
        return res;
    }

    int getSum(int l, int r){
        return getSum(r) - getSum(l - 1);
    }
};

