  int n,q;
  cin>>n>>q;
  init(n);
  while(q--){
    int com,x,y;
    cin>>com>>x>>y;
    if(com){
      cout<<rangemin(x,y+1,0,0,::n)<<endl;
    }else{
      rangeadd(y,x,x+1,0,0,::n);
    }
  }
}

