using namespace std;

class SegTree {
public:
    int m_n;
    vector<int> m_data;

    SegTree( int n ) { Init( n ); }

    void Init( int n ) {

	m_n = 1;
	while ( m_n < n ) m_n <<= 1;

	m_data.resize( 2*m_n - 1 );
    }

    void Add( int k, int val ) {

	k += m_n - 1;

	m_data[k] += val;

	while ( k > 0 ) {
	    k = ( k - 1 )/2;
	    m_data[k] = m_data[2*k+1] + m_data[2*k+2];
	}
    }

    int Sum( int a, int b ) {
	return query( a, b + 1, 0, 0, m_n );
    }

protected:

    int query( int a, int b, int k, int l, int r ) {

	if ( b <= l || a >= r ) return 0;

	if ( a <= l && r <= b ) return m_data[k];

	int left = query( a, b, 2*k+1, l, (l+r)/2 );
	int right = query( a, b, 2*k+2, (l+r)/2, r );

	return left + right;
    }

};


