        update_node(parent(node_index),value);
    }
    // [a,b)に対して答える

    ll query(int a, int b, int k, int l, int r) {
        // std::cout << l<<" "<<r << std::endl;
        if (r <= a || b <= l){
            return 0;
        }
        if (a <= l && r <= b){
            return node[k]; // ノード k の担当範囲がクエリ区間 [a, b) に完全に含まれる
        }else {
            // 一部だけ範囲が被る場合は左右の子に委託する
            ll c1 = query(a, b, 2 * k + 1, l, (l + r) / 2); // 左の子に値を聞く
            ll c2 = query(a, b, 2 * k + 2, (l + r) / 2, r); // 右の子に値を聞く
            return c1+c2; // 左右の子の値の min を取る
        }
    }

    int parent(int node_index){
        return (node_index-1)/2;
    }
    int convert(int origin){
        return origin    +(int)(pow(2,cou-1)-1);
    }
    int rconvert(int node_index){
        return node_index-(int)(pow(2,cou-1)-1);
    }
    int child1( int node_index){
        return node_index*2+1;
    }
};

int main(void){
    ll n,q;
    std::cin >> n>>q;
    SegmentTree seg(n,0);

    for (int i = 0; i < q; i++) {
        int c,x,y;
        std::cin >> c>>x>>y;

        if(c==0){
            x--;
            seg.update(x,y);
        }else{
            x--;y--;
            std::cout << seg.query(x,y+1,0,0,seg.size/2) << std::endl;
        }
    }
}

