}

void add(int x, int y){
	x += N-1;
	dat[x] += y;
	while(x > 0){
		x = (x-1)/2;
		dat[x] += y;
	}
}

int getSum(int a, int b, int t, int r, int l){
	if(a >= l || b <= r) return 0;
	if(a <= r && l <= b) return dat[t];
	return getSum(a,b,t*2+1,r,(r+l)/2)+getSum(a,b,t*2+2,(r+l)/2,l);
}

