template<class T,class F,class G>
inline void prseg<T,F,G>::open(int siza){
	siz=1;
	hgt=0;
	while(siz<siza){
		siz*=2;
		++hgt;
	}
	siz=siza;
	node=siz-1;
	int n=node+siz;
	dat=new T[n];
	for(int i=0;i<n;++i) dat[i]=id;
	return;
}
template<class T,class F,class G>
inline void prseg<T,F,G>::close(void){
	siz=hgt=node=0;
	delete[] dat;
	dat=nullptr;
	return;
}
template<class T,class F,class G>
inline void prseg<T,F,G>::put(int num,T val){
	num+=node;
	dat[num]=appg(val,dat[num]);
	int h=num<(1<<hgt)-1?hgt-1:hgt;
	for(int i=0;i<h;++i){
		num=(num-1)/2;
		dat[num]=appf(dat[num*2+1],dat[num*2+2]);
	}
	return;
}
template<class T,class F,class G>
inline T prseg<T,F,G>::get(int first,int last){
	first+=node;
	last+=node;
	T x=id;
	while(first<last){
		if(!(first&1)) x=appf(dat[first],x);
		if(!(last&1)) x=appf(dat[--last],x);
		first/=2;
		last/=2;
	}
	return x;
}
template<class T,class F,class G>
inline void prseg<T,F,G>::set(int num,T val){
	dat[num+node]=val;
	return;
}
template<class T,class F,class G>
inline void prseg<T,F,G>::build(void){
	int d=node;
	for(int k=(1<<hgt-1)-1;k<d;++k) dat[k]=appf(dat[k*2+1],dat[k*2+2]);
	for(int i=hgt-2;i>=0;--i){
		d=(1<<i+1)-1;
		for(int k=(1<<i)-1;k<d;++k) dat[k]=appf(dat[k*2+1],dat[k*2+2]);
	}
	return;
}
