struct Node{
	int data;

	Node(int data) : data(data) {}

	Node operator*(const Node r) const{return Node(data + r.data);}
} e(0);

struct SqrtDecomposition{
	vector<Node> data;
	vector<Node> bucket;
	int N, K;

	SqrtDecomposition(int n) : N(n){
		K = (N + sqrtN - 1) / sqrtN;
		data.assign(K * sqrtN, e);
		bucket.assign(K, e);
	}

	void add(int k, int x){
		data[k] = data[k] * Node(x);
		k = k / sqrtN;

		Node ret = e;
		for(int i = k * sqrtN; i < (k + 1) * sqrtN; i++) ret = ret * data[i];
		bucket[k] = ret;
	}

	int get(int a, int b){
		int L = a / sqrtN, R = (b + sqrtN - 1) / sqrtN;
		Node ret = e;
		for(int k = L; k < R; k++){
			int l = k * sqrtN, r = (k + 1) * sqrtN;

			if(a<=l&&r<=b) ret = ret * bucket[k];
			else for(int i = max(a, l); i < min(b, r); i++) ret = ret * data[i];
		}

		return ret.data;
	}
};

