struct SegmentTree {
    vector<int> node;
    int n = 1;

    explicit SegmentTree(int sz) {
        while (n < sz) {
            n *= 2;
        }

        node.resize(2 * n - 1);
    }

    void Update(int k, int a) {
        k += n - 1;
        node[k] += a;

        while (k > 0) {
            k = (k - 1) / 2;

            node[k] = node[k * 2 + 1] + node[k * 2 + 2];
        }
    }

    void GetSum(int a, int b, long long int &sum, int k = 0, int l = 0, int r = -1) {
        if (r < 0) {
            r = n;
        }

        if (r <= a || b <= l) {
            return;
        }
        if (a <= l && r <= b) {
            sum += node[k];
            return;
        }

        GetSum(a, b, sum, k * 2 + 1, l, (l + r) / 2);
        GetSum(a, b, sum, k * 2 + 2, (l + r) / 2, r);
    }
};

