struct BinaryIndexedTree {
  BinaryIndexedTree(int n) : n(n), v(n + 1, 0) {}

  int n;
  vector<int> v;

  int sum(int k) {
    int ret = 0;
    for (; k; k -= k & -k) ret += v[k];
    return ret;
  }

  void add(int k, int x) {
    for (; k <= n; k += k & -k) v[k] += x;
  }
};

int main() {
