template <typename T>
struct BIT {
    vector<T> array;
    T UNITY_SUM = 0;

    BIT(int n) { init(n); }

    void init(int n) {
        array.resize(n + 1);
        for (int i = 0; i < array.size(); i++) {
            array[i] = UNITY_SUM;
        }
    }

    void add(int a, T x) {
        a += 1;
        for (int i = a; i < array.size(); i += i & -i) {
            array[i] = array[i] + x;
        }
    }

    T _sum(int a) {
        a += 1;
        T res = UNITY_SUM;
        for (int i = a; i > 0; i -= i & -i) {
            res = res + array[i];
        }

        return res;
    }

    T sum(int a, int b) {
        return _sum(b - 1) - _sum(a - 1);
    }
};

