int sT[4*100000];

void u(int v , int l , int r , int x , int val)
{
	if(x < l || x >= r)
	{
		return;
	}
	if( (r - l) == 1)
	{
		sT[v] += val;
		return;
	}else
	{
		int m = (l+r)/2;
		u(2*v,	l,m ,x,val);
		u(2*v+1,m,r,x,val);
		sT[v] += val;
	}
}
int q(int v , int l , int r , int i , int j)
{
	if(j < l || i >= r)
	{
		return 0;
	}
	else if(i <= l && r-1 <= j)
	{
		return sT[v];
	}else
	{
		int m = (l+r)/2;
		return (q(2*v , l , m , i , j) + q(2*v+1 , m , r , i , j));
	}
}

