#define SLICE(f,c,l,r,...) (([&](decltype((c)) cc, decltype((l)) ll, decltype((r)) rr) {\
    auto ii = ll <= rr ? begin(cc)+ll : end(cc);\
    auto jj = ll <= rr ? begin(cc)+rr : end(cc);\
    return (f)(ii, jj, ## __VA_ARGS__);\
})(c,l,r))

struct SqrtDecomposition {
    i64 rn_;
    vector<i64> data_;
    vector<i64> buckets_;

    explicit SqrtDecomposition(i64 rn)
        : rn_(rn),
          data_(rn_*rn_, 0),
          buckets_(rn, 0)
    {}

    void add(i64 i, i64 x) {
        data_[i] += x;
        i64 bi = i / rn_;
        buckets_[bi] += x;
    }

    i64 sum(i64 i, i64 n) {
        i64 l  = i;
        i64 r  = i+n;
        i64 bl = l / rn_;
        i64 br = r / rn_;

        i64 res = 0;
        res += SLICE(accumulate, buckets_, bl+1, br, 0LL);
        if(bl == br) {
            res += SLICE(accumulate, data_, l, r, 0LL);
        }
        else {
            res += SLICE(accumulate, data_, l, (bl+1)*rn_, 0LL);
            res += SLICE(accumulate, data_, br*rn_, r, 0LL);
        }
        return res;
    }
};

i64 N;

void solve() {
    SqrtDecomposition sd(1000);

    i64 Q; RD(Q);
    REP(_, Q) {
        i64 cmd; RD(cmd);
        if(cmd == 0) {
            i64 i; RD(i); --i;  // 0-based
            i64 x; RD(x);
            sd.add(i, x);
        }
        else if(cmd == 1) {
            i64 s,t; RD(s); RD(t); --s; --t;  // 0-based
            assert(s <= t);
            i64 n = t-s+1;
            i64 ans = sd.sum(s, n);
            PRINTLN(ans);
        }
        else {
            assert(false);
        }
    }
}

signed main() {
    RD(N);

    solve();

    return 0;
}

