template<typename T>
struct dynamic_segment{
    vector<T>node;
    vector<int>used;
    int sz=1,n;
    dynamic_segment(int n):n(n){
        while(sz<n)sz*=2;
        node.resize(sz*2,0);
    }
    void add(int64_t x,T val){
        x+=sz;
        while(x){
            node[x]+=val;
            used.push_back(x);
            x/=2;
        }
    }
    T get(int64_t l,int64_t r){
        l+=sz;r+=sz;
        T res=0;
        while(l<r){
			if(l&1)res+=node[l++];
			if(r&1)res+=node[--r];
			l/=2;r/=2;
		}
        return res;
    }
    void clear(){
        for(auto e:used)node[e]=0;
        used.clear();
    }
};

