  for (int i=1; i<=n; i++) {
    A[i]=0;
  }
}
void add(int i,int x) {
  while (i<=n) {
    A[i]+=x;
    i+=i&(-i);
  }
}
ll getSum(int s,int t) {
  ll sumt=0;
  while (t) {
    sumt+=A[t];
    t-=t&(-t);
  }
  ll sums=0;
  s-=1;
  while (s) {
    sums+=A[s];
    s-=s&(-s);
  }
  ll sum=sumt-sums;
  return sum;
}
