template<typename T> class SQRTdecomposition{
public:
    vector<T> data, backet;
    int sz,backet_size,backet_cnt;
    SQRTdecomposition(vector<T>& v) : data(v){
        sz = (int)data.size();
        backet_size = (int)sqrt(sz);
        backet_cnt = (sz + backet_size - 1) / backet_size;
        backet.resize(backet_cnt);
        rep(i,sz){
            backet[i / backet_size] += data[i];   //例えば和を持たせる処理
        }
    }
    void update(int l, int k){
        data[l] += k;
        backet[l / backet_size] += k;
    }
    T query(int l, int r){    //[l.r)
        T res = 0;
        // 同じバケット内にある
        if(l / backet_size == (r-1) / backet_size){
            for(int i = l; i < r; i++){
                res += data[i];
            }
        }else{
            // 完全に被っているバケット
            for(int i = (l + backet_size - 1) / backet_size; i < r / backet_size; i++){
                res += backet[i];
            }
            // 中途半端な左側のバケット
            if(l % backet_size){
                for(int i = l; i < backet_size*(l / backet_size + 1); i++){
                    res += data[i];
                }
            }
            // 中途半端な右側のバケット
            if(r % backet_size){
                for(int i = r - r % backet_size; i < r; i++){
                    res += data[i];
                }
            }
        }
        return res;
    }
};

int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n,q;
    cin >> n >> q;
    vi a(n,0);
    SQRTdecomposition<int> sr(a);
    rep(i,q){
        int a,b,c;
        cin >> a >> b >> c;
        if(a == 0){
            sr.update(b-1,c);
        }else{
            cout << sr.query(b-1,c) << "\n";
        }
    }
    return 0;
}

