template<class T>
struct FenwickTree {
  using size_t = std::size_t;
  T e; size_t n; std::vector<T> dat;
  FenwickTree() {}
  FenwickTree(T e, size_t n_=0) : e(e), n(n_), dat(n_+1, e) {}
  void add(size_t k, T v) { for(++k;k<dat.size();k+=k&-k) dat[k] += v; }
  T sum(size_t k) { T r=e; for(;k>0;k-=k&-k) r += dat[k]; return r; } // [0, k)
};
template<class T> auto make_bit(T e, std::size_t n=0) { return FenwickTree<T>(e, n); }



