template<class T>
struct BinaryIndexedTree {
	const int n;
	vector<T> v;
	BinaryIndexedTree(int n) : n(n), v(n, 0) {}
	void add(int i, T x) {
		for (; i < n; i |= i + 1)
			v[i] += x;
	}
	// [0, i)
	T sum(int i) {
		T r = 0;
		for (--i; i >= 0; i = (i & (i + 1)) - 1)
			r += v[i];
		return r;
	}
	// [l, r)
	T sum(int l, int r) {
		return sum(r) - sum(l);
	}
};

