struct SegmentTree {
   using F = function<ll(ll, ll)>;
   const F f;
   const ll M;

   int size;
   vector<ll> data;

   SegmentTree(int n, const F& f, const ll& M) : f(f), M(M) {
      size = 1;
      while (size < n) size <<= 1;
      data.assign(size * 2, M);
   }

   void set(int i, ll x) {
      data[i + size] = x;
   }

   void init() {
      for (int k = size - 1; k > 0; --k) {
         data[k] = f(data[2 * k], data[2 * k + 1]);
      }
   }

   void update(int i, ll x, F f2) {
      i += size;
      data[i] = f2(data[i], x);
      while (i >>= 1) {
         data[i] = f(data[2 * i], data[2 * i + 1]);
      }
   }

   ll query(int l, int r) {
      ll L = M, R = M;
      l += size, r += size;
      while (l < r) {
         if (l & 1) L = f(L, data[l]);
         if (r & 1) R = f(R, data[r - 1]);
         l = (l + 1) / 2;
         r = r / 2;
      }
      return f(L, R);
   }
};

int main() {
   cin.tie(0);
   ios::sync_with_stdio(false);

   auto f = [](ll l, ll r) { return l + r; };
   int n, q;
   cin >> n >> q;
   SegmentTree seg(n, f, 0);
   rep(i, q) {
      int t, x, y;
      cin >> t >> x >> y;
      if (t) cout << seg.query(x, y + 1) << endl;
      else seg.update(x, y, f);
   }
}

