template<typename Monoid>
class SegmentTree {
  using F = function<Monoid(Monoid, Monoid)>;
  int n, sz;
  vector<Monoid> a;
  const F f;
  const Monoid m;
public:
  SegmentTree(int n, const F f, const Monoid& m) : n(n), sz(1), f(f), m(m) {
    while (sz < n) sz <<= 1;
    a.resize(2 * sz - 1, m);
  }
  void update(int i, const Monoid& x) {
    i += sz - 1;
    a[i] = x;
    while (i) {
      i = (i - 1) >> 1;
      a[i] = f(a[(i << 1) + 1], a[(i << 1) + 2]);
    }
  }
  Monoid query(int l, int r) {
    Monoid vl(m), vr(m);
    for (l += (sz - 1), r += (sz - 1); l < r; l >>= 1, r >>= 1) {
      if (!(l & 1)) vl = f(vl, a[l]);
      if (!(r & 1)) vr = f(vr, a[--r]);
    }
    return f(vl, vr);
  }
  Monoid operator[](int i) const {
    return a[sz + i - 1];
  }
  vector<Monoid> data() const {
    return vector<Monoid>(a.begin() + sz - 1, a.begin() + sz + n - 1);
  }
  friend ostream& operator<<(ostream& o, const SegmentTree& s) {
    o << s.data();
    return o;
  }
};

