using namespace std;

const long long sqrtN = 512;
struct SqrtDecomposition {
  long long N, K;
  vector<long long> data;
  vector<long long> bucketSum;
  SqrtDecomposition(long long n) : N(n) {
    K = (N + sqrtN - 1) / sqrtN;
    data.assign(K * sqrtN, 0);
    bucketSum.assign(K, 0);
  }
  void add(long long x, long long y) {
    long long k = x / sqrtN;
    data[x] += y;
    long long sum = 0;
    for (long long i = k * sqrtN; i < (k + 1) * sqrtN; ++i) {
      sum += data[i];
    }
    bucketSum[k] = sum;
  }
  // [x, y)
  long long getSum(long long x, long long y) {
    long long sum = 0;
    for (long long k = 0; k < K; ++k) {
      long long l = k * sqrtN, r = (k + 1) * sqrtN;
      if (r <= x || y <= l)
        continue;
      if (x <= l && r <= y) {
        sum += bucketSum[k];
      } else {
        for (long long i = max(x, l); i < min(y, r); ++i) {
          sum += data[i];
        }
      }
    }
    return sum;
  }
};

