	while(q--) {
		int type,x,y;cin>>type>>x>>y;
		if(type==0) {
			x--;
			tree.update(x,y);
		}
		else {
			x--;
			cout<<tree.query(x,y)<<endl;
		}
	}

	return 0;
}

