template<class T>
struct segment_tree {
	using value_type = T;
	using F = function<T(T, T)>;
private : 
	int n;
	const F f;
	const value_type ie;
	vector<value_type> node;

public : 
	segment_tree (const F &f, const value_type &ie) : f(f), ie(ie) { }

	void resize (int _n) noexcept {
		n = 1;
		while (n < _n) n <<= 1;
		node.resize(2 * n);
		fill(node.begin(), node.end(), ie);
	}

	void resize (int _n, const value_type &e) noexcept {
		n = 1;
		while (n < _n) n <<= 1;
		node.resize(2 * n);
		fill(node.begin(), node.end(), ie);
		for (int i = n; i < 2 * n; i++) node[i] = e;
		for (int i = n; i--> 0;) {
			node[i] = f(node[i << 1 | 0], node[i << 1 | 1]);
		}
	}

	template<class iter>
	void build (iter l, iter r) {
		resize(r - l);
		for (int i = n; l != r; i++, l++) node[i] = *l;
		for (int i = n; i--> 0;) {
			node[i] = f(node[i << 1 | 0], node[i << 1 | 1]);
		}
	}

	void set_val (int i, const value_type &x) {
		i += n;
		node[i] = x;
		for (i >>= 1; i > 0; i >>= 1) {
			node[i] = f(node[i << 1 | 0], node[i << 1 | 1]);
		}
	}

	constexpr value_type fold (int l, int r) {
		value_type vl = ie, vr = ie;
		for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
			if (l & 1) vl = f(vl, node[l++]);
			if (r & 1) vr = f(node[--r], vr);
		}
		return f(vl, vr);
	};

	constexpr const value_type& fold_all() const {
		return (node[1]);
	}

	constexpr const value_type& operator[] (int i) const {
		return node[i + n];
	}

};


int main() {
	int n, q;
	cin >> n >> q;
	auto f = [](const int &a, const int &b) { return (a + b); };
	segment_tree<int> seg(f, 0);
	seg.resize(n);

	while (q--) {
		int type;
		cin >> type;

		if (type == 0) {
			int i, x;
			cin >> i >> x;
			i--;
			seg.set_val(i, seg[i] + x);
		} else {
			int l, r;
			cin >> l >> r;
			l--; r--;
			cout << seg.fold(l, r + 1) << '\n';
		}
	}

	return 0;
}

