template <typename T>
struct BIT {
	int n; // num of elements(1-ind)
	T e; function<T(T, T)> op, inv;
	vector<T> a; // size: n+1
	void chop(T &x, T y) { x = op(x, y); }
	void chinv(T &x, T y) { x = inv(x, y); }
	BIT(int n_, T e_, function<T(T, T)> op_, function<T(T, T)> inv_) {
		n = n_; e = e_; op = op_; inv = inv_;
		a = vector<T>(n + 1, e);
	}
	BIT(vector<T> a_, T e_, function<T(T, T)> op_, function<T(T, T)> inv_) {
		BIT(a_.size(), e_, op_, inv_);
		rep(i, a_.size()) a[i + 1] = a_[i];
	}
	void operate(int i, T val) {
		for (; i <= n; i += i & -i) chop(a[i], val);
	}
	void update(int i, T val) {
		operate(i, val - get(i));
	}
	T range(int i) { // [1, i]
		T res = e;
		for (; i > 0; i -= i & -i) chop(res, a[i]);
		return res;
	}
	T get(int i, int j) { // [i, j]
		return inv(range(j), range(i - 1));
	}
	T get(int i) { // [i, i]
		return get(i, i);
	}
};

