struct RSQsq {

  /*　使い方まとめ　*/

  /*

  RSQsq myvec(n) // 宣言 nは必要な要素数
  myvec.add(i,k) // 配列のi番目に要素kを足す(更新ではないことに注意)
  myvec.at(i) // 配列のi番目にアクセス(0-index)
  myvec.rsum(i,j) // 配列の[i,j]の範囲の和を返す(0-index)

  */

  vector<int> data;
  vector<int> bucket;
  int sq;

  RSQsq(int n) {
    sq = sqrt(n);
    if(sq*sq==n) sq--;
    sq++;
    data = Vi(sq*sq,0);
    bucket = Vi(sq,0);
  }

  int at(int k) {
    return data[k];
  }

  void add(int i,int k) {
    int ib = i/sq;
    data[i] += k;
    bucket[ib] += k;
  }

  int rsum(int L,int R) {
    R++;
    int sum = 0;
    int dL,dR;

    rep(i,0,sq+1) {
      dL = i*sq;
      dR = (i+1)*sq;
      if(dR <= L || R <= dL) continue;
      if(L <= dL && dR <= R) sum += bucket[i];
      else {
        rep(j,max(L,dL),min(R,dR)) {
          sum += data[j];
        }
      }
    }
    return sum;
  }

  void debug(){
    Verr(data);
    Verr(bucket);
  }

};


