	int lt, rt, sum;

}tree[N << 2];

void buildTree(int p, int l, int r) {

	tree[p].lt = l;
	tree[p].rt = r;
	tree[p].sum = 0;

	if (l == r)return;

	int mid = (l + r) >> 1;

	buildTree(p << 1, l, mid);
	buildTree(p << 1 | 1, mid + 1, r);

	return;

}

int query(int p, int l, int r) {

	if (tree[p].lt == l && tree[p].rt == r)
		return tree[p].sum;

	int mid = (tree[p].lt + tree[p].rt) >> 1;

	if (r <= mid)
		return query(p << 1, l, r);
	if (l > mid)
		return query(p << 1 | 1, l, r);
	return query(p << 1, l, mid) + query(p << 1 | 1, mid + 1, r);

}

void add(int p, int x, int y) {

	tree[p].sum += y;

	if (tree[p].lt == tree[p].rt)
		return;

	int mid = (tree[p].lt + tree[p].rt) >> 1;

	if (x <= mid)
		add(p << 1, x, y);
	else
		add(p << 1 | 1, x, y);

	return;

}

