        n = (int)(v.size());
        node.resize(2*n);
        for(int i=0;i<n;i++) node[i+n] = v[i];
        for(int i=n-1;i>=0;i--) node[i] = node[i<<1] + node[i<<1|1];
    }
    //i番目の要素にxを足す
    void update(int i,long long x){
        i += n;
        node[i] += x;
        while(i>1){
            i >>= 1;
            node[i] = node[i<<1] + node[i<<1|1];
        }
