template<class T,class F>
struct SegTree{
	V(T) seg;
	size_t size;
	const F f;
	const T e;
	SegTree(const V(T)& d,F f,T e):f(f),e(e){
		int n=d.size();
		size=1;
		while(size<n)size<<=1;
		seg.resize(size*2-1,e);
		rep(i,n)seg[i+size-1]=d[i];
		gnr(i,0,size-2)u(i);
	}

	void u(int i){
		seg[i]=f(seg[i*2+1],seg[i*2+2]);
	}

	void set(int i,T x){
		i+=size-1;
		seg[i]=x;
		while(i){
      i=(i-1)/2;
      u(i);
    }
	}
	T get(int a,int b,int i,int l,int r){
		if(r<=a||b<=l)return e;
		if(a<=l&&r<=b)return seg[i];
		int m=(l+r)/2;
		return f(get(a,b,i*2+1,l,m),get(a,b,i*2+2,m,r));
	}
	T get(int a,int b){
		return get(a,b,0,0,size);
	}
  T operator[](const int &i)const{
    return seg[i+size-1];
  }
};
template<class T,class F>
SegTree<T,F> segtree(const V(T)& d,F f,T e){
	return SegTree<T,F>(d,f,e);
}

