void add(int x, int val,vector<int>& bit)
{
	int N = bit.size() - 1;
	while (x <= N) {
		bit[x] += val;
		x += x & -x;
	}
}

int sum(int x,vector<int>& bit)
{
	int ret = 0;
	while (x) {
		ret += bit[x];
		x &= (x - 1);
	}

	return (ret);
}

