//RMQ_Segment_Tree
int initial = 0;
int N, dat[1000000];
void init(int n_){
	N = 1;
	while(N<=n_)N *= 2;
	for(int i = 1; i<=2*N; ++i)dat[i] = initial;
}

void update(int k, int a){
	k += N-1;
	dat[k] += a;
	while(k>0){
		k /= 2;
		dat[k] = dat[k*2] + dat[k*2+1];
	}
}

int query(int a, int b, int k, int l, int r){
	if(r <= a || b <= l)return initial;
	if(a <= l && r <= b)return dat[k];
	else{
		int vl = query(a, b, k*2, l, (l+r)/2);
		int vr = query(a, b, k*2+1, (l+r)/2, r);
		return vl+vr;
	}
}

