  ll bit[MAX_N+1],n;
  BIT(ll N){
	fill_n(bit,MAX_N+1,0);
	n=N;
  }

  //sum[1,r]
  ll sum(ll i){
	ll s=0;
	while(i>0){
	  s+=bit[i];
	  i-=i&-1;
	}
	return s;
  }

  //sum[l,r]
  ll lrsum(ll l,ll r){
	return sum(r)-sum(l-1);
  }

  //a_i=x
  void add(ll i,ll x){
	while(i<=n){
	  bit[i]+=x;
	  i+=i&-i;
	}
  }

};

