template<typename T> class fenwick {
  public:
  vector<T> fenw;
  int n;  
  fenwick(int _n) : n(_n) {
    fenw.resize(n);
  }
  void modify(int x, T v) {
    while (x < n) {
      fenw[x] += v;
      x |= (1 + x);
    }
  }
  T get(int x) {
    T v{};
    while (x >= 0) {
      v += fenw[x];
      x = (x & (x + 1)) - 1;
    }
    return v;
  }
  T get(int a, int b) {
    if (a > 0) {
      return get(b) - get(a - 1);
    } else {
      return get(b);
    }
  }
};

