class SegmentTree {
 private:
  vector<ll> nodes;
  ull size;
  function<ll(ll, ll)> fn;

 public:
  SegmentTree(ull size, function<ll(ll, ll)> fn = [](ll a, ll b) { return a + b; }) {
    // size 以上の最小の2べき
    ll sz = 1;
    while (sz <= size) sz <<= 1;
    this->size = sz;

    this->nodes = vector<ll>(this->size * 2, 0);
    this->fn = fn;
  }

  optional<ll> get(ull from_i, ull to_i, ull k = 1, ll l = 0, ll r = -1) {
    if (r < 0) r = size;

    // 被覆してる
    if (from_i <= l && r <= to_i) return nodes[k];
    // 関係ない
    if (r <= from_i || to_i <= l) return none;

    // 子からもらう
    optional<ll> left = get(from_i, to_i, k * 2, l, (l + r) / 2);
    optional<ll> right = get(from_i, to_i, k * 2 + 1, (l + r) / 2, r);

    if (left && right) return (*left) + (*right);
    if (left) return *left;
    if (right) return *right;
    return none;
  }

  void add(ull i, ll value) {
    ll k = size + i;

    nodes[k] = fn(nodes[k], value);
    k /= 2;
    while (k > 0) {
      nodes[k] = fn(nodes[k * 2], nodes[k * 2 + 1]);
      k /= 2;
    }
  }
};

