//for range sum query
struct fenwick_tree{
  //0-indexed
  //1-indexed用のコードを0-indexedに落とし込む処理をしているため、可読性がちょっと低い

  // nは元の配列且つBITのサイズ。
  // BITでは、元の配列と同じサイズの配列で管理できる。
  ll n;
  // bitを格納する配列
  vector<ll> bit;
  fenwick_tree(int sz){
    n = sz;
    // bitをサイズn, 値を0で初期化。
    bit.assign(sz,0);
  }
  //add a-th factor w;
  void add(ll a,ll w){
    //0-indexedで入ってきたaをa+1にして、1-indexedに
    //そして各値にアクセスするときだけindexを1減らす
    for(ll i=a+1;i<=n;i+=i&-i) bit[i-1] += w;
  }
  //return sum [0,a)
  ll sum(ll a){
    ll res = 0;
    //0-indexedで入ってきたaをa+1にするが、半開区間なのでa+1-1=aになる
    for(ll i=a;i>0;i-=i&-i) res += bit[i-1];
    return res;
  }
  //return sum [a,b)
  ll sum(ll a,ll b){
    return sum(b)-sum(a);
  }
};

