struct FenwickTree {
    int length;
    vector<int> node;
    FenwickTree (int N) : length(N), node(length + 1, 0) {}
    void add(int idx, int val) {
        ++idx;
        while (idx <= length) {
            node[idx] += val;
            idx += (idx & (-idx));
        }
    }
    int getsum(int idx) {
        int ans = 0;
        while (idx) {
            ans += node[idx];
            idx -= (idx & (-idx));
        }
        return ans;
    }
};

