class BIT {
		vector<int> dat;
		int const N;
	public:
		BIT(int N) : N(N), dat(N+1, 0) {}
		void add(int k, int a) {
			while (k <= N) {
				dat[k] += a;
				k += k & -k;
			}
		}
		int sum(int k) {
			int res = 0;
			while (k >= 1) {
				res += dat[k];
				k -= k & -k;
			}
			return res;
		}
};

