template<typename T>
struct BIT {
  vector<T> tree;

  BIT(int size) : tree(size + 1, 0) {};

  T sum(int a) {
    T res = 0;
    ++a;
    while (a) {
      res += tree[a];
      a -= a & -a;
    }
    return res;
  }

  T add(int a, int x) {
    ++a;
    while (a < tree.size()) {
      tree[a] += x;
      a += a & -a;
    }
  }
};

