  void init(int n, int m)
  {
    N = n;
    bit.resize(n + 1);
    for (int i = 0; i < bit.size(); i++)
    {
      bit[i] = m;
    }
  }

  int64_t sum(int i)
  {
    T s = 0;
    while (i > 0)
    {
      s += bit[i];
      i -= i & -i;
    }
    return s;
  }

  void add(int i, T x)
  {
    while (i <= N)
    {
      bit[i] += x;
      i += i & -i;
    }
  }
};

int main()
{
