namespace Fenwicks{
    template<typename T> class Fenwick{
    public:
        int size;vector<T> bit;
        Fenwick():Fenwick(0){}
        Fenwick(int n):size(n){bit = vector<T>(n+1);}
        T sum(int n){// [0,n)
            T s=0;
            while(n>0){
                s+=bit[n];
                n-=n&-n;//low
            }
            return s;
        }
        void add(int i,T x){//[0,...i...,n)
            i++;
            while(i<=size){
                bit[i]+=x;
                i+=i & -i;//next
            }
        }

        //lib
        T sum(int a,int b){// [a,b)
            return sum(b)-sum(a);
        }
    };
}
using namespace Fenwicks;

namespace Fenwicks{

    // [l,r)に v を足す
    //↑[l,r)のsumに対して d(x)=v*(x-l)+v=v*x -v*l+v のグラフを加算する．
    //↑　sum(l)の傾き+=v．sum(l)の値+=-v*l+v． 直線を足す．
    //      sum(r)の傾き-=v．sum(r)の値-=-v*r+v．  直線を引く．
    // (足された後の変化) sum(r)の値+=d(r)　値を足す．

    // [l,r)のsumに加算するグラフの基底が定まれば同様の手法で書ける．

    // ex [l,r)に 0*v,2*v,4*v,6*v, ... 2*(r-l-1)*v を加える．
    // ↑[l,r)のsumに対して d(x)=v*(x-l)(x-l+1) のグラフを加算する．
    //    [l,r)のsumに対して d(x)=v* x^2 + v*(-2*l+1)x +v*(l^2 - l)を加算．
    // ↑sum(l)の二次係数+=v sum(r)の二次係数-=v
    //    sum(l)の一次係数+=v*(-2*l+1) sum(r)の一次係数-=v*(-2*l+1)
    //    sum(l)の値+=v*(l^2 - l) sum(r)の値-=v*(l^2-l)
    // (足された後の変化) sum(r)の値+=d(r)　値を足す．
    // 二次関数を足す　→　二次関数を引く　→　値を足す．
    template<typename T> class FenwickLen{
    public:
        int size;
        Fenwick<T> bit1,bit0;
        FenwickLen(int n):size(n){
            bit0=Fenwick<T>(n);bit1=Fenwick<T>(n);
        }
        T sum(int n){// [0,n)
            return bit1.sum(n)*n+bit0.sum(n);
        }
        T sum(int a,int b){// [a,b)
            return sum(b)-sum(a);
        }
        void add(int l,int r,T v){// [l,r)
            bit1.add(l,v);bit1.add(r,-v);
            bit0.add(l,-v*l+v);bit0.add(r,-(-v*r+v));
            bit0.add(r,v*(r-l)+v);
        }
    };
}
