		i++;
		while (i <= size_) {
			v[i] += x;
			i += i & -i;
		}
	}
	inline Type sum(size_t l, size_t r) {
		return sum(r) - sum(l);
	}
	bool operator[](size_t x) {
		return sum(x, x + 1);
	}
