struct SgTree{
private:
	vector<long long> node;
	long long defval;
	int N;
	int n;
public:
	void init(int n, long long defval = INT64_MAX){
		N = 1;
		while(N < n)N<<=1;
		this->n = n;
		this->defval = defval;
		node.assign(N*2-1, defval);
	}
	long long query(int a, int b, int l = 0, int r = -1, int i = 0){
		if(r == -1) r = N;
		if(b <= l || r <= a) return defval;
		if(a <= l && r <= b) return node[i];
		return query(a,b,l,(l+r)/2,i*2+1) + query(a,b,(l+r)/2,r,i*2+2);
	}
	void update(int p, long long v){
		int q = p + N - 1;
		node[q] += v;
		while(q!=0){
			q = (q-1)/2;
			node[q] = node[q*2+1] + node[q*2+2];
		}
	}
	long long get(int p){ return node[p+N-1];}
};


