void add(int pos, int val, int num, int l, int r){
	if (l > pos || r <= pos)
		return;

	data[num] += val;

	if (r - l > 1){
		add(pos, val, num * 2 + 1,  l, (l + r) / 2);
		add(pos, val, num * 2 + 2, (l + r) / 2, r);
	}
}

int  sum(int num, int kl, int kr, int l, int r){
	int ret = 0;

	if (l >= kl && r <= kr)
		return data[num];

	int mid = (l + r) / 2;
	if (mid > kl){
		ret += sum(num * 2 + 1, kl, kr, l, mid);
	}
	if (mid < kr){
		ret += sum(num * 2 + 2, kl, kr, mid, r);
	}
	return ret;
}

