class Segtree {
  struct Node {
    Node *lch, *rch;
    long long sum;
    Node() : sum(0), lch(nullptr), rch(nullptr) {}
    ~Node() {
      // if (lch != nullptr) delete lch;
      // if (rch != nullptr) delete rch;
    }
    void add(ll x, ll val, ll lb, ll ub) {
      if (x >= ub) return;
      Node* node = this;
      while (ub - lb > 1) {
        node->sum += val;
        ll mid = (lb + ub) / 2;
        if (x < mid) {
          if (node->lch == nullptr) node->lch = new Node();
          node = node->lch;
          ub = mid;
        }
        else {
          if (node->rch == nullptr) node->rch = new Node();
          node = node->rch;
          lb = mid;
        }
      }
      node->sum += val;
    }
    long long find(ll r, ll lb, ll ub) {
      long long res = 0;
      Node* node = this;
      while (node != nullptr) {
        ll mid = (lb + ub) / 2;
        if (ub <= r) {
          res += node->sum;
          break;
        }
        else if (r < mid) {
          ub = mid;
          node = node->lch;
        }
        else {
          if (node->lch != nullptr) res += node->lch->sum;
          lb = mid;
          node = node->rch;
        }
      }
      return res;
    }
  };
  Node *root;
  const ll n;
public:
  Segtree() : Segtree(0) {}
  Segtree(ll n) : root(new Node()), n(n) {}
  void add(ll x, ll val) {
    if (x < 0 || x >= n) return;
    root->add(x, val, 0, n);
  }
  long long find(ll r) {
    if (r == 0) return 0;
    return root->find(min(n, r), 0, n);
  }
  ~Segtree() { delete root; }
};

struct Trie {
  ll keta, n;
  Trie *lch, *rch;
  Segtree seg;
  Trie() : lch(nullptr), rch(nullptr), n(0), seg() {}
  Trie(ll keta, ll n) : lch(nullptr), rch(nullptr), keta(keta), n(n), seg(n) {}
  Trie* make_child() {
    assert(keta > 0);
    return new Trie(keta-1, n);
  }
  // x, y に +k
  void add(ll x, ll y, ll k) {
    Trie* t = this;
    while (t->keta > 0) {
      t->seg.add(y, k);
      ll mid = 1LL<<(t->keta-1);
      if (x >= mid) {
        x -= mid;
        if (t->rch == nullptr) t->rch = t->make_child();
        t = t->rch;
      }
      else {
        if (t->lch == nullptr) t->lch = t->make_child();
        t = t->lch;
      }
    }
    t->seg.add(y, k);
  }
  // [0, r) 中, xでxorしてk未満
  long long find(ll r, ll x, ll k) {
    long long res = 0;
    Trie* t = this;
    while (t != nullptr) {
      if (k >= (1LL<<t->keta)) {
        res += t->seg.find(r);
        break;
      }
      if (keta == 0 || k == 0) break;
      ll mid = 1LL<<(t->keta-1);
      Trie *left = t->lch, *right = t->rch;
      if (x>>(t->keta-1) & 1) swap(left, right);
      if (k >= mid) {
        if (left != nullptr) res += left->seg.find(r);
        k -= mid;
        t = right;
      }
      else {
        t = left;
      }
    }
    return res;
  }
};

