const int inf = INT_MAX;

struct SegmentTree{
private:
    int n; // セグ木の葉の数, つまり２冪になっており,　全体の要素数は2*n-1
    vector<int> node;

public:
    SegmentTree(vector<int> v){
        int sz = v.size();
        n = 1; while(n < sz) n*= 2;
        node.resize(2*n-1, 0);
        for(int i=0; i<sz; ++i) node[i+n-1] = v[i];
        for(int i=n-2; i>=0; --i) node[i] = node[2*i+1]+node[2*i+2];
    }

    // k番目(0-indexed)をvalに変更
    void add(int k, int val){
        k += n-1;
        node[k] += val;

        while(k>0){
            k = (k-1)/2;
            node[k] = node[2*k+1] + node[2*k+2];
        }
    }

    // [a,b)の最小値を求める
    // kは接点の番号、l、rはその接点が[l, r)に対応していることを表す
    // 外からはgetmin(a, b, 0, 0, n)と呼ぶ
    int getsum(int a, int b, int k=0, int l=0, int r=-1){
        if(r < 0) r = n;
        // [a, b)と[l, r)が交差していなければinfを返す
        if(r <= a || b <= l) return 0;

        // [a,b) ⊃ [l, r)ならば、この接点の値
        if(a <= l && r <= b) return node[k];

        // そうでなければ二つの子の最小値
        int vl = getsum(a, b, k*2+1, l, (l+r)/2);
        int vr = getsum(a, b, k*2+2, (l+r)/2, r);
        return vl+vr;
    }
};

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    int n, q; cin >> n >> q;
    vector<int> v(n, 0);

    SegmentTree seg(v);

    for(int i=0; i<q; ++i){
        int com, x, y; cin >> com >> x >> y;
        if(com == 0){
            seg.add(x-1, y);
        }
        else{
            cout << seg.getsum(x-1, y) << endl;
        }
    }

    return 0;
}

