        [](ll i, ll j){ return i+j; },
        [](ll i, ll j){ return i+j; });
    int com;
    ll x, y;
    for (int i=0; i<q; i++) {
        cin >> com >> x >> y;
        if (com == 0) segt.change(x-1, y);
        else cout << segt.query(x-1, y) << '\n';
    }
    return 0;
}

