            ans.push_back(st.sum(x, y+1));
        }
        else {
            int x; ll y;
            std::cin >> x >> y;
            st.update(x,y);
        }
    }
    rip(i,ans.size(), 0) {
        std::printf("%lld\n", ans[i]);
    }
}

