int query(int l,int r,int k,int nl,int nr)
{
	if(nr<=l||r<=nl)return inv;
	if(l<=nl&&nr<=r)return tree[k];

	int vl=query(l,r,k*2+1,nl,(nl+nr)/2);
	int vr=query(l,r,k*2+2,(nl+nr)/2,nr);
	return vl+vr;
}


