int getsum(int a,int b,int k,int l,int r){
  if(r<=a||b<=l)return 0;
  if(a<=l&&r<=b)return tree[k];
  int m=(r)/2;
  return getsum(a,b,k*2+1,l,m)+getsum(a,b,k*2+2,m,r);
}
void add(int a,int b){
  a+=N-1;
  tree[a]+=b;
  while(a){
    a=(a-1)/2;
    tree[a]+=b;
  }
}
