namespace misc {
template <typename T>
using twins = std::pair<T, T>;
using rint_t = std::uint32_t;

rint_t xor128() {
  static rint_t x = 123456789, y = 362436069, z = 521288629, w = 88675123;
  rint_t t = x ^ (x << 11);
  x = y;
  y = z;
  z = w;
  return w = (w ^ (w >> 19)) ^ (t ^ (t >> 8));
}
