using T = int;
#define def 0
struct DynamicSegTree { // on monoid
    T comp(T a, T b) { return a + b; }





    struct node_t {
        int left, right; // indices on pool
        T value;
    };
    deque<node_t> pool;
    int root; // index
    int width; // of the tree
    int size; // the number of leaves
    DynamicSegTree() {
        node_t node = { -1, -1, def };
        pool.push_back(node);
        root = 0;
        width = 1;
        size = 1;
    }
protected:
    int create_node(int parent, bool is_right) {
        // make a new node
        int i = pool.size();
        node_t node = { -1, -1, def };
        pool.push_back(node);
        // link from the parent
        assert(parent != -1);
        int & ptr = is_right ? pool[parent].right : pool[parent].left;
        assert(ptr == -1);
        ptr = i;
        return i;
    }
    int get_value(int i) {
        return i == -1 ? def : pool[i].value;
    }
public:
    void point_set(int i, T z) {
        assert(0 <= i);
        while (width <= i) {
            node_t node = { root, -1, pool[root].value };
            root = pool.size();
            pool.push_back(node);
            width *= 2;
        }
        point_set(root, -1, false, 0, width, i, z);
    }
    void point_set(int i, int parent, bool is_right, int il, int ir, int j, T z) {
        if (il == j and ir == j + 1) { // 0-based
            if (i == -1) {
                i = create_node(parent, is_right);
                size += 1;
            }
            pool[i].value = z;
        }
        else if (ir <= j or j + 1 <= il) {
            // nop
        }
        else {
            if (i == -1) i = create_node(parent, is_right);
            point_set(pool[i].left, i, false, il, (il + ir) / 2, j, z);
            point_set(pool[i].right, i, true, (il + ir) / 2, ir, j, z);
            pool[i].value = comp(get_value(pool[i].left), get_value(pool[i].right));
        }
    }
    T range_concat(int l, int r) {
        assert(0 <= l and l <= r);
        if (width <= l) return def;
        return range_concat(root, 0, width, l, min(width, r));
    }
    T range_concat(int i, int il, int ir, int l, int r) {
        if (i == -1) return def;
        if (l <= il and ir <= r) { // 0-based
            return pool[i].value;
        }
        else if (ir <= l or r <= il) {
            return def;
        }
        else {
            return comp(
                range_concat(pool[i].left, il, (il + ir) / 2, l, r),
                range_concat(pool[i].right, (il + ir) / 2, ir, l, r));
        }
    }
};

