int sum(int x, int y, int k, int l, int r) {
	if (x == l && y == r) {
		return tree[k];
	}

	int mid = (l + r) / 2;
	if (y <= mid) {
		return sum(x, y, (k * 2 + 1), l, mid);
	}
	if (x >= mid) {
		return sum(x, y, (k * 2 + 2), mid, r);
	}
	int s = sum(x, mid, (k * 2 + 1), l, mid) + sum(mid, y, (k * 2 + 2), mid, r);
