template <typename T>
class FenwickTree {
  private:
    vector<T> ft;
    T zero;

    inline T LSOne(T n) {
      return n & -n;
    }
  public:
    FenwickTree(int n, T z) {
      zero = z;
      ft.assign(n + 1, z);
    }

    int rsq(int b) {
      int sum = 0;
      for (; b; b -= LSOne(b)) sum += ft[b];
      return sum;
    }

    int rsq(int a, int b) {
      return rsq(b) - (a == 1 ? zero : rsq(a - 1));
    }

    void adjust(int k, T v) {
      for (; k < (int)ft.size(); k += LSOne(k)) ft[k] += v;
    }
};

