    // 初期化
    SegmentTree(ll size){
        N = _powerOfTwo(size); //2べき
        A.resize(N * 2); // 木なので2倍必要
    }

    void Add(int X, int diff){
        int index = N + X - 1; // 葉のインデックス
        A[index] += diff;
        // 親にも反映
        while(index > 0){
            index = (index-1) / 2;
            A[index] += diff;
        }
    }

    void DebugPrint(){
        pn(A[0]);
    }

    // 引数以上の2のべき乗 5=>8
    ll _powerOfTwo(int n){
        ll ret = 1;
        while(ret < n){
            ret *= 2;
        }
        return ret;
    }

    // 区間[a,b)の総和。ノードk =[l,r) に着目している
    ll _rangeSum(int a, int b, int k, int l, int r){
        //cout << "_rangeSum() " << a << " " << b << " " << k << " " << l << " " << r << endl;

        // 重ならない
        if(r <= a || b <= l){
            return 0;
        }
        // 内包する
        else if(a <= l && r <= b){
            return A[k];
        }
        // 重なる部分もある
        else{
            ll center = (l+r) / 2;
            // 左下の子
            ll sum0 = _rangeSum(a, b, 2*k+1, l, center);
            // 右下の子
            ll sum1 = _rangeSum(a, b, 2*k+2, center, r);
            return sum0 + sum1;
        }
    }

    // [a, b) までの和
    // 半開区間
    ll RangeSum(int a, int b){
        //cout << "range sum [" << a << "," << b << ")" << endl;
        return _rangeSum(a, b, 0, 0, N);
    }
};

