struct SegTree {
  vector<int> seg_tree;
  int sz;

  SegTree(int _n) {
    sz = 1;
    while (sz < _n) {
      sz *= 2;
    }

    seg_tree.resize(2* sz - 1);
  }

  void add(const int i, const int value, const int n) {
    int k = i + sz-1;
    seg_tree[k] += value;
    while (k > 0) {
      k = (k-1) / 2;
      seg_tree[k] += value;
    }
  }

  int sum_w(const int a, const int b) {
    return this->sum(a,b,0,0,sz);
  }

  int sum(const int a, const int b, int k, int l, int r) {
    if (b <= l || r <= a) return 0;

    if (a <= l && r <= b) return seg_tree[k];

    else {
      int res = 0;
      res += sum(a,b,2*k+1,l,(l+r)/2);
      res += sum(a,b,2*k+2,(l+r)/2,r);
      return res;
    }
  }

};

