class RangeSumQuery {
private:
  int* tree;
public:
  int size;
  RangeSumQuery(int n) {
    size = 1; while(size < n) size *= 2;
    tree = new int[2*size - 1];
    for (int i=0; i < 2*size - 1; i++) tree[i] = 0;
  }
  void add(int i, int x);
  int getSum(int s, int t, int i, int l, int r);
};

void RangeSumQuery::add(int i, int x) {
  i += size - 1;

  tree[i] = x;
  while (i > 0) {
    i = (i - 1) / 2;
    tree[i] = tree[2*i+1] + tree[2*i+2];
  }

  // cout << "size: " << size << '\n';
  // for(int i=0; i<size*2-1; i++) {
    // cout << i<<":" << tree[i] << ", ";
  // }
  // cout << '\n';
}

int RangeSumQuery::getSum(int s, int t, int i, int l, int r) {
  // cout << i << ": (" << s << ", " << t << ")" << '\n';
  // cout << "[" << l << ", " << r << "]" << '\n';
  if (r < s || t < l) return 0;
  if (s <= l && r <= t) return tree[i];

  int mid = (l+r)/2;
  int vl = getSum(s, min(t, mid), 2*i+1, l, mid);
  int vr = getSum(max(s, mid), t, 2*i+2, mid+1, r);
  return vl + vr;
}

