  fenwick_tree(){}
  fenwick_tree(int _n):n(_n){
    data.resize(n+1);
  }
  fenwick_tree(std::vector<T>const& a):n(a.size()){
    data.resize(n+1);
    for(int i=1;i<=n;++i){
      data[i] += a[i-1];
      if(i+(i&-i)<=n)data[i+(i&-i)] += data[i];
    }
  }
