    return prefix_sum(r)-prefix_sum(l);
  }
  void add(int x,T v){
    for(int i=x+1;i<=n;i+=i&-i)data[i]+=v;
  }
  void dump(){for(auto x:data)std::cout<<x<<" ";std::cout<<std::endl;}
};

