        root = cnt++;

        if (l + 1 == r) {
            v[root].x += val;
            return;
        }

        int mi = (l + r) / 2;
        if (i < mi) add(v[root].l, l, mi, i, val);
        else add(v[root].r, mi, r, i, val);

        v[root].x = comp(v[v[root].l].x, v[v[root].r].x);
