int calcTotal(int* ary, int size, int index, int end)
{
  int total = 0;
  while (index < end && index < size)
  {
    total += ary[index];
    index++;
  }

  return total;
}

void add(int* dtAry, int* termAry, int size, int sqrtN, int index, int val)
{
  int bi, termTotal;
  dtAry[index] += val;
  bi = index / sqrtN;
  termTotal = calcTotal(dtAry, size, bi * sqrtN, bi * sqrtN + sqrtN);
  termAry[bi] = termTotal;
}

int getSum(int* dtAry, int* termAry, int dtSize, int termSize, int sqrtN, int left, int right)
{
  int total = 0;
  if (left / sqrtN == right / sqrtN)
  {
    total = calcTotal(dtAry, dtSize, left, right + 1);
  }
  else
  {
    total += calcTotal(dtAry, dtSize, left, ((left / sqrtN) + 1) * sqrtN);
    total += calcTotal(termAry, termSize, (left / sqrtN) + 1, (right + 1) / sqrtN);
    total += calcTotal(dtAry, dtSize, ((right + 1) / sqrtN) * sqrtN, right + 1);
  }

  return total;
}

int main()
{
  int n, q, s, m, i, com, x, y, sum;
