void input(int n, long long *x) {
	for (int i = 0; i < n; i++)
		x[i] = 0;
}

void init(int *s, int *x, int idx, int left, int right) {
	if (left == right) {
		s[idx] = x[left];
		return;
	}
	int mid = (left + right) / 2;
	init(s, x, 2 * idx, left, mid);
	init(s, x, 2 * idx + 1, mid + 1, right);
	s[idx] = min(s[2 * idx], s[2 * idx + 1]);
	return;
}

void update(int *s, int idx, int left, int right, int p, int val) {
	if (left == right) {
		s[idx] = val;
		return;
	}
	int mid = (left + right) / 2;
	if (p <= mid)
		update(s, 2 * idx, left, mid, p, val);
	else
		update(s, 2 * idx + 1, mid + 1, right, p, val);
	s[idx] = min(s[2 * idx], s[2 * idx + 1]);
	return;
}

int query(int *s, int idx, int left, int right, int l, int r) {
	if (l <= left && r >= right)
		return s[idx];
	if (l > right || r < left)
		return INT_MAX;
	return min(query(s, 2 * idx, left, (left + right) / 2, l, r), query(s, 2 * idx + 1, (left + right) / 2 + 1, right, l, r));
}

int lowbit(int x) {
	return x&(-x);
}

void update2(int a, int b, long long *bit, int n) {
	while (a <= n) {
		bit[a] += b;
		a += lowbit(a);
	}
}

long long query2(int a, long long *bit) {
	long long r = 0;
	while (a > 0) {
		r += bit[a];
		a -= lowbit(a);
	}
	return r;
}

