typedef long long ll;

const int MAX_N = 100001;

ll st[1 << 18];

void init(int n){
    int nn = 1;
    while(nn < n) nn *= 2;
    fill(st, st + 2 * nn - 1, 0);
}

void add(int i, ll x, int k, int l, int r){
    if(i < l || r <= i) return;
    if(r - l == 1) st[k] += x;
    else{
        int chl = 2 * k + 1;
        int chr = 2 * k + 2;
        add(i, x, chl, l, (l + r) / 2);
        add(i, x, chr, (l + r) / 2, r);
        st[k] = st[chl] + st[chr];
    }
}

ll get_sum(int a, int b, int k, int l, int r){
    if(r <= a || b <= l) return 0LL;
    if(a <= l && r <= b) return st[k];
    ll res_l = get_sum(a, b, 2 * k + 1, l, (l + r) / 2);
    ll res_r = get_sum(a, b, 2 * k + 2, (l + r) / 2, r);
    return res_l + res_r;
}

int main(){
    int n, q;
    scanf("%d%d", &n, &q);
    init(++n);
    for(int _ = 0; _ < q; ++_){
        int c, x, y;
        scanf("%d%d%d", &c, &x, &y);
        if(c == 0){
            add(x, y, 0, 0, n);
        }else{
            ll ret = get_sum(x, y + 1, 0, 0, n);
            printf("%lld\n", ret);
        }
    } 
    return 0;
}

#include <bits/stdc++.h>

using namespace std;

using ll = long long;

int main() {
  const int sqrtN = 512;
  int n, q;
  cin >> n >> q;
  int bucket_sz = (n+sqrtN-1)/sqrtN;
  vector<ll> a(n, 0);
  vector<ll> bucketSum(bucket_sz, 0);
  auto update = [&](int k, int x) {
    a[k] += x;
    k /= sqrtN;
    int l = k*sqrtN, r = (k+1)*sqrtN;
    ll sum = 0;
    for(int i = l; i < r; ++i) sum += a[k];
    bucketSum[k] = sum;
  };
  auto query = [&](int s, int t)->ll{
    ll res = 0;
    for(int i = 0; i < bucket_sz; ++i) {
      int l = i*sqrtN, r = (i+1)*sqrtN;
      if(r <= s || t <= l) continue;
      if(s <= l && r <= t) res += bucketSum[i];
      else {
	for(int j = max(s, l); j < min(t, r); ++j) {
	  res += a[j];
	}
      }
    }
    return res;
  };
  while(q--) {
    ll t, x, y;
    cin >> t >> x >> y;
    if(t == 0) update(x, y);
    else cout << query(x, y+1) << endl;
  }

  return 0;
}

