template<class T>
struct SegTree {
    // tree: data structure
    // INF: initilize value
    // f: update function(old, new)
    // g: get function(child1, child2)

    T INF;
    size_t N;
    std::vector<T> tree;

    std::function<T(T,T)> F;
    std::function<T(T,T)> G;

    SegTree(size_t size, T inf, std::function<T(T,T)> f, std::function<T(T,T)> g) {
        INF = inf;
        F = f;
        G = g;

        N = 1;
        while( N < size ) {
            N <<= 1;
        }
        tree.resize(2*N-1, INF);
    }

    void update(int i, int x) {
        i += N - 1;
        tree[i] = F(tree[i], x);
        while(i > 0) {
            i = (i-1)/2;
            tree[i] = G(tree[i*2+1],tree[i*2+2]);
        }
    }

    T query(size_t a, size_t b) {
        auto x = query(a, b, 0, 0, N);
        return x;
    }
    T query(size_t a, size_t b, size_t k, size_t l, size_t r) {
        if( r <= a || b <= l ) {
            return INF;
        }
        if( a <= l && r <= b ) {
            return tree[k];
        } else {
            T vl = query(a, b, k*2+1, l, (l+r)/2);
            T vr = query(a, b, k*2+2, (l+r)/2, r);
            return G(vl, vr);
        }
    }

    void debug() {
        std::cout << "------" << std::endl;
        std::cout << tree[0] << std::endl;
        size_t r = 0;
        while(r < N-1) {
            size_t ch = r*2+2;
            FOR(i, r+1, ch+1) {
                if(i != r+1) std::cout << " ";
                std::cout << tree[i];
            }
            std::cout << std::endl;
            r = ch;
        }
        std::cout << "------" << std::endl;
    }
};

