struct segtree {
	int N = 1;
	vi val;
	segtree(int n) {
		while (N < n) N *= 2;
		val = vi(2 * N);
		for (int i = 0; i < 2 * N; i++) {
			val[i] = 0;
		}
	}
	void add(int k, int a) {
		k += N;
		val[k] += a;
		while (k > 0) {
			k = k / 2;
			val[k] += a;
		}
	}
	int sum(int a, int b) { return sum(a, b, 1, 0, N); }
	int sum(int a, int b, int k, int l, int r) {
		if (r <= a || b <= l) return 0;
		if (a <= l && r <= b) return val[k];
		int m = (l + r) / 2;
		return sum(a, b, k * 2, l, m)+ sum(a, b, k * 2 + 1, m, r);
	}
};

