};

template <typename T>
struct Sum {
  using value_type = T;
  static const value_type default_value = value_type();
  static value_type merge(const value_type& a, const value_type& b) {
    return a + b;
  }
  static value_type eval(std::int64_t L, std::int64_t R, value_type v,
                         value_type lazy) {
    return v + (R - L) * lazy;
  }
