    void update(int k, int a) {
        k += m_n - 1;
        m_dat[k] = a;

        while (k > 0) {
            k = (k - 1) / 2;
            m_dat[k] = m_dat[k * 2 + 1] + m_dat[k * 2 + 2];
        }
    }

