template<typename CommutativeMonoid>
class BIT{
public:
	using value_type = CommutativeMonoid;

private:
	std::vector<value_type> tree;
	size_t N;

public:
	BIT(){}
	BIT(const size_t& N):N(N+1), tree(N+1, value_type(0)){}
	BIT(const BIT& bit):tree(bit.tree), N(bit.N){}

	void update(size_t k, const value_type& diff){
		for(;k <= N;k += k & -k){
			tree[k] = tree[k]+diff;
		}
	}

	value_type query(size_t k) const { // sum of [0, k)
		value_type res = value_type();
		for(;k > 0;k -= k & -k){
			res = res + tree[k];
		}
		return res;
	}

	void updatez(size_t k, value_type v){ // 0-indexed
		update(k+1, v);
	}

	size_t search(std::function<bool(value_type)>& f) const { // Find k :[0, k) -> True, [0, k-1) -> False
		if(f(value_type()))
			return 0;
		if(!f(query(N)))
			return N+1;
		value_type x;
		size_t k = 1, idx = 0;
		while(k <= N) k <<= 1;
		k >>= 1;
		while(k >>= 1){
			if((idx|k) <= N && !f(tree[idx|k]+x))
				x = x + tree[idx|=k];
		}
		return idx+1;
	}

	size_t size() const {return N;}
};

