class Bucket{
  public:
  vector<ll> buc,v;
  ll N,sqn,K;
  Bucket(){};
  Bucket(ll n){
    N = n;
    sqn = sqrt(N);
    K = (n + sqn - 1) /sqn;
    buc.resize(K);
    v.resize(K * sqn);
  }
  void add(int x,int y){
    v[x] += y;
    ll sum = 0;
    int k = x / sqn;
    for(int i = k * sqn; i < (k + 1) * sqn;++i){
      sum += v[i];
    }
    buc[k] = sum;
  }
  ll query(int x,int y){
    ll res = 0;
    for (int k = 0; k < K; ++k) {
      int l = k * sqn, r = (k + 1) * sqn;
      if (r <= x || y <= l)
        continue;
      if (x <= l && r <= y) {
        res += buc[k];
      } else {
        for (int i = max(x, l); i < min(y, r); ++i) {
          res += v[i];
        }
      }
    }
    return res;
  }
  void Debug(){
    for(int i = 0; i < N;++i){
      cout << buc[i/sqn] << ' ';
    }
    cout << endl;
    for(int i = 0; i < N;++i){
      cout << v[i] << ' ';
    }
    cout << endl;
  }
};

