template <typename T>
class FenwickTree {
	const int n;
	vector<T> data;
public:
	FenwickTree(int n_) : n(n_ + 1), data(n) {}
	T find(int p) const {
		p++;
		T res = 0;
		while (p > 0) {
			res += data[p];
			p &= p - 1;
		}
		return res;
	}
	T find(int l, int r) const {
		return find(r) - find(l - 1);
	}
	void add(int p, T val) {
		p++;
		while (p < n) {
			data[p] += val;
			p += p & -p;
		}
	}
	void update(int p, T val) {
		add(p, val - find(p));
	}
};

