}

template<typename T>
//Least Significant Bit 最小の bit を返す
T LSB(T n) { return (n & (-n)); }
/*-----------------------------------------ここからコード-----------------------------------------*/

template<typename T>
//0-indexed/内部的に 1-indexed
struct BIT {
	vector<T> tree;
	//初期化
	BIT(ll n) : tree(n) {
		tree.assign(n + 1, 0);
	}

	//[0, n) の sum を返す/0-indexed
	T sum(ll n) {
		T ret = 0;
		//実は 1-indexed だが半開区間なので見た目がそのまま
		for (; n >= 0; n -= LSB(n)) {
			ret += tree[n];
			if (!n)break;
		}
		return ret;
	}

	//n 番目に x を足す
	void add(ll n, T x) {
		ll siz = tree.size();
		for (++n; n < siz; n += LSB(n))tree[n] += x;
	}
};

