// SegmentTree
template<typename T>
class SegTree{
public:
    int n;
    T defaultValue;
    vector<T> dat;

    SegTree(int m, T value){
        n = 1;
        while(n < m){
            n *= 2;
        }
        dat.assign(2 * n - 1, value);
        defaultValue = value;
    }

    void update(int i, T value){
        i += n - 1;
        dat[i] += value;
        while(i > 0){
            i = (i - 1) / 2;
            dat[i] = ope(dat[2 * i + 1], dat[2 * i + 2]);
        }
    }

    T query(int a, int b, int k = 0, int l = 0, int r = -1){
        if(r < 0){
            r = n;
        }

        if(r <= a || b <= l){
            return defaultValue;
        }
        if(a <= l && r <= b){
            return dat[k];
        }
        else{
            T vl = query(a, b, 2 * k + 1, l, (l + r) / 2);
            T vr = query(a, b, 2 * k + 2, (l + r) / 2, r);
            return ope(vl, vr);
        }
    }

private:
    T ope(T a, T b){
        return a + b;
    }
};

int main(){

    int n, q;
    cin >> n >> q;

    SegTree<int> segTree(n, 0);

    for(int i = 0; i < q; i++){
        int com, x, y;
        cin >> com >> x >> y;
        if(com == 0){
            segTree.update(x - 1, y);
        }
        else{
            cout << segTree.query(x - 1, y) << endl;
        }
    }

    return 0;
}

