struct BinaryIndexedTree{
    vector<vector<long long>> BIT;
    BinaryIndexedTree(vector<long long> A) : BIT(){
        int n;
        while((1<<n)<=A.size())n++;
        BIT.resize(n);
        while(A.size()<(1<<n)-1)A.push_back(0);
        for(int i = 0;i < n;i++)BIT[i].resize(1<<(n-i-1));
        for(int i = 1;i < A.size();i++)A[i] += A[i-1];
        for(int i = 0;i < n;i++){
            for(int j = 0;j < BIT[i].size();j++){
                BIT[i][j] = A[(1<<(i))-1+(1<<(i+1))*j] - (j ? A[(1<<(i+1))*j-1] : 0);
            }
        }
    }
    long long get(long long i){
        long long ans = 0;
        long long n = 0;
        while(n < BIT.size()){
            if(i%2 == 0){
                ans += BIT[n][(i>>1)];
                i--;
            }
            i >>= 1;
            n++;
        }
        return ans;
    }
    long long getSum(long long x,long long y){
        return get(y) - (x ? get(x-1) : 0);
    }
    void add(long long i,long long x){
        long long n = 0;
        while(n < BIT.size()){
            if(i%2 == 0){
                BIT[n][(i>>1)] += x;
            }
            i >>= 1;
            n++;
        }
    }
};

