template <class T>
struct FenwickTree {
    int n;
    vector<T> x;
    FenwickTree(int n_ = 0) : n(n_), x(n_+1){
        fill(x.begin(), x.end(), 0);
    }
    T sum(int r){
        T S = 0;
        for (; r >= 0; r = (r&(r+1))-1) S += x[r];
        return S;
    }
    T sum(int l, int r){
        if(l >= r) return 0;
        else return l==0 ? sum(r-1) : sum(r-1) - sum(l-1);
    }
    void add(int k, T a){
        for (; k < n; k |= k+1) x[k] += a;
    }
    void set(int k, T a){
        int x = sum(k, k+1);
        add(k, a-x);
    }
    vi to_a(int l = -1, int r = -1){
        if(l == -1) l = 0;
        if(r == -1) r = n;
        vi res(r-l);
        range(i,l,r) res[i-l] = sum(i,i+1);
        return res;
    }
};

