//segment tree実装
constexpr size_t next_pow2(size_t n){
    if((n & (n - 1)) == 0) return n;

    size_t ret = 1;
    while(n > ret){
        ret <<= 1;
    }

    return ret;
}

template<typename Tp, typename Pred>
class segment_tree{
    private:
        size_t bottom_;
        const Tp init_;
        std::vector<Tp> data_;
        Pred pred_;
    public:
        segment_tree(const std::vector<Tp>& in, Tp init, Pred pred) : bottom_(next_pow2(in.size())), init_(init), data_(2 * bottom_ - 1, init), pred_(pred) {
            for(size_t i = 0; i < in.size(); i++){
                data_.at(i + bottom_ - 1) = in.at(i);
            }

            for(long i = bottom_ - 2; i >= 0; i--){
                data_.at(i) = pred_(data_.at(2 * i + 1), data_.at(2 * i + 2));
            }
        }

        // 元の配列のindexをvalに更新
        void update(size_t index, Tp val){
            index += bottom_ - 1;

            data_[index] = val;

            while(index != 0){
                index = (index - 1) / 2;
                data_[index] = pred_(data_.at(2 * index + 1), data_.at(2 * index + 2));
            }
        }

        // 区間[begin, end)の探索
        Tp find(size_t begin, size_t end){
            begin += bottom_ - 1;
            end += bottom_ - 1;

            Tp left = init_;
            Tp right = init_;

            while(begin < end){
                if(begin % 2 == 0){
                    left = pred_(left, data_.at(begin));
                }

                if(end % 2 == 0){
                    right = pred_(right, data_.at(end - 1));
                }

                begin /= 2;
                end = (end - 1) / 2;
            }

            return pred_(left, right);
        }

        Tp at(size_t n){
            return data_.at(n + bottom_ - 1);
        }

        // debug
        void print(){
            for(const auto& e : data_){
                std::cout << e << std::endl;
            }
        }
};

int main(){

    size_t n, q;
    std::cin >> n >> q;

    std::vector<size_t> v(n, 0);
    auto pred = [](size_t a, size_t b){ return a + b; };
    segment_tree<size_t, decltype(pred)> st(v, 0, pred);

    for(size_t i = 0; i < q; i++){
        size_t command, x, y;
        std::cin >> command >> x >> y;

        if(command == 0){
            st.update(x - 1, st.at(x - 1) + y);
        }else{
            std::cout << st.find(x - 1, y) << std::endl;
        }
    }

    return 0;
}

