class BIT{
private:
  int n;
  VI bit;
public:
  // prepare [0..n), assign to bit[1..n]
  BIT(int n_){
	n = n_;
	bit.assign(n+1, 0);
  }

  // return bit[0,i)
  int sum(int i){
	int s = 0;
	while(i > 0){
	  s += bit[i];
	  i -= i & -i;
	}
	return s;
  }

  // bit[i] += x, 0-indexed
  void add(int i, int x){
	++i;
	while(i <= n){
	  bit[i] += x;
	  i += i & -i;
	}
  }

  // return minimum i s.t. x <= bit[0..i)
  int lower_bound(int x){
	if(x <= 0) return 0;
	int i = 1;
	for(;i<=n;i<<=1);
	i >>= 1;
	int res = 0;
	for(;i>0;i>>=1){
	  if(res+i <= n && bit[res+i] < x){
		x -= bit[res+i];
		res += i;
	  }
	}
	return res+1;
  }
};

