int size = 1;
vector<long> segtree;

void change(int k, long x){
    k += size - 1;
    segtree[k] += x;
    while(k > 0){
        k = (k - 1) / 2;
        segtree[k] = segtree[k * 2 + 1] + segtree[k * 2 + 2];
    }
}

long sum(int a, int b, int l, int r, int now){
    if(r <= a || b <= l){
        return 0;
    }else if(a <= l && r <= b){
        return segtree[now];
    }else{
        return sum(a, b, l, (l + r) / 2, now * 2 + 1) + sum(a, b, (l + r) / 2, r, now * 2 + 2);
    }
}

