template <typename T>
class RSQ{
public:
	vector<T> dat;
	int n;
	RSQ(int n0,T initdata){
		initsize(n0,initdata);
	}
	void initsize(int n0, T initdata){
		int k=1;
		while(1){
			if(n0<=k){
				n=k;
				dat.resize(2*n-1);
				for(int i=0;i<2*n-1;i++)dat[i]=initdata;
				break;
			}
			k*=2;
		}
	}

	void add(int i,int x){
		i += n-1;
		dat[i] += x;
		while(i>0){
			i = (i-1) / 2;
			dat[i] = dat[i*2+1]+dat[i*2+2];
		}
	}

	T query0(int a,int b,int k,int l,int r){// [a,b)
		if(r<=a || b<=l)return 0;
		if(a<=l && r<=b)return dat[k];
		else{
			int vl = query0(a,b,k*2+1,l,(l+r)/2);
			int vr = query0(a,b,k*2+2,(l+r)/2,r);
			return vl+vr;
		}
	}

	T query(int a,int b){ // [a,b)
		return query0(a,b,0,0,n);
	}
};

int main(){
	int n,q;
	cin >> n >> q;
	RSQ<int> rsq(n+1,0);
	FOR(i,0,q){
		int com,x,y;
		cin >> com >> x >> y;
		if(com){
			cout << rsq.query(x,y+1) << endl;
		}else{
			rsq.add(x,y);
		}
	}
}

