struct RSQ{
  //Ranged Sum Query

  int n;
  vector<int> node;
  //1-indexed

  RSQ(int size){
    int t=1;
    while(t<size){
      t*=2;
    }

    node.clear();
    node.resize(t*2,0);
    n=t;
  }

  void add(int i,int val){
    i=i+n;
    while(i>0){
      node[i]+=val;
      i/=2;
    }
  }

  int getSum(int s,int t,int k=1,int left=0,int right=-1){
    if(right<0)right=n;

    if(right<=s||left>=t){
      return 0;
    }

    if(left>=s&&right<=t){
      return node[k];
    }

    return getSum(s,t,k*2,left,(left+right)/2)+getSum(s,t,k*2+1,(left+right)/2,right);
  }
};

