template<typename T, typename E, typename F, typename G>
class SegmentTree {
    int N;
    F f;
    G g;
    T ti;
    E ei;
    vector<T> dat;

public:
    SegmentTree(int n, F f, G g, T ti, E ei) : N(1), f(f), g(g), ti(ti), ei(ei) {
        while (N < n) {
            N <<= 1;
        }
        dat.resize(2 * N - 1, ti);
    }

    void build(int n, vector<T> v) {
        for (int i = 0; i < n; ++i) {
            dat[i + N - 1] = v[i];
        }
        for (int i = N - 2; i >= 0; --i) {
            dat[i] = f(dat[i * 2 + 1], dat[i * 2 + 2]);
        }
    }

    void update(int k, T t) {
        k += N - 1;
        dat[k] = g(dat[k], t);
        while (k > 0) {
            k = (k - 1) / 2;
            dat[k] = f(dat[k * 2 + 1], dat[k * 2 + 2]);
        }

//        dat[k + N - 1] = g(dat[k + N - 1], t);
//        for (int i = (k + N - 2) / 2;; i = (i - 1) / 2) {
//            dat[i] = f(dat[i * 2 + 1], dat[i * 2 + 2]);
//            if (i == 0) break;
//        }
    }

    T query(int a, int b, int k, int l, int r) {
        if (r <= a || b <= l) {
            return ti;
        } else if (a <= l && r <= b) {
            return dat[k];
        } else {
            T left = query(a, b, k * 2 + 1, l, (l + r) / 2);
            T right = query(a, b, k * 2 + 2, (l + r) / 2, r);
            return f(left, right);
        }
    }

    T query(int a, int b) {
        return query(a, b, 0, 0, N);
    }

};

