template<class T>
class SqrtDecomposition {
private:
    int N, K;
    const int cap = 512;
    vector<T> data, bucket;
public:
    SqrtDecomposition(int n);
    void add(int x, T y);
    T query(int x, int y);
};

template<class T>
inline SqrtDecomposition<T>::SqrtDecomposition(int n) : N(n) {
    K = (N + cap - 1) / cap;
    data.assign(K * cap, 0);
    bucket.assign(K, 0);
}

template<class T>
inline void SqrtDecomposition<T>::add(int x, T y) {
    int k = x / cap;
    data[x] += y;
    bucket[k] = 0;
    for(int i = k * cap; i < (k + 1) * cap; ++i) {
        bucket[k] += data[i];
    }
}

template<class T>
inline T SqrtDecomposition<T>::query(int x, int y) {
    T sum = 0;
    for(int k = 0; k < K; ++k) {
        int l = k * cap, r = (k + 1) * cap;
        if(r <= x || y <= l) continue;
        if(x <= l && r <= y) {
            sum += bucket[k];
        } else {
            for(int i = max(x, l); i < min(y, r); ++i) {
                sum += data[i];
            }
        }
    }
    return sum;
}

void solve() {
    int N, Q;
    cin >> N >> Q;
    SqrtDecomposition<int> sq(N);
    while(Q--) {
        int c, x, y;
        cin >> c >> x >> y;
        if(c) cout << sq.query(x, y + 1) << '\n';
        else sq.add(x, y);
    }
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    solve();
    return 0;
}

