template<typename T,Int X>
struct BinaryTrie{
  struct Node{
    bool f;
    T laz;
    int par,cnt,nxt[2];
    Node(){}
    Node(bool f,int par):
      f(f),laz(0),par(par),cnt(0){nxt[0]=nxt[1]=-1;}
  };

  vector<Node> v;
  queue<int> q;
  BinaryTrie(){v.reserve(int(6e6));v.emplace_back(0,-1);}

  void emplace(bool f,int par){
    if(q.empty()){
      v[par].nxt[f]=v.size();
      v.emplace_back(f,par);
    }else{
      v[par].nxt[f]=q.front();
      v[q.front()]=Node(f,par);
      q.pop();
    }
  }

  inline int count(int x){
    return x<0?0:v[x].cnt;
  }

  inline void eval(int x,int i){
    if((v[x].laz>>i)&1){
      swap(v[x].nxt[0],v[x].nxt[1]);
      v[x].laz^=T(1)<<i;
    }
    for(int k=0;k<2;k++){
      if(!~v[x].nxt[k]) continue;
      v[v[x].nxt[k]].laz^=v[x].laz;
      v[v[x].nxt[k]].f=k;
    }
    v[x].laz=0;
  }

  void add(const T b,int k=1){
    int pos=0;
    for(int i=X-1;i>=0;i--){
      eval(pos,i);
      bool f=(b>>i)&1;
      if(v[pos].nxt[f]<0) emplace(f,pos);
      pos=v[pos].nxt[f];
    }
    v[pos].cnt+=k;
    for(int i=0;i<X;i++){
      pos=v[pos].par;
      v[pos].cnt=count(v[pos].nxt[0])+count(v[pos].nxt[1]);
    }
  }

  void update(const T b){
    v[0].laz^=b;
  }

  int find(const T b){
    int pos=0;
    for(int i=X-1;i>=0;i--){
      eval(pos,i);
      bool f=(b>>i)&1;
      if(~v[pos].nxt[f]) pos=v[pos].nxt[f];
      else return -1;
    }
    return pos;
  }

  void erase(int pos,int k=1){
    v[pos].cnt-=k;
    for(int i=0;i<X;i++){
      pos=v[pos].par;
      v[pos].cnt=count(v[pos].nxt[0])+count(v[pos].nxt[1]);
      for(int k=0;k<2;k++){
	if(!count(v[pos].nxt[k])){
	  if(~v[pos].nxt[k])
	    q.emplace(v[pos].nxt[k]);
	  v[pos].nxt[k]=-1;
	}
      }
    }
  }

  int xmax(const T b){
    int pos=0;
    for(int i=X-1;i>=0;i--){
      eval(pos,i);
      bool f=(~b>>i)&1;
      f^=!~v[pos].nxt[f];
      pos=v[pos].nxt[f];
    }
    return pos;
  }

  int xmin(const T b){
    return xmax(~b&((T(1)<<X)-1));
  }

  int lower_bound(const T b){
    int pos=0;
    for(int i=X-1;i>=0;i--){
      eval(pos,i);
      bool f=(b>>i)&1;
      if(~v[pos].nxt[f]){
	pos=v[pos].nxt[f];
	continue;
      }
      if(f) return next(pos,i);
      return fmin(v[pos].nxt[!f],i-1);
    }
    return pos;
  }

  int upper_bound(const T b){
    return lower_bound(b+1);
  }

  int next(int pos,int i=-1){
    for(;i<X;i++){
      int par=v[pos].par;
      if(v[pos].f==0&&~v[par].nxt[1])
	return fmin(v[par].nxt[1],i);
      pos=par;
    }
    return -1;
  }

  int fmin(int pos,int i){
    if(i==-1) return pos;
    eval(pos,i);
    return fmin(v[pos].nxt[v[pos].nxt[0]==-1],i-1);
  }

  T val(int pos){
    T res=0;
    for(int i=0;i<X;i++){
      res|=T(v[pos].f)<<i;
      pos=v[pos].par;
    }
    return res;
  }

  int find_by_order(int k){
    int pos=0;
    if(count(pos)<=k) return -1;
    for(int i=X-1;i>=0;i--){
      eval(pos,i);
      if(count(v[pos].nxt[0])<=k){
	k-=count(v[pos].nxt[0]);
	pos=v[pos].nxt[1];
      }else{
	pos=v[pos].nxt[0];
      }
    }
    return pos;
  }

  int order_of_key(const T b){
    int res=0,pos=0;
    for(int i=X-1;i>=0;i--){
      eval(pos,i);
      bool f=(b>>i)&1;
      if(f) res+=count(v[pos].nxt[0]);
      pos=v[pos].nxt[f];
      if(pos<0) break;
    }
    return res;
  }

  void show(){
    vector<T> vs;
    T a=val(xmin(0));
    vs.emplace_back(a);
    int pos=find(a);
    while(val(xmax(0))!=a){
      pos=next(pos);
      a=val(pos);
      vs.emplace_back(a);
    }
    cout<<"#######"<<endl;
    for(T x:vs) cout<<x<<" ";
    cout<<endl;
  }

};
