template<class T> struct FenwickTree {
    using F = function<T(T, T)>;
private :
    T id;
    const F &f;
    vector<T> node;
public : 
    FenwickTree (int n, const F &f, const T &id) : 
        node(n+1, id), id(id), f(f) { }

    void resize (int n) {
        node.assign(n+1, id);
    }

    T fold (int i) {
        T ret = id;
        for (++i; i > 0; i -= (i & -i)) {
            ret = f(ret, node[i]);
        }
        return ret;
    }

    void add (int i, const T &x) {
        for (++i; i < node.size(); i += (i & -i)) {
            node[i] = f(node[i], x);
        }
    }

};

