#define N 100000
#define MAX (1<<31)-1
using namespace std;
long long A[N+1], T[4*N+1];

void build(int l, int r, int k) {
    if (l == r) {
        T[k] = A[l];
        return;
    }
    int mid = (l + r) / 2;
    build(l, mid, k * 2);
    build(mid + 1, r, k * 2 + 1);
    T[k] = T[2 * k] + T[2 * k + 1];
}
void updata(int in, int data ,int l, int r ,int k) {
    if (l == r) {
        A[l] += data;
        T[k] += data;
        return;
    }
    int mid = (l + r) / 2;
    if (in <= mid) updata(in, data, l, mid, k * 2);
    else updata(in, data, mid + 1, r, k * 2 + 1);
    T[k] = T[2 * k] + T[2 * k + 1];
}
long long find(int L, int R, int l, int r, int k) {
    if (L <= l && r <= R) return T[k];
    int mid = (l + r) / 2;
    long long ans = 0;
    if (mid >= L) ans += find(L, R, l, mid, k * 2);
    if (mid < R) ans += find(L, R, mid + 1, r, k * 2 + 1);
    return ans;
}
int main() {
