template <typename T>
struct SegTree {
	T init_val;
	int n;
	vector<T> dat;

	SegTree(int _n, T init_val) : init_val(init_val) {
		n = 1;
		while (n < _n) n *= 2;
		dat.resize(n * 2 - 1, init_val);
	}

	void add(int i, T x) {
		i += n - 1;
		dat[i] += x;
		while (i > 0) {
			i = (i - 1) / 2;
			dat[i] = dat[i * 2 + 1] + dat[i * 2 + 2];
		}
	}

	void set(int i, T x) {
		dat[i + n - 1] = init_val;
		update(i, x);
	}

	// ??¢?´¢??????[a,b), ?????¨????????????k?????????[l,r)
	T query(int a, int b, int k, int l, int r) {
