template<typename Traits>
class FenwickTree {
public:
  using value_type = typename Traits::value_type;
  FenwickTree(int n = 0, const Traits &traits = Traits()):
    traits(traits), n(n), val(n + 1, traits.initial()){}
  void update(int k, value_type x){
    k++;
    while (k <= n){
      val[k] = traits.merge(val[k], x);
      k += k & -k;
    }
  }
  value_type query(int k) const {
    value_type res = traits.initial();
    while (k > 0){
      res = traits.merge(res, val[k]);
      k -= k & -k;
    }
    return res;
  }
  value_type query(int l, int r) const {
    return traits.merge(query(r), traits.inverse(query(l)));
  }
private:
  Traits traits;
  int n;
  vector<value_type> val;
};

namespace fen {
template<typename T>
struct Sum {
  using value_type = T;
  value_type initial() const { return 0; }
  value_type merge(value_type x, value_type y) const { return x + y; }
  value_type inverse(value_type x) const { return -x; }
};

template<typename T>
struct Min {
  using value_type = T;
  value_type initial() const { return numeric_limits<value_type>::max(); }
  value_type merge(value_type x, value_type y) const { return min(x, y); }
  value_type inverse(value_type x) const { assert(false); }
};

template<typename T>
struct Max {
  using value_type = T;
  value_type initial() const { return numeric_limits<value_type>::min(); }
  value_type merge(value_type x, value_type y) const { return max(x, y); }
  value_type inverse(value_type x) const { assert(false); }
};
}

template<typename T> using FenwickTreeSum = FenwickTree<fen::Sum<T>>;
template<typename T> using FenwickTreeMin = FenwickTree<fen::Min<T>>;
template<typename T> using FenwickTreeMax = FenwickTree<fen::Max<T>>;
