template<typename T,typename F>
struct SegmentTree {
private:
    int n;
    vector<T> node;
    T id;
    F f;
public:
    SegmentTree(vector<T> v,F func,T identity):id(identity),f(func) {
        int sz = v.size();
        n = 1;
        while (n < sz) n *= 2;
        node.resize(2*n-1,id);
        for (int i = 0;i < sz;++i) node[i+n-1] = v[i];
        for (int i = n-2;i >= 0;--i) node[i] = f(node[2*i+1],node[2*i+2]);
    }

    void update(int x,T val) {
        x += (n-1);
        node[x] = val;
        while (x > 0) {
            x = (x-1)/2;
            node[x] = f(node[2*x+1],node[2*x+2]);
        }
    }

    T getval(int a,int b,int k = 0,int l = 0,int r = -1) {
        if (r < 0) r = n;
        if (r <= a || b <= l) return id;
        if (a <= l && r <= b) return node[k];
        return f(getval(a,b,2*k+1,l,(l+r)/2),getval(a,b,2*k+2,(l+r)/2,r));
    }
};

int main() {
    int n,q;
    cin >> n >> q;
    auto f = [&](int a,int b)->int{return a+b;};
    SegmentTree<int,decltype(f)> sum(vector<int>(n,0),f,0);
    for (int i = 0;i < q;++i) {
        int c,x,y;
        cin >> c >> x >> y;
        if (c) cout << sum.getval(x-1,y) << endl;
        else sum.update(x-1,f(y,sum.getval(x-1,x)));
    }
    return 0;
}

