	vector<long long> Node;
public:
	BinaryIndexedTree(long long N) : Size(N + 1) {
		Node.resize(Size, 0);
	}
	void Update(long long K, long long X) {
		while (K < Size) {
			Node[K] += X;
			K += (K & -K);
		}
	}
	long long Query(long long R) {
		long long ANS = 0;
		while (R > 0) {
			ANS += Node[R];
			R -= (R & -R);
		}
		return ANS;
	}
	long long Query(long long L, long long R) {
		return Query(R) - Query(L - 1);
	}
	void put() {
		cout << "// ";
		for (int i = 1; i < Size; i++) cout << Node[i] << " ";
		cout << endl;
	}
};

