/* SegTree */
const int N = 1e5;
int t[N<<1];
int n;

void build() {
    rev(i,n-1) t[i] = t[i<<1] + t[i<<1|1];
}
void modify(int p, int value) {
    for(t[p += n] += value; p > 1; p >>= 1) t[p>>1] = t[p] + t[p^1];
}
int query(int l, int r) {
    int res = 0;
    for(l += n, r += n; l < r; l >>= 1, r >>= 1) {
        if (l&1) res += t[l++];
        if (r&1) res += t[--r];
    }
    return res;
}


int main() {
    int Q; cin>>n>>Q;

    rep(i,n) t[n+i] = 0;
    build();
    vector<pair<int,int> > q;
    rep(i,Q) {
        int c,x,y; cin>>c>>x>>y;
        if(c == 0) modify(x-1,y);
        else q.pb(pair<int,int>(x-1,y));
    }
    for(auto& e:q) cout << query(e.first, e.second) << endl;
}

