ll nodenum;
vector<ll> node;

ll init_num=0;
ll func(ll x,ll y){
    return x+y;
}

//セグ木
void init(vector<ll> v){
    nodenum=1;
    while(v.size()>nodenum)nodenum*=2;
    node.resize(2*nodenum-1,init_num);
    rep(i,nodenum-1,nodenum*2-2){
        if(i-(nodenum-1)<v.size()){
            node[i]=node[i-(nodenum-1)];
        }else{
            node[i]=init_num;
        }
    }
    for(ll i=nodenum-2;i>=0;i--){
        node[i]=func(node[2*i+1],node[2*i+2]);
    }
}

void update(ll x,ll y){ //v[x]をyに変更する
    node[x+nodenum-1]=y;
    ll next=x+nodenum-1;
    while(next>0){
        next=(next-1)/2;
        node[next]=func(node[2*next+1],node[2*next+2]);
    }
}

ll find(ll i,ll j,ll x,ll y,ll z){     //v[[i,j)]でのfuncの結果を出力する //node[x]に着目しているnode[x]が担当する範囲は[y,z); //最初はx=-1で
    if(x==-1) return find(i,j,0,0,nodenum);
    if(j<=y || z<=i)return init_num;
    if(i<=y && z<=j)return node[x];
    return func(find(i,j,2*x+1,y,(y+z)/2),find(i,j,2*x+2,(y+z)/2,z));
}

