	BIT_(ll N): v(N+1), N(N){}
	void add(ll i, T x) { for(i++; i<=N; i+=i&(-i)) v[i]+=x; }
	T sum(ll i) { ll s=0;  for(i++; i>0; i-=i&(-i)) s+=v[i];  return s; }
	T sum(ll i, ll j) { return sum(j)-sum(i-1); }
};
using BIT = BIT_<ll>;


void solve()
{
	ll N, Q;  cin >> N >> Q;
	vector<tuple<ll, ll, ll>> cxy = cinv3<ll, ll, ll>(Q);

	BIT bit(N);

	rep(i, 0, Q-1){
		ll com; ll x; ll y;  tie(com, x, y) = cxy[i];

		if (com==0){//add a_xにyを足す
			x--;
			bit.add(x, y);
		}
		else{//getsum a_x～a_yの和を得る
			x--; y--;
			ll ans = bit.sum(x, y);
			cout << ans << '\n';
		}
	}
}


int main(){
	solve();
	return 0;
}

