class segment_tree {
	int dat[1000005];
	int whi;
public:
	segment_tree(int &x,int y) {
		whi = y;
		if (whi != 0 && whi != 1 && whi != 2)exit(0);
		int s = x;
		x = 1;
		while (1) {
			x *= 2;
			if (s <= x)break;
		}
		if (!whi) {
			rep(i, x * 2 - 1)dat[i] = ((int)(1) << 31) - 1;
		}
		else if (whi == 1) {
			rep(i, x * 2 - 1)dat[i] = -(((int)(1) << 31) - 1);
		}
	}
	void update(int k, int a, int x) {
		k += x;
		if (whi != 2)dat[k] = a;
		else dat[k] += a;
		while (k > 0) {
			k = (k - 1) / 2;
			if (!whi)dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
			else if (whi == 1)dat[k] = max(dat[k * 2 + 1], dat[k * 2 + 2]);
			else dat[k] = dat[k * 2 + 1] + dat[k * 2 + 2];
		}
	}
	int query(int a, int b, int x, int l, int r) {
		if (r < a || b < l) {
			if (!whi)return inf;
			else if (whi == 1)return -inf;
			else return 0;
		}
		if (a <= l && b >= r)return dat[x];
		int vl = query(a, b, x * 2 + 1, l, (l + r) / 2);
		int vr = query(a, b, x * 2 + 2, (l + r) / 2 + 1, r);
		if (!whi)return min(vl, vr);
		else if (whi == 1)return max(vl, vr);
		else return vl + vr;
	}
};
