struct SqrtTree {

  vector<T> data;
  vector<T> bucket;
  T sq;

  SqrtTree( vector<T> const& v) : data(v) {
    int d_size = data.size();
    sq = sqrt( d_size );
    bucket.assign( (d_size + sq - 1) / sq, 0 );
    for(int i = 0; i < d_size; i++) {  bucket[i / sq] += data[i];  }
  }

  // [l, r]
  T query(int l, int r) {
    T res = 0;
    int i = l;
    while(i <= r) {
      if(i % sq == 0 && i + sq <= r) {
        // change here!
        res += bucket[ i / sq ];
        // res = min(res,  bucket[ i / sq ]); RMQ
        i += sq;
      } else {
        res += data[i];
        i++;
      }
    }
    return res;
  }

  void update(int i, T x) {
    // change here!
    // bucket[i / sq] -= data[i];
    data[i] += x;
    bucket[i / sq] += x;

    // RMQ
