class SquareDivision{
    private:
        const int BUCKET_SIZE=256;
        int N, B;
        vector<int> data, bucket_sum;

    public:
        void prepare(int n){
            B=(n+BUCKET_SIZE-1)/BUCKET_SIZE;
            N=B*BUCKET_SIZE;
            data.assign(N, 0);
            bucket_sum.assign(B, 0);
        }

        void add(int i, int x){
            int k=x/BUCKET_SIZE;
            data[i]+=x;
            int sum=0;
            for(int j=k*BUCKET_SIZE; j<(k+1)*BUCKET_SIZE; j++){
                sum+=data[j];
            }
            bucket_sum[k]=sum;
        }

        // [x, y)
        int getsum(int x, int y){
            int sum=0;
            for(int i=0; i<B; i++){
                int l=i*BUCKET_SIZE, r=(i+1)*BUCKET_SIZE;

                if(r<=x || y<=l) continue;

                if(x<=l && r<=y) sum+=bucket_sum[i];
                else{
                    for(int j=max(x, l); j<min(y, r); j++){
                        sum+=data[j];
                    }
                }
            }
            return sum;
        }
};

