typedef ll seg_t;

class SegTree {
private:
	int n;
	vector<seg_t> segtree;
	seg_t exc;
	seg_t (*build_rule)(seg_t, seg_t);
	seg_t build_seg(int k) {
		int l = k * 2 + 1, r = k * 2 + 2;
		return build_rule(segtree[l], segtree[r]);
	}
	seg_t find_rule(int s, int t, int l, int r, int k) {
		if (s == l&&t == r) return segtree[k];
		else {
			int mid = (l + r) / 2;
			if (s < mid&&mid < t) {
				seg_t result1 = find_rule(s, mid, l, mid, k * 2 + 1);
				seg_t result2 = find_rule(mid, t, mid, r, k * 2 + 2);
				return build_rule(result1, result2);
			}
			else if (s < mid) {
				return find_rule(s, t, l, mid, k * 2 + 1);
			}
			else if (mid < t) {
				return find_rule(s, t, mid, r, k * 2 + 2);
			}
		}
	}
public:
	SegTree(vector<seg_t> a, seg_t init, seg_t (*f)(seg_t, seg_t)) {
		n = (ll)pow(2, ceil(log2(a.size())));
		segtree = vector<seg_t>(n * 2 - 1, init);
		exc = init;
		build_rule = f;
		Loop(i, a.size()) segtree[n - 1 + i] = a[i];
		Loopr(i, n - 1) segtree[i] = build_seg(i);
	}
	void update(int k, seg_t x, bool add_flag = false) {
		k += n - 1;
		segtree[k] = add_flag ? segtree[k] + x : x;
		while (k > 0) {
			k = (k - 1) / 2;
			segtree[k] = build_seg(k);
		}
	}
	// note: range is [s, t)
	seg_t search(int s, int t) {
		if (s == t) return exc;
		return find_rule(s, t, 0, n, 0);
	}
};

seg_t seg_build_rule(seg_t a, seg_t b) {
	return a + b;
}

int main() {
	int n; cin >> n;
	int q; cin >> q;
	vector<seg_t> a(n, 0);
	SegTree segtree(a, 0, seg_build_rule);
	Loop(i, q) {
		int c, x, y; cin >> c >> x >> y;
		if (c == 0) {
			segtree.update(x, y, true);
		}
		else {
			cout << segtree.search(x, y + 1) << endl;
		}
	}
	return 0;
}

#include <cassert>

template <class CommutativeMonoid, template <class> class Container>
class fenwick_tree {

public:
	using value_structure = CommutativeMonoid;
	using value_type = typename value_structure::value_type;
	using container_type = Container<value_type>;
	using const_reference = typename container_type::const_reference;
	using size_type = typename container_type::size_type;

private:
	size_type base_size;
	container_type c;
	static size_type getsize(const size_type size) {
		size_type ret = 1;
		while (ret < size)
			ret <<= 1;
		return ret;
	}

public:
	fenwick_tree() : base_size(0), c() {}
	explicit fenwick_tree(const size_type size)
		: base_size(getsize(size)), c(size + 1, value_structure::identity()) {}

	bool empty() const { return size() == 0; }
	size_type size() const { return c.size() - 1; }

	value_type fold(size_type last) const {
		assert(last <= size());
		value_type ret = value_structure::identity();
		for (; last; last &= last - 1)
			ret = value_structure::operation(c[last], ret);
		return ret;
	}
	template <class F> size_type search(const F &f) const {
		if (f(value_structure::identity()))
			return 0;
		size_type i = 0, k = base_size;
		value_type acc = value_structure::identity();
		while (k >>= 1)
			if ((i | k) < c.size() && !f(value_structure::operation(acc, c[i | k])))
				acc = value_structure::operation(acc, c[i |= k]);
		return i + 1;
	}

	void update(size_type index, const value_type &diff) {
		assert(index < size());
		for (++index; index < c.size(); index += index & ~index + 1)
			c[index] = value_structure::operation(c[index], diff);
	}
};

template <class T> class plus_monoid {
public:
	using value_type = T;
	static value_type operation(const value_type &x, const value_type &y) {
		return x + y;
	}
	static value_type identity() { return value_type(0); }
	static value_type reverse(const value_type &x) { return x; }
};

