        i = (i - 1) / 2;
        S[i] += x;
    }
}


int find(int s, int t, int k, int l, int r)
{
    if (r <= s || t <= l)
        return 0;

    if (s <= l && r <= t)
        return S[k];

    int u, v;
    u = find(s, t, k * 2 + 1, l, (l + r) / 2);
    v = find(s, t, k * 2 + 2, (l + r) / 2, r);
    return u + v;
}


