int main()
{
	int h, r;
	int g[16][16] = {};
	cin >> h >> r;

	REP(i, r) {
		REP(j, r) {
			scanf("%d", &g[i][j]);
		}
	}

	int dp[16][16][1 << 16 + 1] = {};

	REP(i, r) {
		dp[i][i][1 << i] = 1;
	}

	REP(k, 1 << r) {
		REP(i, r) {
			REP(j, r) {
				if (i == j) continue;
				if (k & (1 << j) && k & (1 << i)) {
					REP(l, r) {
						if (g[j][l] && k & (1 << l)) {
							dp[i][j][k] += dp[i][l][k ^ (1 << j)];
							dp[i][j][k] %= MODU;
						}
					}
				}

			}
		}
	}
	fc def = {};

	REP(i, r) {
		REP(j, r) {
			REP(k, 1 << r) {
				def[i][j] += dp[i][j][k];
				def[i][j] %= MODU;
			}
		}
	}

	fc fdp[32] = {};

	fdp[0] = def;

	rep(i, 1, 32) {
		REP(j, r) {
			REP(k, r) {
				REP(l, r) {
					fdp[i][j][l] += (1LL*fdp[i - 1][j][k] * fdp[i - 1][k][l])%MODU;
					fdp[i][j][l] %= MODU;
				}
			}
		}
	}

	int cur = 1;
	fc ans = def;
	while (cur < h) {
		int ad = 0;
		while (cur + (1<<ad) <= h) {
			ad++;
		}
		ad--;
		fc ca = {};
		REP(j, r) {
			REP(k, r) {
				REP(l, r) {
					ca[j][l] += (1LL * ans[j][k] * fdp[ad][k][l]) % MODU;
					ca[j][l] %= MODU;
				}
			}
		}

		ans = ca;
		cur += 1 << ad;
	}
	cout << ans[0][0] << endl;
	return 0;
}

