        fac[i] = fac[i - 1] * i % mod;
        inv[i] = mod - inv[mod%i] * (mod / i) % mod;
        finv[i] = finv[i - 1] * inv[i] % mod;
    }
}

// 二項係数計算
ll nCk(ll n, ll k){
    if(fac[0] == 0)COMinit();
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % mod) % mod;
}
//nのm乗をMODで割ったあまりO(logm)
ll modpow(ll n,ll m,ll MOD){
    if(m == 0)return 1;
    if(m < 0)return -1;
    ll res = 1;
    while(m){
        if(m & 1)res = (res * n) % MOD;
        m >>= 1;
        n *= n;
        n %= MOD;
    }
    return res;
}
ll mypow(ll n,ll m){
    if(m == 0)return 1;
    if(m < 0)return -1;
    ll res = 1;
    while(m){
        if(m & 1)res = (res * n);
        m >>= 1;
        n *= n;
    }
    return res;
}

struct segtree{
    ll n;
    vector<ll> dat;
    segtree(ll _n):n(),dat(_n * 4,0){
        ll x = 1;
        while(x < _n){
            x *= 2;
        }
        n = x;
    }
    void update(ll a,ll m){
        a += n - 1;
        dat[a] += m;
        while(a > 0){
            a = (a - 1) / 2;
            dat[a] = dat[a * 2 + 1] + dat[a * 2 + 2];
        }
        return;
    }
    ll query_sub(ll a,ll b,ll k,ll l,ll r){
        if(l >= b || r <= a){
            return 0;
        }
        else if(a <= l && r <= b){
            return dat[k];
        }
        else{
            ll le = query_sub(a,b,k * 2 + 1,l,(l + r) / 2);
            ll ri = query_sub(a,b,k * 2 + 2,(l + r) / 2,r);
            return le + ri;
        }
    }
    ll query(ll a,ll b){
        return query_sub(a,b,0,0,n);
    }
};
