using namespace std;


struct node {
	int begin;
	int end;
	int sum = 0;
	node* child1;
	node* child2;
	node(int begin, int end) {
		this->begin = begin;
		this->end = end;
	}
};

vector<node*> tree;

node* init(int begin, int end) {
	tree.push_back(new node(begin, end));
	int parent = tree.size() - 1;
	if (begin != end) {
		int mid = (begin + end) / 2;
		tree[parent]->child1 = init(begin, mid);
		tree[parent]->child2 = init(mid + 1, end);
	}
	return tree[parent];
}

void add(int x, int y) {
	node* nod = tree[0];
	while (nod->begin != nod->end) {
		nod->sum += y;
		if (x <= nod->child1->end)
			nod = nod->child1;
		else
			nod = nod->child2;
	}
	nod->sum += y;
}

int getSum(node* nod, int x, int y) {
	if (nod->end < x)
		return 0;
	if (nod->begin > y)
		return 0;
	if (nod->begin == x && y == nod->end)
		return nod->sum;
	return getSum(nod->child1, x, min(x,nod->child1->end)) + getSum(nod->child2, max(nod->child2->begin,y), y);	
}

int main() {
	int n, q;
	cin >> n >> q;
	init(0, n);
	for (int i = 0; i < q; ++i) {
		int com, x, y;
		cin >> com >> x >> y;
		if (com == 0)
			add(x, y);
		else
			cout << getSum(tree[0],x, y) << endl;
	}
}

