struct SegmentTree {
  int n;
  vi node;
  SegmentTree(int sz) {
    int n_ = 1;
    while(n_ < sz) {
      n_ *= 2;
    }
    n = n_;
    node.resize(2*n, 0);
  }
  void build(vi v) {
    for(int i=0;i<((int)(v.size()));++i) {
      node[i+n-1] = v[i];
    }
    for(int i=n-2;i>=0;--i) {
      node[i] = node[2*i+1] + node[2*i+2];
    }
  }
  void update(int idx, int val) {
    idx += n-1;
    node[idx] += val;
    if(idx == 0) return;
    idx = (idx - 1) / 2;
    while(1) {
      node[idx] = node[2*idx+1] + node[2*idx+2];
      if(idx == 0) break;
      idx = (idx-1)/2;
    }
  }
  int query(int a, int b) {
    return query(a, b, 0, n, 0);
  }
