  int query(int a, int b, int l, int r, int k) {
    if(a <= l && r <= b) return node[k];
    if(r <= a || b <= l) return 0;
    int v1 = query(a, b, l, (l+r)/2, 2*k+1);
    int v2 = query(a, b, (l+r)/2, r, 2*k+2);
    return v1 + v2;
  }
};
