class SegTreeSum {
public:
    int n;
    vector< int > node;

    SegTreeSum(vector< int > v) {
        int sz = v.size();
        n = 1;
        while( n < sz ) n <<= 1;
        node.resize(2 * n - 1, INF);

        for( int i = 0; i < sz; ++i ) {
                node[i + n - 1] = v[i];

        }
        for( int i = n - 2; i >= 0; --i ) {
            node[i] = node[2 * i + 1] + node[2 * i + 2];

        }
    }

    void Update(int x, int val) {
        x += n - 1;
        node[x] += val;
        while( x > 0 ) {
            x = (x - 1) >> 1;
            node[x] = node[2 * x + 1] + node[2 * x + 2];

        }
    }

    int Query(int a, int b, int k = 0, int l = 0, int r = -1) {
        if( r < 0 ) {
            r = n;

        }

        if( r <= a || b <= l ) {
            return 0;

        }
        if( a <= l && r <= b ) {
            return node[k];

        }

        int vl = Query(a, b, 2 * k + 1, l, (l + r) / 2);
        int vr = Query(a, b, 2 * k + 2, (l + r) / 2, r);
        return vl + vr;

    }

};

