template<typename T>
class DynamicSegmentTree {
 public:
  explicit DynamicSegmentTree(int size, const T& init = 0, const std::function<T(T, T)>& op = std::plus<T>()) : SIZE(size), INIT(init), OP(op), ROOT(std::make_unique<Node>(init)) {}
  T find(int left, int right) const {assert(left<=right); assert(0<=left); assert(right<SIZE); return find(left, right + 1, ROOT, 0, SIZE);}
  void update(int index, const T& value) {assert(0<=index && index<SIZE); update(index, value, ROOT, 0, SIZE);}

 private:
  struct Node {
    T value;
    std::unique_ptr<Node> left_child, right_child;
    Node(const T& init) : value(init) {}
  };

  T find(int a, int b, const std::unique_ptr<Node>& n, int l, int r) const {
    if(b <= l || r <= a) return INIT;
    if(a <= l && r <= b) return n->value;
    T vl = INIT, vr = INIT;
    if(n->left_child) vl = find(a, b, n->left_child, l, (l + r) / 2);
    if(n->right_child) vr = find(a, b, n->right_child, (l + r) / 2, r);
    return OP(vl, vr);
  }
  T update(int i, const T& value, const std::unique_ptr<Node>& n, int l, int r) {
    if(i < l || r <= i) return n->value;
    if(l == i && r - 1 == i) return n->value = value;
    if(not n->left_child)  n->left_child  = std::make_unique<Node>(INIT);
    if(not n->right_child) n->right_child = std::make_unique<Node>(INIT);
    auto vl = update(i, value, n->left_child, l, (l + r) / 2);
    auto vr = update(i, value, n->right_child, (l + r) / 2, r);
    return n->value = OP(vl, vr);
  }

  const int SIZE;
  const T INIT;
  const std::function<T(T, T)> OP;
  const std::unique_ptr<Node> ROOT;
};

