template<class T, T def> struct SuperSegTree {
    struct dice {mt19937 mt; dice() { random_device rd; mt = mt19937(rd()); }
        int operator()(int x) { return this->operator()(0, x - 1); }
        int operator()(int x,int y){uniform_int_distribution<int> dist(x,y);return dist(mt); }} dc;
    struct Node {
        int val;Node *lch, *rch;int sz;T data,ans;Node(int a,T d):val(a),lch(0),rch(0),sz(1){init(d);}
        void init(T d) { data = d; ans = data; }void push() { }
        void update(){ans=data;if(lch) ans=comp(ans, lch->ans);if (rch) ans = comp(ans, rch->ans);}

        // Modify!! -----------------------------
        T comp(T a, T b) { return a + b; }
        // --------------------------------------
    };

    SuperSegTree() { root = new Node(inf, def); }
    Node *root;
    inline int getsz(Node *t) { return t ? t->sz : 0; }
    int getsz() { return getsz(root); }
    inline void push(Node *t) {if (t == NULL)return;t->push();}
    inline Node *update(Node *t) {if (!t)return NULL;t->sz = getsz(t->lch) + getsz(t->rch) + 1;
        t->update();return t;}
    Node *merge(Node *a, Node *b) {push(a); push(b);if (!a)return b;if (!b)return a;
        if (dc(getsz(a) + getsz(b))<getsz(a)) {a->rch = merge(a->rch, b);return update(a);}
        else {b->lch = merge(a, b->lch);return update(b);}}
    template<class... V> Node *merge(Node *a, V... y) { return merge(a, merge(y...)); }
    pair<Node *, Node *>split(Node *t, int k) { // [0,k) [k,N)
        push(t);if (!t)return make_pair(t, t);if (k <= getsz(t->lch)) {
        pair<Node *, Node *>s = split(t->lch, k);t->lch = s.second;
        return make_pair(s.first, update(t));}
        else {pair<Node *, Node *>s = split(t->rch, k - getsz(t->lch) - 1);t->rch = s.first;
        return make_pair(update(t), s.second);}}
    int lower_bound(int x) { return lower_bound(root, x); }
    int lower_bound(Node *t,int x){push(t);if(!t)return 0;if(t->val>=x)return lower_bound(t->lch,x);
        return lower_bound(t->rch, x) + getsz(t->lch) + 1;}
    tuple<Node*, Node*, Node*> split3(int l, int r) { // [0,l) [l,r] (r,N)
        auto p = split(root, l); auto a = p.first; auto q = split(p.second, r - l + 1);
        auto b = q.first;auto c = q.second;root = 0;return make_tuple(a, b, c);}
    void dump() { dump(root); cout << endl; }
    void dump(Node *t) {if (t == NULL)return;push(t);dump(t->lch);
        cout << t->val <<" : " << t->data << endl;dump(t->rch);}
    T get(int i) {return get(i, i);}
    void update(int i, T v) {int k = lower_bound(i);Node *a, *b, *c;tie(a, b, c) = split3(k, k);
        if (b != NULL && b->val == i) b = new Node(i, v);else b = merge(new Node(i, v), b);
        root = merge(a, b, c);}
    T get(int l, int r) { // [l,r]
        int kl = lower_bound(l);int kr = lower_bound(r);Node *a, *b, *c;tie(a, b, c) = split3(kl, kr);
        T res = def;if (kl == kr) {if (b) if(l <= b->val && b->val <= r) res = b->ans;} else {
        if (b) res = b->ans;}root = merge(a, b, c);return res;}
    void add(int i, T v) {update(i, get(i) + v);}
};
