void init(){
  n_ = 1;
  while(n_<n)n_*=2;
  FOR(i,0,2*n_-1)st[i]=0;
}

void update(int a,int b){
  a+=n_-1;
  st[a] += b;
  while(a>0){
    a = (a-1)/2;
    st[a] = st[a*2+1]+st[a*2+2];
  }
}

int find(int a,int b,int c,int l,int r){
  if(r<=a || b<=l)return 0;
  if(a<=l && r<=b)return st[c];

  int L = find(a,b,c*2+1,l,(l+r)/2);
  int R = find(a,b,c*2+2,(l+r)/2,r);
  return L+R;
}

