// Segment-Tree
struct SegmentTree {
  int n;
  vector<ll> dat;

  SegmentTree(int _n) {
    init(_n);
  }

  void init(int _n) {
    n = 1;
    while (n < _n) n *= 2;
    dat.resize(2 * n - 1, 0);
  }

  // i番目の値にxを加算
  void add(ll i, ll x) {
    i += n - 1; // 葉のノード
    dat[i] += x;
    while (i > 0) { // 更新
      i = (i - 1) / 2;
      dat[i] = dat[2 * i + 1] + dat[2 * i + 2];
    }
  }

  // [a, b)の和
  // k:ノードの番号 [l, r)がkに対応づいている
  // query(a, b, 0, 0, n)と呼ぶ
  ll query(int a, int b, int k = 0, int l = 0, int r = -1) {
    if (r == -1) r = n;
    if (r <= a || b <= l) return 0;
    if (a <= l && r <= b) return dat[k];
    else {
      ll vl = query(a, b, 2 * k + 1, l, (l + r) / 2);
      ll vr = query(a, b, 2 * k + 2, (l + r) / 2, r);
      return vl + vr;
    }
  }
};

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  int n, q;
  cin >> n >> q;

  SegmentTree st(n);

  while (q--) {
    ll com, x, y;
    cin >> com >> x >> y;
    if (com == 0) {
      x--;
      st.add(x, y);
    }
    else {
      x--;
      y--;
      cout << st.query(x, y + 1) << '\n';
    }
  }
}

