#define SEG_LEN (1 << 18) //10^5 より大きい２進数, index = 1から利用する．
int seg[SEG_LEN * 2];

void add(int ind, int x){
  ind += SEG_LEN;
  seg[ind] += x;
  while(true){
    ind /= 2;
    if(ind == 0) break;
    seg[ind] = seg[ ind * 2 ]+seg[ ind * 2 + 1 ];
  }

}

int sum(int l, int r){
  l += SEG_LEN;
  r += SEG_LEN;
  int ans = 0;
  while(l < r){
    if(l%2 == 1){
      ans += seg[l];
      l++;
    }
    l /= 2;

    if(r%2 == 1){
      ans += seg[r - 1];
      r--;
    }
    r /= 2;
  }
  return ans;
}

