#include <bits/stdc++.h>
using namespace std;

template <typename T>
class SegmentTree
{
private:
  using Fn = function<T(T, T)>;
  int N;
  vector<T> dat;
  T unit;
  Fn func;

public:
  SegmentTree() {}
  SegmentTree(int n_, Fn func_, T unit_) : func(func_), unit(unit_)
  {
    N = 1;
    while (N < n_)
      N *= 2;
    dat.assign(2 * N - 1, unit);
  }
  SegmentTree(vector<T> v, Fn func_, T unit_) : func(func_), unit(unit_)
  {
    N = 1;
    int sz = v.size();
    while (N < sz)
      N *= 2;
    dat.resize(2 * N - 1);
    for (int i = 0; i < N; ++i)
      dat[i + N - 1] = (i < sz ? v[i] : unit);
    for (int i = N - 2; i >= 0; --i)
      dat[i] = func(dat[i * 2 + 1], dat[i * 2 + 2]);
  }

  // k 番目の要素を a に変更
  void update(int k, T a)
  {
    k += N - 1;
    dat[k] = a;
    while (k > 0)
    {
      k = (k - 1) / 2;
      dat[k] = func(dat[k * 2 + 1], dat[k * 2 + 2]);
    }
  }

  // k 番目の要素を取得
  T get(int k) { return dat[k + N - 1]; }

  // 区間 [l, r) の和を取得
  T query(int l, int r)
  {
    T vl = unit, vr = unit;
    for (l += (N - 1), r += (N - 1); l < r; l >>= 1, r >>= 1)
    {
      if ((l & 1) == 0)
        vl = func(vl, dat[l]);
      if ((r & 1) == 0)
        vr = func(vr, dat[--r]);
    }
    return func(vl, vr);
  }
};

int main()
{
  int n, q;
  cin >> n >> q;
  auto f = [](int a, int b) { return a + b; };
  SegmentTree<int> sg(n, f, 0);
  for (int qi = 0; qi < q; qi++)
  {
    int com, x, y;
    cin >> com >> x >> y;
    if (com == 0) // 変更クエリ
      sg.update(x - 1, sg.get(x - 1) + y);
    else // 求値クエリ
      cout << sg.query(x - 1, y) << "\n";
  }
  return 0;
}

#include <bits/stdc++.h>
using namespace std;

int N, Q;
vector<int> v, t;

int combine(int i, int j) {
    return i + j;
}

void build(int id = 1, int l = 0, int r = N) {
    if (r - l < 2) {
        t[id] = v[l];
        return;
    }

    int mid = (l + r) / 2;
    build(id<<1  , l, mid);
    build(id<<1|1, mid, r);
    t[id] = combine(t[id<<1], t[id<<1|1]);
}

void modify(int p, int val, int id = 1, int l = 0, int r = N) {     // set v[p] = val
    if (r - l < 2) {
        t[id] += val;
        return;
    }

    int mid = (l + r) / 2;
    if (p < mid)
        modify(p, val, id<<1  , l, mid);
    else
        modify(p, val, id<<1|1, mid, r);

    t[id] = combine(t[id<<1], t[id<<1|1]);
}

int query(int x, int y, int id = 1, int l = 0, int r = N) {         // query in range [l,r)
    if (x >= r || l >= y) return 0;
    if (x <= l && r <= y) return t[id];

    int mid = (l + r) / 2;
    return combine(query(x,y,id<<1,l,mid), query(x,y,id<<1|1,mid,r));
}

int main() {

    scanf("%d%d",&N,&Q); t.assign(N<<2,0);
    for (int i = 0, op, x, y; i < Q; i++) {
        scanf("%d%d%d",&op,&x,&y);

        if (op) 
            printf("%d\n", query(x-1,y));
        else 
            modify(x-1,y);

    }

    return 0;
}

