typedef int BIT_T;
class BIT
{
private:
  vector<BIT_T> bit;
public:
  BIT(int n)
  {
    bit.resize(n+1,0);
  }

  //index 0 to i の和を返す
  BIT_T sum(int i)
  {
    BIT_T s=0;
    while(i>0){
      s+=bit[i];
      i-=i& (-i);//i& -i はiの最小1bit  <- 2^kを引く
    }
    return s;
  }

  //index i to j の和
  BIT_T sum(int i,int j)
  {
    return sum(j)-sum(i-1);
  }

  //index i に x をたす
  void add(int i,BIT_T x){
    while(i<=bit.size()){
      bit[i]+=x;
      i+=i& (-i);
    }
  }
};


