int n;
vector<int> dat;

void init(int _n){
  n = 1;
  while(n < _n) n *= 2;
  dat.resize(n*2-1,0);
  rep(i,n*2-1){
    dat[i] = 0;
  }
}

void update(int i, int x){
  i += n-1;
  dat[i] += x;
  while(i > 0){
    i = (i-1)/2;
    dat[i] = dat[i*2+1] + dat[i*2+2];
  }
}

int getSum(int x, int y, int k, int l, int r){
  if(r <= x || y <= l) return 0;
  if(x <= l && r <= y) return dat[k];
  else{
    int vl = getSum(x,y,k*2+1,l,(l+r)/2);
    int vr = getSum(x,y,k*2+2,(l+r)/2,r);
    return vl + vr;
  }
}
