// binary-indexed-tree template
// note that BIT is 1-indexed
// arr -> a_0, a_1, ..., a_{n-1}
template< typename T >
struct FenwickTree {
    vector<T> a;

    FenwickTree (int size){
        a.assign(size + 1, 0);
    }

    // find the sum [0, t]
    T sum (int i){
        T ret = 0;
        while(i > 0){
            ret += a[i];
            i = i & (i-1);
        }
        return ret;
    }

    // find the sum [s, t]
    T sum_range (int s, int t){
        return sum(t) - sum(s-1);
    }

    // update a_i -> a_i + x
    void add (int i, T x){
        for (++i; i < (int)(a.size()); i += i & -i){
            a[i] += x;
        }
        return;
    }
};

