template <class T>
struct SegTree {
    int n;
    T identity;
    std::vector<T> values;
    std::function<T(T, T)> operateF;
    std::function<T(T, T)> updateF;

    SegTree(
        int n,
        T identity,
        std::function<T(T, T)> operateF,
        std::function<T(T, T)> updateF
    ) {
        this->identity = identity;
        this->operateF = operateF;
        this->updateF = updateF;

        int node = 1;
        while (node < n) node *= 2;
        this->n = node;
        this->values = std::vector<T>(2*node-1, identity);
    }

    void update(int i, T x) {
        i += n - 1;
        values[i] = updateF(values[i], x);
        while (i > 0) {
            i = (i-1) / 2;
            values[i] = operateF(values[i*2+1], values[i*2+2]);
        }
    }

    T query(int a, int b) {
        return _query(a, b, 0, 0, n);
    }

    T operator[](int i) {
        return values[i+n-1];
    }

private:
    T _query(int a, int b, int k, int l, int r) {
        if (r <= a || b <= l) return identity;
        if (a <= l && r <= b) return values[k];

        T childL = _query(a, b, 2*k+1, l, (l+r)/2);
        T childR = _query(a, b, 2*k+2, (l+r)/2, r);
        return operateF(childL, childR);
    }
};

int n, q;

int main() {
    cin >> n >> q;
    SegTree<ll> t = SegTree<ll>(
        n, 0,
