class Bucket{
  public:
  vector<ll> buc,v;
  ll n,sqn;
  Bucket(){};
  Bucket(ll N){
    n = N;
    buc.resize(sqrt(n) + 1);
    sqn = sqrt(n);
    v.resize(n);
  }
  void add(int k,int d){
    v[k] += d;
    buc[k / sqn] += d;
  }
  ll query(ll l,ll r){
    ll res = 0;
    for(int i = l; i < min((l / sqn + 1) * sqn,r);++i){
      res += v[i];
    }
    for(int i = r; i >= max(l,(r / sqn) * sqn);--i){
      res += v[i];
    }
    for(int i = l / sqn + 1; i < r / sqn;++i){
      res += buc[i];
    }
    return res;
  }
  void Debug(){
    for(int i = 0; i < n;++i){
      cout << buc[i/sqn] << ' ';
    }
    cout << endl;
    for(int i = 0; i < n;++i){
      cout << v[i] << ' ';
    }
    cout << endl;
  }
};

