int getSum(int x, int y){
    x += SEG_NUM;
    y += SEG_NUM;
    int ans = 0;
    while(x < y){
        if(x % 2 == 1){
            ans += seg[x];
            x++;
        }
        x /= 2;
        if(y % 2 == 1){
            ans += seg[y - 1];
            y--;
        }
        y /= 2;
    }
    return ans;
}

