class BIT
{
  private:
    vector<T> array;
    int N;

  public:
    BIT(int size) : array(size + 1, 0), N(size) {}

    T sum(int i)
    {
        T sum = 0;
        while (i > 0)
        {
            sum += array[i];
            i -= i & -i;
        }

        return sum;
    }

    T sum(int l, int r)
    {
        T res_l = sum(l - 1);
        T res_r = sum(r);

        return res_r - res_l;
    }

    void add(int i, T x)
    {
        while (i <= N)
        {
            array[i] += x;
            i += i & -i;
        }
    }

    int lower_bound(int w)
    {
        if (w <= 0)
        {
            return 0;
        }        

        int init = 1;
        while(init < N)
        {
            init *= 2;
        }

        int x = 0;
        for(int k = init; k > 0; k /= 2)
        {
            if(x + k <= N && array[x + k] < w)
            {
                w -= array[x + k];
                x += k;
            }
        }

        return x + 1;
    }
};

