template<typename T>
struct SqrtTree {

  vector<T> data;
  vector<T> bucket;
  T sq;
  T const init = inf;

  SqrtTree( vector<T> const& v) : data(v) {
    int d_size = data.size();
    sq = sqrt( d_size );
    bucket.resize( (d_size + sq - 1) / sq);
    for(int i = 0; i < d_size; i++) {
      if(i % sq == 0) {bucket[i / sq] = data[i]; }
      bucket[i / sq] = min(bucket[i / sq], data[i]);
    }
  }

  // [l, r]
  T query(int l, int r) {
    T res = init; // change here!
    int i = l;
    while(i <= r) {
      if(i % sq == 0 && i + sq <= r) {
        // change here!
        res = min(res,  bucket[ i / sq ]);
        i += sq;
      } else {
        // change here!
        res = min(res, data[i]);
        i++;
      }
    }
    return res;
  }

  void update(int i, T x) {
    // change here!
    data[i] = x;
    // bucket ?????´??°
    bucket[i / sq] = init;
    for(int k = 0; k < sq; k++) {
      int cur_i = (i / sq) * sq + k;
      if( (int)data.size() <= cur_i) { break; }
      bucket[i / sq] = min(bucket[i / sq], data[ cur_i ]);
    }
  }

  void print() {

    int tab = 5;

    for(int i = 0; i < (int)bucket.size(); i++ ) {
      string x;
      if(bucket[i] == init) { x = "I"; }
      else                 { x = to_string(bucket[i]); }
      cout << setw(tab*sq) << x;
    }

    cout << "\n";

    for(int i = 0; i < (int)data.size(); i++ ) {
      string x;
      if(data[i] == init) { x = "I"; }
      else                 { x = to_string(data[i]); }
      cout << setw(tab) << x;
    }

    cout << "\n";
  }

};



