//BinaryIndexTree(siz):長さsizで初期化
//sum(k):区間[0,k]の和を求める
//add(k,x):要素kにxを加える

template<typename T>
struct BinaryIndexTree {

	vector<T> data;
	T siz;

	BinaryIndexTree(T n)
	{
		//1-indexなので配列は1つ多めに用意する
		siz = n;
		data.resize(siz + 1, 0);
	}
	T sum(T k)
	{
		//a_1～a_kまでの和を計算
		T ret = 0;
		for (int i = k; i > 0; i -= (i & -i))
		{
			ret += data[i];
		}
		return ret;
	}

	T sum_between(T i, T j) {
		if (i > j) {
			return 0;
		}
		else
		{
			return sum(j) - sum(i - 1);
		}
	}

	void add(T k, T x)
	{
		//a_kにxを加算する
		for (T i = k; i < data.size(); i += (i & -i))
		{
			data[i] += x;
		}
	}

	T lower_bound(T w) {
		if (w <= 0) return 0;
		T x = 0, r = 1;
		while (r < siz) r <<= 1;
		for (T k = r; k > 0; k >>= 1) {
			if (x + k <= siz && data[x + k] < w) {
				w -= data[x + k];
				x += k;
			}
		}
		return x + 1;
	}


};




