}

void add(int i, int y){
	int k;
	k=n-1+i;
	dat[k] += y;
	while(k>0){
		k=(k-1)/2;
		dat[k]+=y;
	}
}

int find(int x, int y, int k,int l,int r){
	if(r <= x || l >= y){
		return 0;
	}
	if(r <= y && l >= x){
		return dat[k];
	}else{
		int vl = find(x,y,2*k+1,l,(l+r)/2);
		int vr = find(x,y,2*k+2,(l+r)/2,r);
		return vl+vr;
	}
}

