typedef long long ll;
const ll inf=1e18;
struct segtree{
    private:
    vector<ll> node_min,node_max,node_sum;
    ll siz;
    public:
    segtree(ll n){
        siz=1;
        while(siz<n) siz*=2;
        node_min.resize(siz*2,0);
        node_max.resize(siz*2,0);
        node_sum.resize(siz*2,0);
    }
    void upd(ll pos,ll x){
        pos+=siz-1;
        node_min[pos]=x;
        node_max[pos]=x;
        ll pls=x-node_sum[pos];
        node_sum[pos]=x;
        while(pos>0){
            pos=(pos-1)/2;
            node_min[pos]=min(node_min[pos*2+1],node_min[pos*2+2]);
            node_max[pos]=max(node_max[pos*2+1],node_max[pos*2+2]);
            node_sum[pos]+=pls;
        }
    }
    void add(ll pos,ll x){
        pos+=siz-1;
        node_min[pos]+=x;
        node_max[pos]+=x;
        node_sum[pos]+=x;
        while(pos>0){
            pos=(pos-1)/2;
            node_min[pos]=min(node_min[pos*2+1],node_min[pos*2+2]);
            node_max[pos]=max(node_max[pos*2+1],node_max[pos*2+2]);
            node_sum[pos]+=x;
        }
    }
    ll seq_min(ll l,ll r,ll pos=0,ll a=0,ll b=-1){
        if(b<0) b=siz;
        if(b<=l||r<=a) return inf;
        if(l<=a&&b<=r) return node_min[pos];
        ll mid=(a+b)/2;
        ll lb=seq_min(l,r,pos*2+1,a,mid);
        ll rb=seq_min(l,r,pos*2+2,mid,b);
        return min(lb,rb);
    }
    ll seq_max(ll l,ll r,ll pos=0,ll a=0,ll b=-1){
        if(b<0) b=siz;
        if(b<=l||r<=a) return 0;
        if(l<=a&&b<=r) return node_max[pos];
        ll mid=(a+b)/2;
        ll lb=seq_max(l,r,pos*2+1,a,mid);
        ll rb=seq_max(l,r,pos*2+2,mid,b);
        return max(lb,rb);
    }
    ll seq_sum(ll l,ll r,ll pos=0,ll a=0,ll b=-1){
        if(b<0) b=siz;
        if(b<=l||r<=a) return 0;
        if(l<=a&&b<=r) return node_sum[pos];
        ll mid=(a+b)/2;
        ll lb=seq_sum(l,r,pos*2+1,a,mid);
        ll rb=seq_sum(l,r,pos*2+2,mid,b);
        return lb+rb;
    }
};
int main(){
    ll n,q;
    cin>>n>>q;
    segtree seg(n+1);
    for(int i=0;i<q;i++){
        ll c,x,y;
        cin>>c>>x>>y;
        if(c==0) seg.add(x,y);
        else cout<<seg.seq_sum(x,y+1)<<endl;
    }
}

