template<typename T>
struct SqrtTree {

  vector<T> data;
  vector<T> bucket;
  T sq;

  SqrtTree( vector<T> const& v) : data(v) {
    int d_size = data.size();
    sq = sqrt( d_size );
    bucket.resize( (d_size + sq - 1) / sq);
    for(int i = 0; i < d_size; i++) {
      if(i % sq == 0) {bucket[i / sq] = data[i]; }
      bucket[i / sq] += data[i]; // change here!
    }
  }

  // [l, r]
  T query(int l, int r) {
    T res = 0;// change here!
    int i = l;
    while(i <= r) {
      if(i % sq == 0 && i + sq <= r) {
        // change here!
        res += bucket[ i / sq ];
        // res = min(res,  bucket[ i / sq ]); RMQ
        i += sq;
      } else {
        // change here!
        res += data[i];
        i++;
      }
    }
    return res;
  }

  void update(int i, T x) {
    // change here!
    // bucket[i / sq] -= data[i];
    data[i] += x;
    bucket[i / sq] += x;

    // RMQ
    // bucket[i / sq] = min(x, bucket[i / sq]);
    // data[i] = x;
  }

  void print() {

    for(int i = 0; i < (int)bucket.size(); i++ ) {
      cout << setw(2*sq) << bucket[i];
    }

    cout << "\n";

    for(int i = 0; i < (int)data.size(); i++ ) {
      cout << setw(2) << data[i];
    }

    cout << "\n";
  }

};



