int sum(int l, int r){
  l += SEG_LEN;
  r += SEG_LEN;
  int ans = 0;
  while(l < r){ 
    if(l %2 == 1){ 
      ans += seg[l];
      l++;
    }
    l /= 2;
    if(r % 2 == 1){ 
      ans += seg[r-1];
      r--;
    }
    r /= 2;
  }
  return ans;
}


