template<class T>
struct SqrtDecomposition{
  using F=std::function<T(T,T)>;
  const int sqrtN = 512;
  int n,k;
  T ide_ele;
  std::vector<T> data,bucket;
  F fn;

  //初期化
  SqrtDecomposition(int n,T ide_ele,F fn) : n(n), ide_ele(ide_ele) , fn(fn) {
    k = (n+sqrtN-1)/sqrtN;
    data.assign(k*sqrtN,ide_ele);
    bucket.assign(k,ide_ele);
  }

  //data[index]に(T)xを加算して更新
  void add(int index, T x){
    data[index] += x;
    k = index/sqrtN;
    T sum = ide_ele;
    for(int i = k*sqrtN; i<(k+1)*sqrtN; i++){
      sum = fn(sum,data[i]);
    }
    bucket[k] = sum;
  }

  //[l,r)においてクエリ処理
  T query(int l,int r){
    int k_l = l/sqrtN;
    int k_r = r/sqrtN;
    T sum = ide_ele;
    if(k_l==k_r){
      for(int i = l; i<r; i++){
        sum = fn(sum,data[i]);
      }
      return sum;
    }
    for(int i = l; i<(k_l+1)*sqrtN; i++){
      sum = fn(sum,data[i]);
    }
    for(int i = k_r*sqrtN; i<r; i++){
      sum = fn(sum,data[i]);
    }
    for(int i = (k_l+1); i<k_r; i++){
      sum = fn(sum,bucket[i]);
    }
    return sum;
  }
};

