class SegmentTreeSum{
    int n = 0;
    vector<int> dat;
public:
    SegmentTreeSum(){}
    SegmentTreeSum(int m, int fill = 0){
        int i = 1;
        while(i < m) i *= 2;
        n = i;
        dat.resize(2*i - 1);
        REP(j, 2*i-1) dat[j] = fill;
    }

    void update(int k, int a){
        k += n - 1;
        int moto = dat[k];
        dat[k] = a;
        while(k){
            k = (k - 1) / 2;
            dat[k] += a - moto;
        }
    }

    void updateIncrease(int k, int a){
        update(k, dat[k+n-1] + a);
    }
    void updateIncrease(int k){
        updateIncrease(k, 1);
    }

    void updateDecrease(int k, int a){
        update(k, dat[k+n-1] - a);
    }
    void updateDecrease(int k){
        updateDecrease(k, 1);
    }

    int getSum(int a, int b, int k=0, int l=0, int r=-1){
        //[a, b[であることに注意
        if(r < 0) r = n;
        if(r <= a || b <= l) return 0;
        if(a <= l && r <= b) return dat[k];

        int vl = getSum(a, b, 2*k+1, l, (l+r)/2);
        int vr = getSum(a, b, 2*k+2, (l+r)/2, r);
        return vl + vr;
    }

    int getvalue(int k){
        return dat[k+n-1];
    }

    bool getExist(int l, int r){
        //[l, r]
        return (getSum(l, r+1) > 0);
    }
};

