struct RSQ{
    int n;
    vector<int> dat;
    RSQ() {}
    RSQ(int n_) {
        n = 1;
        while(n < n_) n *= 2;
        dat.resize(2 * n - 1, 0);
        // rep(i, 0, 2 * n - 1) dat[i] = MAX;
    }
    void add(int k, int a){
        k += n - 1;
        dat[k] += a;
        while(k > 0){
            k = (k - 1) / 2;
            dat[k] = dat[2 * k + 1] + dat[2 * k + 2];
        }
    }
    //sum[a, b)
    int query(int a, int b){
        return query(a, b, 0, 0, n);
