struct BinaryIndexedTree {
	vector<T> data;

	BinaryIndexedTree(int size):data(size+1,0) {}

	T sum(int k) {
		T res=0;
		for(++k;k>0;k-=(k&-k)) res+=data[k];
		return res;
	}

	void add(int k,T x) {
		for(++k;k<(int)data.size();k+=(k&-k)) data[k]+=x;
	}
};

