  public:

    SegmentTree() = default;

    SegmentTree(int size, function<T(T, T)> query_func,
                function<T(T, E)> update_func, T identity,
                vector<T> v = vector<T>())
            : query_func(query_func), update_func(update_func), identity(identity) {
        n = 1;
        while(n < size) n *= 2;
        node.resize(2*n-1, identity);
        if(size == v.size()) build(size, v);
    }

    void build(int size, vector<T> v) {
        for(int i=0;i<size;++i) node[i+n-1] = v[i];
        for(int i=n-2;i>=0;--i) node[i] = query_func(node[2*i+1], node[2*i+2]);
    }

    void update(int x, E val) {
        x += n - 1;

        node[x] = update_func(node[x], val);
        while(x > 0) {
            x = (x - 1) / 2;
            node[x] = query_func(node[2*x+1], node[2*x+2]);
        }
    }

    T query(int a, int b, int k=0, int l=0, int r=-1) {
        if(r < 0) r = n;

        if(r <= a || b <= l) return identity;

        if(a <= l && r <= b) return node[k];

        int vl = query(a, b, 2*k+1, l, (l+r)/2);
        int vr = query(a, b, 2*k+2, (l+r)/2, r);
        return query_func(vl, vr);
    }
};

int main(){
    int n, q;
    cin >> n >> q;
    SegmentTree<i64, i64> st(n+1,
        [](i64 a, i64 b){return a+b;},
        [](i64 a, i64 b){return a+b;},
        0
    );
    for(int i=0;i<q;++i){
        int com, x, y;
        cin >> com >> x >> y;
        if(com == 0){
            st.update(x, y);
        }else{
            cout << st.query(x, y+1) << endl;
        }
    }

    return 0;
}

