int getSum(int a, int b, int k, int l, int r, vector<int>& node) {
	if (a <= l && r <= b) return node[k];
	if (r <= a || b <= l) return 0;
	return getSum(a, b, 2*k + 1, l, (l + r)/2, node) + getSum(a, b, 2 * k + 2, (l + r)/2, r, node);
}


