ll s[4*N];

void update(int idx, int l, int r, int i, int v){
	if(i < l || i > r) return;
	if(i == l && i == r) {s[idx] += v; return;}
	update(ldx, l, mdx, i, v);
	update(rdx, mdx + 1, r, i, v);
	s[idx] = (s[ldx] + s[rdx]);	
}

ll query(int idx, int l, int r, int i, int j){
	if(j < l || i > r) return 0;
	if(l >= i && r <= j) return s[idx];
	return (query(ldx, l, mdx, i, j) + query(rdx, mdx + 1, r, i, j));	
}

