template <typename T>
class BIT
{
public:
    BIT(int size, T unity = 0) : bit(++size, unity), _unity(unity) {}

    // [a, b)の和を計算する
    T sum(int a, int b) {
        return _sum(b - 1) - _sum(a - 1);
    }

    // i番目の要素にxを加算
    void add(int i, T x) {
        for (++i; i < (int)bit.size(); i += i & -i) bit[i] += x;
    }

private:
    vector<T> bit;
    T _unity;

    T _sum(int i) {
        T s = _unity;
        for (++i; i > 0; i -= i & -i) s += bit[i];
        return s;
    }
};


int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);

    int n, q; cin >> n >> q;
    BIT<int> bit(n);
    for (int i = 0; i < q; i++) {
        int c, x, y; cin >> c >> x >> y;
        if (!c) bit.add(x - 1, y);
        else    cout << bit.sum(x - 1, y) << endl;
    }
    return 0;
}

