const int SEG_SIZE = 1<<17;

int Seg_tree[SEG_SIZE*2];


void add(int i,int x)
{
   int now = i+SEG_SIZE;
   while(1)
   {
      Seg_tree[now] += x;
      now/=2;
      if(now==0)break;
   }
}

int getSum(int l,int r)
{
   int res = 0;
   l+=SEG_SIZE;
   r+=SEG_SIZE;
   while(1)
   {

      if(l%2==1)
      {
         res+=Seg_tree[l];
         l++;
      }

      if(r%2==1)
      {
         res+=Seg_tree[r-1];
         r--;
      }
      if(l==r)break;
      l/=2;
      r/=2;
   }
   return res;
}


