class Segtree {
  struct Node {
    Node *lch, *rch;
    long long sum;
    Node() : sum(0), lch(nullptr), rch(nullptr) {}
    ~Node() {
      // if (lch != nullptr) delete lch;
      // if (rch != nullptr) delete rch;
    }
    void add(ll x, ll val, ll lb, ll ub) {
      if (x >= ub) return;
      Node* node = this;
      while (ub - lb > 1) {
        node->sum += val;
        ll mid = (lb + ub) / 2;
        if (x < mid) {
          if (node->lch == nullptr) node->lch = new Node();
          node = node->lch;
          ub = mid;
        }
        else {
          if (node->rch == nullptr) node->rch = new Node();
          node = node->rch;
          lb = mid;
        }
      }
      node->sum += val;
    }
    long long find(ll r, ll lb, ll ub) {
      long long res = 0;
      Node* node = this;
      while (node != nullptr) {
        ll mid = (lb + ub) / 2;
        if (ub == r) {
          res += node->sum;
          break;
        }
        else if (r < mid) {
          ub = mid;
          node = node->lch;
        }
        else {
          if (node->lch != nullptr) res += node->lch->sum;
          lb = mid;
          node = node->rch;
        }
      }
      return res;
    }
  };
  Node *root;
  const ll n;
public:
  Segtree() : Segtree(0) {}
  Segtree(ll n) : root(new Node()), n(n) {}
  void add(ll x, ll val) {
    root->add(x, val, 0, n);
  }
  long long find(ll r) {
    return root->find(r, 0, n);
  }
  ~Segtree() { delete root; }
};

