int update( int ini, int fin, int nd, int s, int v ){

	if( s > fin || v < ini )
		return T[nd];

	if( ini == fin ){
		T[nd] += v;
		return T[nd];
	}

	int m = ( ini + fin ) >> 1;
	int l = ( nd << 1 );
	int r = l | 1;

	int v1 = update( ini, m, l, s, v);
	int v2 = update( m + 1, fin, r, s, v);
	T[nd] = v1 + v2;
	return T[nd];          
}


int query( int ini, int fin, int nd, int qi, int qe ){

	if( qi > fin || qe < ini )
		return 0;

	if( qi <= ini && fin <= qe )
		return T[nd];

	int m = ( ini + fin ) >> 1;
	int l = nd << 1;
	int r = l | 1;

	int v1 = query( ini, m, l, qi, qe );
	int v2 = query( m + 1, fin, r, qi, qe);
	return v1 + v2;
}


