void build(Node *&p,int l,int r)
{
    p=(Node *)malloc(sizeof(Node));
    p->dl=l,p->dr=r,p->s=0;
    p->pl=null,p->pr=null;
    int mid=(l+r)/2;
    if(r>l)
    {
        build(p->pl,l,mid);
        build(p->pr,mid+1,r);
    }
}
int query(Node *&p,int l,int r)
{
    if(p->dl==l &&p->dr==r)
        return p->s;
    int mid=(p->dl+p->dr)/2;
    if(r<=mid)
        return query(p->pl,l,r);
    else if(l>mid)
        return query(p->pr,l,r);
    else
        return query(p->pl,l,mid)+query(p->pr,mid+1,r);
}
void update(Node *&p,int x,int data)
{
    p->s+=data;
    if(p->dl==p->dr)//找到最后一个叶子节点
        return;
    int mid=(p->dl+p->dr)/2;
    if(x<=mid)
        update(p->pl,x,data);
    else
        update(p->pr,x,data);
}
