enum seginit {
    segmin,//[](M a, M b){return a < b ? a : b;}, MAX(M)
    segmax,//[](M a, M b){return a > b ? a : b;},MIN(M)
    segsum,//[](M a, M b){return a + b;} , (M)0
    segmul,//[](M a, M b){return a * b;} , (M)1
    segxor //[](M a, M b){return a ^ b;} , (M)0
};

template<class M> struct SegmentTree {
    using func=function<M(M, M)>;
    int n;
    vector<M> seg;
    func f;
    M e;
    SegmentTree(int len, func f, const M e) : f(f), e(e) {
        n = 1;
        while (n <= len)n <<= 1;
        seg.assign((n << 1) - 1, e);
    }
    SegmentTree(vector<M> dat, seginit s) {
        if (s == segmin) {
            f = [](M a, M b) { return a < b ? a : b; };
            e = MAX(M);
        } else if (s == segmax) {
            f = [](M a, M b) { return a > b ? a : b; };
            e = MIN(M);
        } else if (s == segsum) {
            f = [](M a, M b) { return a + b; };
            e = (M) 0;
        } else if (s == segmul) {
            f = [](M a, M b) { return a * b; };
            e = (M) 1;
        } else if (s == segxor) {
            f = [](M a, M b) { return a ^ b; };
            e = (M) 0;
        }
        n = 1;
        int asz = dat.size();
        while (n <= asz)n <<= 1;
        seg.assign((n << 1) - 1, e);
        rep(i, asz) seg[i + n - 1] = dat[i];
        rer(i, n - 2)seg[i] = f(seg[(i << 1) | 1], seg[(i << 1) + 2]);
    }
    SegmentTree(vector<M> dat, func f, const M e) : f(f), e(e) {
        n = 1;
        int asz = dat.size();
        while (n <= asz)n <<= 1;
        seg.assign((n << 1) - 1, e);
        rep(i, asz) seg[i + n - 1] = dat[i];
        rer(i, n - 2)seg[i] = f(seg[(i << 1) | 1], seg[(i << 1) + 2]);
    }
    void update(int k, M v) {
        seg[k + n - 1] = v;
        k += n - 1;
        while (k) {
            k = (k - 1) >> 1;
            seg[k] = f(seg[(k << 1) | 1], seg[(k << 1) + 2]);
        }
    }
    void del(int k) { update(k, e.v); }
    void add(int k, int v) { update(k, v + seg[k + n - 1]); }
    //高速なquery 葉から辿る
    //@formatter:on
    M query_bottomup(int l, int r) {
        M retl = e;
        M retr = e;
        l += n - 1;
        r += n - 1;
        while (l < r) {            /*右なら、次に右上へ移動してしまうので*/
            if (!(l & 1)) { retl = f(retl, seg[l]); }            /*右なら、左を取らないと機会を逃す*/
            if (!(r & 1)) { retr = f(seg[r - 1], retr); }
            l >>= 1;
            r = (r - 1) >> 1;
        }
        return f(retl, retr);
    }

    M query(int a, int b, int k, int l, int r) {
        if (r <= a || b <= l)return e;
        else if (a <= l && r <= b)return seg[k];
        else {
            M sl = query(a, b, (k << 1) | 1, l, (l + r) >> 1);
            M sr = query(a, b, (k << 1) + 2, (l + r) >> 1, r);
            return f(sl, sr);
        }
    }
    //@formatter:off
    //***************************
    //入れ替えることでbottomupと入れ替えられる
//    Monoid get(int a = 0, int b = -1) { return query(a, b == -1 ? n : b, 0, 0, n); }
    M get(int a = 0, int b = -1) { return query_bottomup(a, b == -1 ? n : b); }
    M getv(int a = 0, int b = -1) { return query_bottomup(a, b == -1 ? n : b); }

    //***************************
    int operator()(int a = 0, int b = -1) { return get(a, b); }
    M operator[](int k) { return seg[k + n - 1]; }
#ifdef _DEBUG
    void debu() {        rep(i, min(n, 10ll)) {            int v = operator[](i).v;            if (v == MIN(ll) || v == MAX(ll)) {                cerr << "e ";            } else {                cerr << v << " ";            }        }        cerr << "" << endl;    }
#else
    inline void debu(){;}
#endif
};
