const int MAX = 1e5 + 5;

int st[4*MAX]; //segtree
int arr[MAX]; //linear array elmt of segtree

int strule(int a, int b){
	return a + b;
}

int getMid(int s, int e){
	return s+(e-s)/2;
}

int buildst(int start, int end, int cur){
	// basis
	if (start == end){
		st[cur] = arr[start];
		return st[cur];
	}

	// reccurence
	int mid = getMid(start, end);
	st[cur] = strule(buildst(start, mid, 2*cur+1), buildst(mid+1, end, 2*cur+2));
}

int find(int ss, int se, int qs, int qe, int cur){
	// all segment inside
	if (qs <= ss && qe >= se){
		return st[cur];
	}

	// all segment outside
	if (se < qs || ss > qe){
		return 0;
	}

	// some segment inside
	int mid = getMid(ss, se);
	return strule(find(ss, mid, qs, qe, 2*cur+1), find(mid+1, se, qs, qe, 2*cur+2));
}

void update(int ss, int se, int index, int val, int cur){
	if(ss == se){
		arr[index] += val;
		st[cur] += val;
	} else {
		int mid = getMid(ss, se);
		if(ss <= index && index <= mid) update(ss, mid, index, val, 2*cur+1);
		else update(mid+1, se, index, val, 2*cur+2);
		st[cur] = strule(st[2*cur+1], st[2*cur+2]);
	}
}

