    ios::sync_with_stdio(false); cin.tie(nullptr);
    int N,Q; cin >> N >> Q;
    BinaryIndexedTree<ll> BIT(N);

    while (Q--) {
        ll com,x,y; cin >> com >> x >> y;
        if (com) {
            cout << BIT.sum(--x,y) << endl;
        } else {
            BIT.add(--x,y);
        }
    }
}

