  vector<i64> tree;

public:
  BIT():size(0),tree(0){};
  BIT(int n):size(n),tree(n+1,0){};
  void add(i64 x,int n){
    for(int i=n;i<=size;i+=i&-i){
      tree[i]+=x;
    }
  }
  i64 sum(int s,int t){
    if(s>t)return 0;
    i64 res=0;
    for(int i=t;i>0;i-=i&-i){
      res += tree[i];
    }
    for(int i=s-1;i>0;i-=i&-i){
      res -= tree[i];
    }
    return res;
  }
  i64 get(int n){
    return tree[n];
  }
};

