constexpr ll MAX_N = 505050;
class BIT {
public:
	BIT(ll N) : N(N) { }
	void add(ll a, ll w) {
		a++;
		for (ll x = a; x <= N; x += x & -x) bit[x] += w;
	}

	ll get(ll a) {
		return sum(a, a + 1);
	}

	ll sum(ll a) {
		a++;
		ll ret = 0;
		for (ll x = a; x > 0; x -= x & -x) ret += bit[x];
		return ret;
	}

	// [a, b) の和を返す
	ll sum(ll a, ll b) {
		if(b == 0 || b - a <= 0) return 0;
		ll ret = sum(b - 1);
		if(a != 0) ret -= sum(a - 1);
		return ret;
	}

	void clear() {
		for(ll i = 0; i < N; i++) bit[i] = 0;
	}
private:
	const ll N;
	ll bit[MAX_N];
};

