{
    cin >> n >> q;
    int size = 1 << (int)(log2(n) + 1);
    seg = vint(2 * size + 1, 0);

    rep(i, q)
    {
        int com, x, y;
        cin >> com >> x >> y;
        if (com)
        {
            int ans = getSum(x, y + 1);
            cout << ans << "\n";
        }
        else
        {
            add(x, y);
        }
    }

    return 0;
}

