//ラングレス圧縮
vector<pair<int, char>> compress(string S) {
	int N = S.size();
	vector<pair<int, char>> memo;

	int tempo = 1;
	for (int i = 1; i < N; i++) {
		if (i != N - 1) {
			if (S.at(i) == S.at(i - 1)) tempo++;
			else {
				memo.push_back(MP(tempo, S.at(i - 1)));
				tempo = 1;
			}
		}
		else {
			if (S.at(i) == S.at(i - 1)) {
				tempo++;
				memo.push_back(MP(tempo, S.at(i - 1)));
			}
			else {
				memo.push_back(MP(tempo, S.at(i - 1)));
				memo.push_back(MP(1, S.at(i)));
			}
		}
	}

	return memo;
}




class BIT {
public:
	vector<int> data;
	vector<int> bit;
	int N;

	//n は対象の配列 v の要素数
	BIT(int n, int ini) : data(n + 1, ini), bit(n + 1, ini), N(n + 1) {};
	BIT(int n) : data(n + 1, 0), bit(n + 1, 0), N(n + 1) {};

	//data[a] += w;
	void add(int a, int w) {
		data[a] += w;
		for (int x = a; x < N; x += x & -x) bit[x] += w;
	}


	//data[1] + … + data[a]
	int sum(int a) {
		int res = 0;
		for (int x = a; x > 0; x -= x & -x) res += bit[x];
		return res;
	}


	//data[1] + … + data[x] >= w なる最小の x (ただし、dataは全て正)
	int lower_bound(int w) {
		if (w <= 0) return 0;

		int x = 0, r = 1;
		while (r < N) r *= 2;
		for (int len = r; len > 0; len /= 2) {// 長さlenは1段下るごとに半分に
			if (x + len < N && bit[x + len] < w) {
				// 採用するとき
				w -= bit[x + len];
				x += len;
			}
		}
		return x + 1;
	}

};




