using namespace std;

template <class T> struct SegmentTreeSum
{
	int N;
	vector<T> node;

	SegmentTreeSum (int n){
		N = 2 << (int)log2(n);
		node.resize(N*2, 0);
	}

	void update(int idx, T val){
		idx += N;
		node[idx] += val;
		while (idx > 0){
			node[idx>>1] = sum(node[idx], node[idx^1]);
			idx >>= 1;
		}
	}

	T sum(T x, T y){
		return x+y;
	}

	T getSum(int l, int r){
		T ret = 0;
		for (l += N, r += N; l < r; l >>= 1, r >>= 1) {
			if (l&1) ret = sum(ret, node[l++]);
			if (r&1) ret = sum(ret, node[--r]);
		}
		return ret;
	}
};

int main(int argc, char const *argv[])
{
