	for (int i = 0; i < q; ++i) {
		int com, x, y;
		cin >> com >> x >> y;
		if (com==0) st.update(--x, y);
		else ans.push_back(st.getSum(--x, y));
	}

	for (int i = 0; i < ans.size(); ++i){
		cout << ans[i] << endl;
	}
	return 0;
}

