template <typename Monoid>
class SegmentTree {
  int sz;
  vector<Monoid> node;
  const Monoid identity;

 public:
  SegmentTree(int n) : identity(Monoid::identity()) {
    sz = 1;
    while (sz < n) sz <<= 1;
    node.resize(2 * sz, identity);
  }

  void update(int k, const Monoid &x) {
    k += sz;
    node[k] = x;
    while (k >>= 1) {
      node[k] = node[2 * k + 0] + node[2 * k + 1];
    }
  }

  void add(int k, const Monoid &x) { return update(k, node[k + sz] + x); }
  Monoid query(int l, int r) {
    Monoid L = identity, R = identity;
    for (l += sz, r += sz; l < r; l >>= 1, r >>= 1) {
      if (l & 1) L += node[l++];
      if (r & 1) R += node[--r];
    }
    return L + R;
  }
};

struct Monoid {
  int v;
  bool operator==(const Monoid& that) const { return v == that.v; }
  bool operator!=(const Monoid& that) const { return !(*(this) == that); }

  static Monoid identity() { return Monoid(0); }

  Monoid(int v = 0) : v(v) {}
  Monoid& operator+=(const Monoid& that) {
    v += that.v;
    return *this;
  }
  Monoid operator+(const Monoid& that) const { return Monoid(*this) += that; }
};

