template <class Tp>
class prefix_accumulator {
  std::vector<size_t> lsuf, pf;
  std::vector<Tp> c;

  void precalc() {
    size_t n = c.size()-1;
    std::vector<size_t> msf(n+1);
    size_t f0 = 1;
    size_t f1 = 1;
    pf[1] = 1;
    for (size_t i = 1; i <= n; ++i) {
      if (i == f1) {
        std::swap(f0 += f1, f1);
        if (f1 <= n) pf[f1] = f0;
      }
      msf[i] = f0;
      lsuf[i] = (i > msf[i])? lsuf[i-msf[i]] : i;
    }
    return;

    for (size_t i = 1; i <= n; ++i)
      fprintf(stderr, "%zu: %zu/%zu\n", i, msf[i], lsuf[i]);
  }

public:
  prefix_accumulator(size_t n): lsuf(n+1), pf(n+1), c(n+1) {
    precalc();
  }

  void update(size_t i, Tp x) {
    // a[i] += x;
    ++i;
    while (i < c.size()) {
      c[i] += x;
      i += pf[lsuf[i]];
    }
  }

  Tp accumulate(size_t i) const {
    // a[0] + ... + a[i-1]
    Tp res = 0;
    while (i > 0) {
      res += c[i];
      i -= lsuf[i];
    }
    return res;
  }
};

int main() {
  size_t n, q;
  scanf("%zu %zu", &n, &q);

  prefix_accumulator<int> pa(n);
  for (size_t i = 0; i < q; ++i) {
    int t;
    scanf("%d", &t);

    if (t == 0) {
      // add(i, x)
      size_t j;
      int x;
      scanf("%zu %d", &j, &x);
      --j;
      pa.update(j, x);
    } else if (t == 1) {
      // getSum(s, t);
      size_t s, t;
      scanf("%zu %zu", &s, &t);
      --s;
      --t;
      int sum = pa.accumulate(t+1);
      sum -= pa.accumulate(s);
      printf("%d\n", sum);
    }
  }
}

