    seg(N,add,0);
    for(int i=0;i<Q;i++){
        int c,x,y;
        cin >> c >> x >> y;
        if(c==0) seg.update(x,y);
        else cout << seg.query(x,y+1) << endl;
    }
}

#include <bits/stdc++.h>

class BIT {
private:
	int sequence_size_;
	std::vector<int> container_;
public:
	BIT(int);
	void add(int place, int num);
	int get_sum(int left, int right);
};

BIT::BIT(int n)
	:sequence_size_(n)
{
	// 各ノードは1-indexedの数列の要素に紐づけられる
	container_.resize(n + 1);
}

void BIT::add(int place, int num)
{
	while (place <= sequence_size_)
	{
		container_[place] += num;
		place += place & -place;
	}
}

// 1-indexedで(left, right]の和
int BIT::get_sum(int left, int right)
{
	int sum{};
	while (right)
	{
		sum += container_[right];
		right -= right & -right;
	}
	while (left)
	{
		sum -= container_[left];
		left -= left & -left;
	}
	return sum;
}

