#define BIT_MAX_N 100001
class BIT {
private:

  int bit[BIT_MAX_N + 1], size;

public:

  BIT(int n) : size(n) {}

  int sum(int i) {
    int s = 0;
    while(i > 0) {
      s += bit[i];
      i -= i & -i;
    }
    return s;
  }

  void add(int i, int x) {
    while(i <= size) {
      bit[i] += x;
      i += i & -i;
    }
  }

};

