template<typename T>
struct BIT {
  std::vector<T> node;
  BIT(int n) : node(n+1, 0) {}
  void add(int idx, T w) {
    for (int i = idx; i < node.size()-1; i |= (i + 1)) {
      node[i] += w;
    }
  }
  T sum(int r) {
    T ret = 0;
    for (int i = r-1; i >= 0; i = ((i & (i+1)) - 1)) {
      ret += node[i];
    }
    return ret;
  }
  T sum(int l, int r) {
    return sum(r) - sum(l);
  }
};

int main() {
  int n, q; cin >> n >> q;
  BIT<int> tree(n);

  while (q--) {
    int com, x, y;
    cin >> com >> x >> y;
    if (com == 0) { tree.add(x-1, y); }
    if (com == 1) {
      x--; y--;
      cout << tree.sum(x, y+1) << endl;
    }
  }
  return 0;
}

