int get_sum(const int &start, const int &end, const std::vector<int> &vec){
	if (start == end){
		return vec.at(start);
	}else if (start > end){
		return 0;
	}else{
		int sum = get_sum(start  >> 1, ((end - 2) >> 1) , vec);
		if (start % 2 == 0){
			sum += vec.at(start);
		}
		if (end % 2 == 1){
			sum += vec.at(end);
		}
		return sum;
	}
}
