class RangeSumQuery {
private:
	vector<int> num;
	vector<int> st;
	vector<int> rangeSum;
public:
	RangeSumQuery(vector<int> v) {
		num = v;
		double root = sqrt(num.size());

		double cnt = 0;
		for (int i = 0; i < root; i++, cnt += root) {
			st.push_back((int)floor(cnt));
		}
		st.push_back(num.size() + 1);

		for (int i = 0; i < st.size() - 1; i++) {
			int now = st[i];
			int next = st[i + 1];
			int sum = 0;
			for (int j = now; j < next; j++) {
				sum += num[j];
			}
			rangeSum.push_back(sum);
		}
	}

	void add(int x, int y) {
		num[x] += y;

		int low = 0;
		int high = st.size() - 1;
		int mid = (high + low) / 2;
		while (high - low > 1) {
			if (x < st[mid]) {
				high = mid;
			} else {
				low = mid;
			}
			mid = (high + low) / 2;
		}

		rangeSum[mid] += y;
	}

	int getSum(int s, int t) {
		int sum = 0;
		for (int i = 0; i < st.size() - 1; i++) {
			int now = st[i];
			int next = st[i + 1];

			if (next <= s) continue;

			if (t < now) break;

			if (s <= now && next <= t) {
				sum += rangeSum[i];
				continue;
			}

			int a = max(now, s);
			int b = min(next - 1, t);
			for (int j = a; j <= b; j++) {
				sum += num[j];
			}
		}

		return sum;
	}
};

signed main() {
	int n, q;
	cin >> n >> q;

	auto rsq = RangeSumQuery(vector<int>(n, 0));

	rep(i, q) {
		int com, x, y;
		cin >> com >> x >> y;

		if (com == 0) {
			x--;
			rsq.add(x, y);
		} else {
			x--; y--;
			cout << rsq.getSum(x, y) << endl;
		}
	}

    return 0;
}

