// (T, op) should be monoidal.
template<typename T>
class SegTree {
public:
  using OP = function<T(T, T)>;

private:
  int N;
  const T zero;
  OP op;
  unique_ptr<T[]> data;

  T sub_query(int a, int b, int k, int l, int r) const {
    if(b <= l || r <= a) return zero;
    if(a <= l && r <= b) return data[k];

    int mid = (l + r) / 2;
    auto vl = sub_query(a, b, k * 2, l, mid);
    auto vr = sub_query(a, b, k * 2 + 1, mid, r);

    return op(vl, vr);
  }
public:
  SegTree(int n, const T& zero, OP op)
  : zero(zero), op(op)
  {
    N = 1;
    while(N < n) N *= 2;
    data = make_unique<T[]>(N*2);
    for(int i=0;i<N*2;++i) data[i] = zero;
  }

  SegTree(int n, const T& zero, OP op, const vector<T>& init)
  : zero(zero), op(op)
  {
    N = 1;
    while(N < n) N *= 2;
    data = make_unique<T[]>(N*2);

    for(int i=0;i<n;++i) data[N+i] = init[i];
    for(int i=N-1;i>0;--i) data[i] = op(data[i*2], data[i*2+1]);
  }


  // xs[ix] = x, 0-indexed
  void update(int ix, const T& x) {
    ix += N;
    data[ix] = x;
    while(ix > 0){
      ix /= 2;
      data[ix] = op(data[ix*2], data[ix*2+1]);
    }
  }

  // return xs[ix]
  T get(int ix) const {
    return data[ix + N];
  }

  // return xs[a] `op` xs[a+1] `op` ... `op` xs[b-1]
  T query(int a, int b) const {
    return sub_query(a, b, 1, 0, N);
  }
};

int main(int argc, char* argv[]){
  init_io(argc, argv);

  using RMQ = SegTree<uint>;
  RMQ::OP op = [](uint a, uint b){ return a + b; };

  int N, Q;
  cin >> N >> Q;

  uint zero = 0;
  vector<uint> init(N, zero);
  RMQ rmq(N, zero, op, init);

  while(Q--){
    uint c, x, y;
    cin >> c >> x >> y;
    --x;
    if(c == 0){
      auto nxt = rmq.get(x) + y;
      rmq.update(x, nxt);
    }
    else cout << rmq.query(x, y) << endl;
  }

  return 0;
}

