struct range_sum_query {
    int n;
    vector<int> dat;
    range_sum_query(int n_=0) {
        n=1;
        while(n<n_) n*=2;
        dat.resize(n*2-1,0);
    }
    // a_i=x
    void add(int i,int x) {
        i += n-1;
        dat[i]+=x;
        while(i>0) {
            i=(i-1)/2;
            dat[i]=dat[i*2+1]+dat[i*2+2];
        }
    }
    // get sum of range[a,b]
    int query(int a,int b) {
        return query(a,b,0,0,n);
    }
    int query(int a,int b,int k,int l,int r) {
        if(r<=a or b<=l) return 0;
        if(a<=l and r<=b) return dat[k];
        int sl=query(a,b,k*2+1,l,(r+l)/2);
        int sr=query(a,b,k*2+2,(r+l)/2,r);
        return (sl+sr);
    }
};

