	int com, x, y;
	cin >> n >> q;
	SegmentTree<int> st(n, 0, [](int a, int b) { return a + b; });
	for (int i = 0; i < q; i++) {
		cin >> com >> x >> y;
		if (com)
			cout << st.Find(x - 1, y - 1) << endl;
		else
			st.Add(x - 1, y);
	}
	return 0;
}

