template<typename group>
struct fenwick_tree {
    using G = group;
    using T = typename group::value_type;

    size_t _size;
    std::vector<T> data;

    fenwick_tree(size_t n = 0) : _size(n), data(n+1, G::id()) { }

    int size() const { return size; }

    T sum(int r) const {
        T s = G::id();
        for(r=r-1; r>=0; r=(r&(r+1))-1) {
            s = G::op(data[r], s);
        }
        return s;
    }

    T sum(int l, int r) const {
        return G::op(G::inv(sum(l)), sum(r));
    }

    void add(int i, const T& x) {
        for(;i<=_size; i|=i+1) {
            data[i] = G::op(data[i], x);
        }
    }

    void set(int i, const T& x) {
        add(i, G::op(G::inv(*this[i]), x));
    }

    T operator[](int i) const {
        return sum(i, i+1);
    }


};

