template <typename T> using V = vector<T>;

template <typename T>
struct SegTree {
    V<T> segs;
    function<T(T, T)> merge;
    T id_ele;
    ll upper;

    SegTree(const V<T> &segs_arg, function<T(T, T)> merge, T id_ele) : merge(merge), id_ele(id_ele) {
        size_t seg_size = 1;
        while(seg_size < segs_arg.size()) seg_size <<= 1;
        seg_size <<= 1;
        upper = seg_size / 2;
        seg_size--;
        segs.resize(seg_size, id_ele);
        for(size_t i = 0; i < segs_arg.size(); i++) segs[i + seg_size / 2] = segs_arg[i];
        for(ssize_t i = seg_size / 2 - 1; 0 <= i; i--) segs[i] = merge(segs[2 * i + 1], segs[2 * i + 2]);
    }

    T get_query(ll ql, ll qr, size_t idx, ll nl, ll nr) {
        if(nr <= ql || qr <= nl) return id_ele;
        if(ql <= nl && nr <= qr) {
            return segs[idx];
        }
        auto mid = (nl + nr) / 2;
        T l = get_query(ql, qr, 2 * idx + 1, nl, mid);
        T r = get_query(ql, qr, 2 * idx + 2, mid, nr);
        return merge(l, r);
    }

    T get_query(ll ql, ll qr) {
        return get_query(ql, qr, 0, 0, upper);
    }

    void update_query(ll idx, T val) {
        idx += upper - 1;
        segs[idx] = val;
        while(idx) {
            ll pidx = (idx - 1) / 2;
            segs[pidx] = merge(segs[2 * pidx + 1], segs[2 * pidx + 2]);
            idx = pidx;
        }
    }
};

int main() {
    ll N, Q;
    cin >> N >> Q;
    V<ll> init_v(N);
    SegTree<ll> st(init_v, [](ll a, ll b) { return a + b; }, 0);
    while(Q--) {
        ll com;
        cin >> com;
        if(com == 0) {
            ll i, x;
            cin >> i >> x;
            i--;
            init_v[i] += x;
            st.update_query(i, init_v[i]);
        } else {
            ll s, t;
            cin >> s >> t;
            s--;
            cout << st.get_query(s, t) << endl;
        }
    }
    return 0;
}

