template< typename T >
struct BIT {
  vector<T> data;
  int size;
  BIT(const int n) : data(n+1), size(n) {}
  void add(int a, T val) {
    for (int x=a; x<=size; x+=x&-x) data[x] += val;
  }
  T get(int a) {
    T ret = 0;
    for (int x=a; x>0; x-=x&-x) ret += data[x];
    return ret;
  }
  T query(int l, int r) {
    return get(r) - get(l);
  }
};

template< typename T >
struct ExBIT {
  BIT<T> p, q;
  ExBIT(int n) : p(n), q(n) {}
  void add(int l, int r, T val) {
    p.add(l, -val * l); p.add(r, val * r);
    q.add(l, val); q.add(r, -val);
  }
  T get(int r) {
    return p.get(r) + q.get(r) * r;
  }
};

