struct BIT {
    int size;
    vector<int> node;

    BIT(int n) {
        size = n;
        node.resize(n+1);
    }

    void add(int i, int x) {
        i++;
        while (i<=size) {
            node[i] += x;
            i += i&(-i);
        }
    }

    int acc(int i) {
        int s = 0;
        while (i>0) {
            s += node[i];
            i -= i&(-i);
        }
        return s;
    }
};

