struct Node {
	int sum;
	int lowerLimit;
	int upperLimit;
	struct Node* left;
	struct Node* right;
};
Node* makeSegmentTree(int lower, int upper) {


	Node* node = (Node*)malloc(sizeof(Node));
	node->lowerLimit = lower;
	node->upperLimit = upper;

	if (lower == upper) {
		node->left = NULL;
		node->right = NULL;
		node->sum = arr[lower];
		return node;
	}

	int middle = (lower + upper) / 2;
	node->left = makeSegmentTree(lower, middle);
	node->right = makeSegmentTree(middle + 1, upper);
	node->sum = node->left->sum + node->right->sum;

	return node;
}
int findSum(Node* node, int lower, int upper) {
	if (lower <= node->lowerLimit && upper >= node->upperLimit) {
		//printf("[%d,%d]:%d", node->lowerLimit, node->upperLimit,node->min);
		return node->sum;
	}
	int middle = (node->lowerLimit + node->upperLimit) / 2;
	int minLeft = 0;
	int minRight = 0;

	//rintf("middle:%d\n", middle);

	if (lower <= middle) {
		minLeft = findSum(node->left, lower, upper);
	}
	if (upper >= (middle + 1)) {
		minRight = findSum(node->right, lower, upper);
	}
	return minLeft + minRight;
}
void update(Node* node, int position, int value) {
	if (node->lowerLimit == node->upperLimit) {
		node->sum += value;

		return;
	}
	int middle = (node->upperLimit + node->lowerLimit) / 2;
	if (position <= middle) {
		update(node->left, position, value);
	}
	else {
		update(node->right, position, value);
	}
	int leftMin = node->left->sum;
	int rightMin = node->right->sum;
	node->sum = leftMin + rightMin;
}
void preorder(Node* node) {
