	}
	printf("[%d,%d]:%d\n", node->lowerLimit, node->upperLimit, node->sum);
	preorder(node->left);
	preorder(node->right);
}
void inorder(Node* node) {
	if (node == NULL) {
		return;
	}
	inorder(node->left);
	printf("[%d,%d]:%d\n", node->lowerLimit, node->upperLimit, node->sum);
	inorder(node->right);
}
