int mx[5000005];
int res = 0;
void bulid(int l,int r,int rt)
{
	if(l == r)
	{
		mx[rt] = 0;
		return;
	}
	int mid = (l + r)/2;
	bulid(l,mid,rt*2);
	bulid(mid+1,r,rt*2+1);
	mx[rt] = mx[rt*2] + mx[rt*2+1];
}

void update(int l,int r,int rt,int idex,int num)
{
	if(l==r)
	{
		mx[rt] += num;
		return ;
	}
	int mid = (l + r) / 2;
	if(mid >= idex) update(l,mid,rt*2,idex,num);
	else update(mid+1,r,rt*2+1,idex,num);
	mx[rt] = mx[rt*2] + mx[rt*2+1];
}
void query(int l,int r,int rt,int ll,int rr)
{
	if(l>=ll&&r<=rr)
	{
		res += mx[rt];
		return ;
	}
	int mid=(l+r)/2;
	if(mid>=ll) query(l,mid,rt*2,ll,rr);
	if(mid<rr) query(mid+1,r,rt*2+1,ll,rr);
}
int main()
{
	int n,q;
	scanf("%d %d",&n,&q);
	bulid(1,n,1);
	while(q--)
	{
		int op,x,y;
		scanf("%d %d %d",&op,&x,&y);
		if(op == 0)
			update(1,n,1,x,y);
		else
		{
			res = 0;
			query(1,n,1,x,y);
			printf("%d\n",res);
		}
	}
	return 0;
}

