template <class T>
struct FenwickTree {
    int n;
    vector<T> x;
    FenwickTree(int n_ = 0) : n(n_), x(n_+1){
        fill(x.begin(), x.end(), 0);
    }
    T sum(int r){
        int s = 0;
        while (r > 0) {
            s += x[r];
            r -= r & -r;
        }
        return s;
    }
    T sum(int l, int r){
        return sum(r) - sum(l-1);
    }
    void add(int i, T a) {
        i++;
        while (i <= n) {
            x[i] += a;
            i += i & -i;
        }
    }
    void set(int k, T a){
        int x = sum(k, k+1);
        add(k, a-x);
    }
    vi to_a(int l = -1, int r = -1){
        if(l == -1) l = 0;
        if(r == -1) r = n;
        vi res(r-l);
        range(i,l,r) res[i-l] = sum(i,i+1);
        return res;
    }
};

