template <typename Tp>
class fenwick{
    std::vector<Tp> tree;
    std::size_t n;

public:
    fenwick(size_t _n) : n(_n) {
        tree.resize(n);
    }

    void add(size_t pos, Tp val){
        while(pos < n) {
            tree[pos] += val;
            pos |= (pos + 1);
        }
    }

    Tp get(size_t pos) {
        Tp v{};
        do{
            v += tree[pos];
            pos &= pos + 1;
        }while(pos-- > 0);

        return v;
    }

    Tp get(size_t left, size_t right){
        if(left == right) return {};
        else if(left == 0) return get(right - 1);
        else return get(right - 1) - get(left - 1);
    }
};

