class bitree{
public:
    i64 *node;
    int nd;
    void make(int n){
        nd=n;
        node=new i64[nd]{};
    }
    void update(int k,i64 x){
        if(k>=nd) return;
        node[k]+=x;
        update(k+(~k&-(~k)),x);
    }
    i64 query(int a,int b){
        i64 c1=0,c2=0;
        func(a-1,c1);
        func(b-1,c2);
        return c2-c1;
    }
    void func(int k,i64 &c){
        if(k<0) return;
        c+=node[k];
        func(k-(~k&-(~k)),c);
    }
};

