template<typename T>
struct Q003 {
   Int n, offset;
   T e;
   std::function<T(T,T)> f;
   std::vector<T> xs;
   Q003(Int n_, T e_, std::function<T(T,T)> f_)
      : n(vecSize(n_)), offset(n/2), e(e_), f(f_), xs(n, e) {}
   static Int vecSize(Int x) {
      Int t = 1;
      while( t < x ) t *= 2;
      return 2 * t;
   }
   void update(Int i, T x) {
      Int k = i + offset;
      xs[k] = x;
      update(k>>1);
   }
   void update(Int i, std::function<T(T)> g) {
      Int k = i + offset;
      xs[k] = g(xs[k]);
      update(k>>1);
   }
   void update(Int k) {
      if( k == 0 ) return;
      xs[k] = f(xs[k<<1], xs[(k<<1)+1]);
      update(k>>1);
   }
   T query(Int x, Int y) {
      return query2(1, x, y, 0, offset);
   }
   T query2(Int k, Int x, Int y, Int a, Int c) {
      if( y <= a or c <= x ) return e;
      if( offset <= k ) return xs[k];
      if( x <= a and c <= y ) return xs[k];
      Int b = (a + c) / 2;
      return f(query2(k<<1, x, y, a, b), query2((k<<1)+1, x, y, b, c));
   }
};

struct Solver {
   Solver() { fprintf(stderr, "--------Solver begin--------\n"); }
   ~Solver() { fprintf(stderr, "--------Solver end--------\n"); }
   void solve() {
      Int n, q; scan(n, q);
      Q003<Int> rmq(n, 0, [](Int x, Int y){ return x + y; });
      for(Int i = 0; i < q; ++i) {
         Int c, x, y; scan(c, x, y);
         if( c == 0 ) {
            rmq.update(x, y);
         }
         if( c == 1 ) {
            Int z = rmq.query(x, y + 1);
            printf("%ld\n", z);
         }
      }
   }
};

int main() {
   loop std::unique_ptr<Solver>(new Solver())->solve();
}

