const int INF = 0;

struct SegmentTree {
    int n;
    vector<int> heap;

    SegmentTree(int n): n(n) {
        heap.assign(4 * n, INF);
    }
    void update(int id, int l, int r, int q, int v) {
        if (q < l || q > r) {
            return;
        }
        if (l == r) {
            heap[id] += v;
        }
        else {
            int m = l + (r - l)/2;
            update(2 * id, l, m, q, v);
            update(2 * id + 1, m + 1, r, q, v);
            pushup(id);
        }
    }

    int query (int id, int l, int r, int ql, int qr) {
        if (qr < l || ql > r) {
            return INF;
        }
        if (ql <= l && r <= qr) {
            return heap[id];
        }
        else {
            int m = l + (r - l)/2;
            return query(2 * id, l, m, ql, qr) + query(2 * id + 1, m + 1, r, ql, qr);
        }
    }

    void pushup(int id) {
        heap[id] = heap[2 * id] + heap[2 * id + 1]; 
    }  
};

