template<typename T>
struct segment_tree {
    long long N; // 木の頂点数
    long long M; // 葉の数
    std::vector<T> V; // セグメント木　1-indexed
    std::function<T(T, T)> op; // 二項演算
    T id; // 単位元

    // ===============================================================

    segment_tree(std::vector<T>& a, std::function<T(T, T)> op, T id) : op(op), id(id) {
        M = 1;
        while (M < a.size()) M *= 2;
        N = 2 * M;
        V.resize(N, id);
        for (long long i = 0; i < a.size(); i++) V[M + i] = a[i];
        for (long long i = a.size(); i < M; i++) V[M + i] = id;
        for (long long i = M - 1; i > 0; i--) {
            V[i] = op(V[2 * i], V[2 * i + 1]);
        }
    }

    // ===============================================================

    void point_update(long long i, T x) {
        i += M;
        V[i] = x;
        while (i / 2 < i) {
            i /= 2;
            V[i] = op(V[2 * i], V[2 * i + 1]);
        }
    }

    T range_subfunc(long long cur_node, long long cur_left, long long cur_right, long long l, long long r) {
        if (cur_right <= l || r <= cur_left) return id;
        if (l <= cur_left && cur_right <= r) return V[cur_node];
        long long mid = (cur_left + cur_right) / 2;
        return op(range_subfunc(cur_node * 2, cur_left, mid, l, r), range_subfunc(cur_node * 2 + 1, mid, cur_right, l, r));
    }

    T range(long long l, long long r) {
        return range_subfunc(1, 0, M, l, r);
    }
};

int main() {
    long long n, q;
    std::cin >> n >> q;
    std::vector<long long> a(n, 0);
    auto f = [] (long long x, long long y) {return x + y;};
    segment_tree<long long> sg(a, f, 0);

    while (q--) {
        long long com, x, y;
        std::cin >> com >> x >> y;
        if (com == 0) {
            sg.point_update(x - 1, a[x - 1] + y);
            a[x - 1] += y;
        }
        else std::cout << sg.range(x - 1, y) << std::endl;
    }
}

