template <class T>
class SegmentTree {
public:
    vector<T> node;
    T n;
public:
    SegmentTree(vector<T> v) {
        n = 1;
        while (n < v.size()) n *= 2;
        node.resize(2*n-1, 0);
        for (int i=0; i<v.size(); ++i) node[i+n-1] = v[i];
        for (int i=n-2; i>=0; --i) node[i] = node[2*i+1] + node[2*i+2]; // sumなので
    }

    void update(T x, T val) {
        x += (n-1);
        node[x] += val;
        while (x > 0) {
            x = (x-1)/2;
            node[x] = node[x*2+1] + node[x*2+2];
        }
    }

    T query(int a, int b, int k=0, int l=0, int r=-1) {
        if (r < 0) r = n;
        if (r <= a or b <= l) return 0;
        if (a <= l and r <= b) return node[k];
        T vl = query(a, b, 2*k+1, l, (l+r)/2);
        T vr = query(a, b, 2*k+2, (l+r)/2, r);
        return vl + vr;
    }
};

