struct segtree{
	int n;
	function<T(T,T)> op;
	vector<T>arr;
	vector<T>st;
	void build(int lo,int hi,int u){
		if(lo==hi){
			st[u]=arr[lo];
		}
		else{
			int mi=(hi+lo)>>1;
			build(lo,mi,u<<1);
			build(mi+1,hi,u<<1|1);
			st[u]=op(st[u<<1],st[u<<1|1]);
		}
	}
	segtree(vector<T> v,function<T(T,T)> op):n(v.size()),st(v.size()*4),op(op){
		arr=v;
		build(0,n-1,1);
	}
	segtree(T n,function<T(T,T)> op):n(n),st(n*4),op(op){}
	T query(int lo,int hi,int u,int l,int r){
		if(l>r)return T();
		if(l==lo&&r==hi){
			return st[u];
		}
		int mi=(hi+lo)>>1;
		if(mi>r){
			return query(lo,mi,u<<1,l,r);
		}
		else if(mi<l){
			return query(mi+1,hi,u<<1|1,l,r);
		}
		else{
			return op(query(lo,mi,u<<1,l,mi),query(mi+1,hi,u<<1|1,mi+1,r));
		}
	}
	T query(int l,int r){
		return query(0,n-1,1,l,r);
	}
	T addupd(int lo,int hi,int u,int p,int x){
		if(lo==hi&&lo==p){
			return st[u]+=x;
		}
		int mi=(hi+lo)>>1;
		if(mi>=p){
			return st[u]=op(addupd(lo,mi,u<<1,p,x),st[u<<1|1]);
		}
		else if(mi<p){
			return st[u]=op(addupd(mi+1,hi,u<<1|1,p,x),st[u<<1]);
		}
	}
	T setupd(int lo,int hi,int u,int p,int x){
		if(lo==hi&&lo==p){
			return st[u]=x;
		}
		int mi=(hi+lo)>>1;
		if(mi>=p){
			return st[u]=op(addupd(lo,mi,u<<1,p,x),st[u<<1|1]);
		}
		else if(mi<p){
			return st[u]=op(addupd(mi+1,hi,u<<1|1,p,x),st[u<<1]);
		}
	}
	void add(int p,T x){
		addupd(0,n-1,1,p,x);
	}
	void set(int p,T x){
		setupd(0,n-1,1,p,x);
	}
