	vector<int> node;//セグ木本体

	//コンストラクタ
	segtree(int n)
	{
		depth=0;
		size=1;
		while(n>size)
		{
			size*=2;
			depth++;
		}
		size*=2;
		node.resize(size,0);
		//最下段に値を入れたあとに、下の段から順番に値を入れる
		//値を入れるには自分の子の2値を参照する
		/*
		for(int i=0;i<n;i++)
			node[i+(1<<depth)]=v[i];

		for(int i=depth-1;i>=0;i--)
			node[i]=calc(node[i*2],node[i*2+1]);*/
	}

	//値の更新
	//node[k]にaを加える
	void update(int k,int a)
	{
		k+=(1<<depth);//セグ木上のインデックスに読み替え
		node[k]+=a;
		while(k>1)
		{
			k/=2;
			node[k]=node[k*2]+node[k*2+1];
		}
		return;
	}

	//値の取得
	//閉区間[a,b]に値はいくつあるか
	int get(int a,int b)
	{
		a+=(1<<depth);
		b+=(1<<depth);
		if(a==b)
			return node[a];
		int nowa=node[a];
		int nowb=node[b];
		while(a/2<b/2)
		{
			//cerr<<depth<<" "<<a<<" "<<b<<endl;
			//左側はより右側を見る
			if((a&1)==0)
				nowa+=node[a+1];
			//右側はより左側を見る
			if((b&1)==1)
				nowb+=node[b-1];
			a/=2;
			b/=2;
		}
		int ret=nowa+nowb;
		return ret;
	}

	//n番目のノードを探す
	int find(int n)
	{
		int ret=1;
		for(int i=0;i<depth;i++)
		{
			//cerr<<ret-(1<<i)<<" "<<node[ret]<<endl;
			if(n<=node[ret*2])
				ret=ret*2;
			else{
				if(node[ret*2+1]==0)
					ret=ret*2;
				else{
					n-=node[ret*2];
					ret=ret*2+1;
				}
			}
		}
		return ret-(1<<depth);
	}
};

