template<class M> struct ST {
  using T = typename M::T;
  int n; V<T> t;
  ST(int n) : n(n) { t.assign(2 * n, M::e()); }
  void build() { for (int i = n - 1; i; i--) t[i] = M::op(t[2 * i], t[2 * i + 1]); }
  void modify(int i, T v) { for (t[i += n] = v; i > 1; i >>= 1) t[i >> 1] = M::op(t[i], t[i ^ 1]); }
