namespace orliv {

template <typename StateType>
struct RBST {
  struct Node;
  using self_t = RBST<StateType>;
  using state_t = typename std::remove_const<StateType>::type;
  using size_t = misc::rint_t;
  using node_ptr = Node *;
  using np_twins = misc::twins<node_ptr>;
  using rb_twins = misc::twins<self_t>;

private:
  node_ptr root;

public:
  RBST() : root(Node::null) {}
  RBST(node_ptr root) : root(root) {}

  template <typename... Types>
  static self_t create(Types... args) {
    return self_t(
        (new Node(std::move(state_t(std::forward<Types>(args)...))))->update());
  }

  static node_ptr merge(node_ptr L, node_ptr R) {
    if (!L->size) return R;
    if (!R->size) return L;

    if (misc::xor128() % (L->size + R->size) < L->size) {
      L->R = merge(L->R, R);
      return L->update();
    } else {
      R->L = merge(L, R->L);
      return R->update();
    }
  }
  static np_twins split(node_ptr x, size_t k) {
    assert(k <= x->size);
    if (!x->size) return np_twins(Node::null, Node::null);
    if (k <= x->L->size) {
      auto s = split(x->L, k);
      x->L = s.second;
      s.second = x->update();
      return s;
    } else {
      auto s = split(x->R, k - x->L->size - 1);
      x->R = s.first;
      s.first = x->update();
      return s;
    }
  }

  const Node *const operator->() const { return root; }

  self_t mergeL(self_t x) {
    root = merge(x.root, root);
    return *this;
  }
  self_t mergeR(self_t x) {
    root = merge(root, x.root);
    return *this;
  }
  static self_t merge(self_t L, self_t R) { return L.mergeR(R); }
  rb_twins split(size_t k) const {
    auto s = split(root, k);
    return rb_twins(self_t(s.first), self_t(s.second));
  }
  const state_t range(size_t l) const { return range(l, root->size); }
  const state_t range(size_t l, size_t r) {
    auto s1 = split(r);
    auto s2 = s1.first.split(l);
    auto st = s2.second->state;
    root = merge(merge(s2.first, s2.second), s1.second).root;
    return st;
  }
  template <typename Callable>
  state_t update(size_t k, Callable callable) {
    auto s1 = split(k);
    auto s2 = s1.second.split(1);
    s2.first.root->state = callable(s2.first.root->state);
    s2.first.root = s2.first.root->update();
    root = merge(s1.first, merge(s2.first, s2.second)).root;
    return s2.first->state;
  }

  size_t size() const { return root->size; }
  template <typename... Types>
  self_t emplace(size_t k, Types... args) {
    auto s = split(k);
    self_t rb = self_t::create(std::forward<Types>(args)...);
    root = rb.mergeL(s.first).mergeR(s.second).root;
    return *this;
  }
  template <typename... Types>
  self_t emplace_back(Types... args) {
    return emplace(root->size, std::forward<Types>(args)...);
  }
  template <typename... Types>
  self_t emplace_front(Types... args) {
    return emplace(0, std::forward<Types>(args)...);
  }
  self_t erase(size_t k) {
    auto s1 = split(k);
    auto s2 = s1.second.split(1);
    if (s2.first.root != Node::null) delete s2.first.root;
    root = merge(s1.first, s2.second).root;
    return *this;
  }
  self_t pop_back() {
    if (root->size == 0) return *this;
    return erase(root->size - 1);
  }
  self_t pop_front() {
    if (root->size == 0) return *this;
    return erase(0);
  }
  struct Node {
    static node_ptr null;
    size_t size = 1;
    node_ptr L = null, R = null;
    state_t state;

    Node() : size(0) {}
    Node(state_t &&s) : state(s) {}
    node_ptr update() {
      assert(this != null);
      size = L->size + R->size + 1;
      state.update(L->state, R->state);
      return this;
    }
    template <typename Callable>
    void traverse(Callable callable, int order = 0) const {
      if (this == null) return;
      if (order < 0) callable(state);
      L->traverse(callable, order);
      if (order == 0) callable(state);
      R->traverse(callable, order);
      if (order > 0) callable(state);
    }
  };
};
}

