			seg[i/2]=upquary(i);
		}
	}
	//change value 
	void update(int index, T value){
		seg[size+index]+=value;
		if (found==false){return ;}
		int ter=index+size;
		while(ter!=1){
			ter/=2;
			seg[ter]=upquary(ter*2);
