#define SEG_LEN (1 << 18)

int seg[SEG_LEN*2];//完全2分木が作れるなら要素数は2^nで,2分木の一番下・一番左の要素は2^nの番号だから2^n+2^n=2*2^nとなる.

void add(int ind,int v){
	ind += SEG_LEN;
	seg[ind] += v;
	while(true){
		ind /= 2;
		if(ind == 0)break;
		seg[ind] = seg[ind * 2] + seg[ind * 2 + 1];
	}
}

int sum(int l,int r){
	l += SEG_LEN;
	r += SEG_LEN;
	int ans = 0;
	while(l < r){
		if(l % 2 == 1){
			ans += seg[l];
			l++;
		}
		l /= 2;
		if(r % 2 == 1){
			ans += seg[r-1];
			r--;
		}
		r /= 2;
	}
	return ans;
}

