#include <iostream>
#include <vector>
using namespace std;
using ll = long long;

enum command { ADD = 0, GETSUM = 1 };



void update(vector<int> &st, int i, int a) {
  const int n = st.size() - 1;
  for (; i <= n; i += (i & -i))
    st[i] += a;
}

// get sum of [l,r);
ll getSum(vector<int> &st, int l, int r) {
  r--;
  l--;
  ll sum = 0;
  for (; r > 0; r -= (r & -r))
    sum += st[r];
  for (; l > 0; l -= (l & -l))
    sum -= st[l];
  return sum;
}

int main(int argc, char const *argv[]) {
  int n, q, comm, x, y;
