const int MAX = 2147483647;
int min(int a, int b) {
	return a < b ? a : b;
}
int getSegTreeSize(int len) {
	if (len == 0)
		return 0;
	int ret, cnt = 0, memo = 1;
	while (memo < len) {
		memo *= 2;
		cnt++;
	}
	ret = 1 << (cnt + 1);
	return ret;
}
class RMQ {
  private:
	int size, length;
	std::vector<int> memo;
	RMQ() {}
	void update(int index) {
		index /= 2;
		if (index == 0)
			return;
		memo[index] = min(memo[index * 2], memo[index * 2 + 1]);
		update(index);
	}
	int get(int left, int right, int node, int node_left, int node_right) {
		if (node_right < left || right < node_left)
			return MAX;
		if (left <= node_left && node_right <= right)
			return memo[node];
		return min(get(left, right, node * 2, node_left, (node_left + node_right) / 2), get(left, right, node * 2 + 1, (node_left + node_right) / 2 + 1, node_right));
	}

  public:
	RMQ(int size) {
		this->size = getSegTreeSize(size) / 2;
		this->length = getSegTreeSize(size);
		memo.resize(this->length);
		fill(memo.begin(), memo.end(), MAX);
	}
	void update(int index, int element) {
		index += length / 2 - 1;
		memo[index] = element;
		update(index);
	}
	int find(int left, int right) {
		return get(left, right, 1, 1, size);
	}
};
class RSQ {
  private:
	int size, length;
	std::vector<int> memo;
	RSQ() {}
	void update(int index) {
		index /= 2;
		if (index == 0)
			return;
		memo[index] = memo[index * 2] + memo[index * 2 + 1];
		update(index);
	}
	int get(int left, int right, int node, int node_left, int node_right) {
		if (node_right < left || right < node_left)
			return 0;
		if (left <= node_left && node_right <= right)
			return memo[node];
		return get(left, right, node * 2, node_left, (node_left + node_right) / 2) + get(left, right, node * 2 + 1, (node_left + node_right) / 2 + 1, node_right);
	}

  public:
	RSQ(int size) {
		this->size = getSegTreeSize(size) / 2;
		this->length = getSegTreeSize(size);
		memo.resize(this->length);
		fill(memo.begin(), memo.end(), 0);
	}
	void update(int index, int element) {
		index += length / 2 - 1;
		memo[index] += element;
		update(index);
	}
	int find(int left, int right) {
		return get(left, right, 1, 1, size);
	}
};
