struct segtree {
    int n;
    vi seg;

    void init(int n_)
    {
        n = 1;
        while (n < n_) n *= 2;
        seg.resize(2 * n - 1);
        rep(i, 2 * n - 1) seg[i] = 0;
    }

    int update(int k, int a)
    {
        k += n - 1;

        seg[k] += a;

        while (k > 0) {
            k = (k - 1) / 2;
            seg[k] += a;
        }
    }

    int query(int a, int b, int k, int l, int r)
    {
        if (r <= a || b <= l) return 0;

        if (a <= l && r <= b) return seg[k];

        int vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
        int vr = query(a, b, k * 2 + 2, (l + r) / 2, r);

        return vl + vr;
    }

    int query(int a, int b)
    {
        return query(a, b, 0, 0, n);
    }
};

signed main()
{
    int N, Q; cin >> N >> Q;

    segtree s;

    s.init(N);

    rep(i, Q) {
        int c, x, y; cin >> c >> x >> y;

        if (c == 0) {
            -- x;
            s.update(x, y);
        } else {
            -- x; -- y;
            cout << s.query(x, y + 1) << endl;
        }
    }
}

