using namespace std;

template<typename T> class SegmentTree {
private:
  const T DEFAULT;
  int n;
  vector<T> d;

  T query(int a, int b, int k, int l, int r) {
    if (r <= a || b <= l) return DEFAULT;
    if (a <= l && r <= b) return d[k];
    T vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
    T vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
    return function(vl, vr);
  }

protected:
  virtual T function(T l, T r) = 0;

public:
  SegmentTree(int m) : DEFAULT(numeric_limits<T>::max()) {
    n = 1 << (32 - __builtin_clz(m - 1));
    d.resize(2 * n - 1, DEFAULT);
  }

  SegmentTree(int m, T def) : DEFAULT(def) {
    n = 1 << (32 - __builtin_clz(m - 1));
    d.resize(2 * n - 1, DEFAULT);
  }

  void update(int k, T a) {
    k += n - 1;
    d[k] = a;
    while (k > 0) {
      k = (k - 1) / 2;
      d[k] = function(d[k * 2 + 1], d[k * 2 + 2]);
    }
  }

  // [a,b)
  T query(int a, int b) {
    return query(a, b, 0, 0, n);
  }
};

template<typename T> class RSQ : public SegmentTree<T> {
protected:
  T function(T l, T r) {
    return l + r;
  }

public:
  RSQ(int n) : SegmentTree<T>(n, 0) {}
};

int main() {
  int n, q;
  cin >> n >> q;
  RSQ<int> rsq(n);
  for (int i = 0; i < q; ++i) {
    int com, x, y;
    cin >> com >> x >> y;
    if (com == 0) rsq.update(x, y);
    else cout << rsq.query(x, y + 1) << endl;
  }
}

