const int N = 1e5 + 5;
int n, q, f[N];

void add(int p, int val) {
    while (p <= n) {
        f[p] += val;
        p += p & -p;
    }
    return;
}

int qry(int p) {
    int rt = 0;
    while (p) {
        rt += f[p];
        p -= p & -p;
    }
    return rt;
}

