#define int long long
const int sqrtN = 512;

struct SqrtDecomposition{
    int N, K;
    vector<int> data;
    vector<int> bucketSum;
    SqrtDecomposition(int n) : N(n){

        //切り上げ(K := バケット数, sqrtN := バケットサイズ)
        K = (N + sqrtN - 1) / sqrtN;
        data.assign(K * sqrtN, 0);
        bucketSum.assign(K, 0);
    }

    void add(int x, int y){
        int k = x / sqrtN;
        data[x] += y;
        int sum = 0;
        for (int i = k * sqrtN; i < (k + 1) * sqrtN; ++i) {
            sum += data[i];
        }
        bucketSum[k] = sum;
    }

    //[x, y)
    int getSum(int x, int y){

        int sum = 0;

        for(int k = 0; k < K; k++){

            int l = k * sqrtN;
            int r = (k + 1) * sqrtN;
            if(r <= x || y <= l) continue;

            if(x <= l && r <= y) sum += bucketSum[k];
            else{
                for(int i = max(x, l); i < min(y, r); i++){
                    sum += data[i];
                }
            }
        }

        return sum;
    }

    void debug(){
        for(int i = 0; i < N; i++){
            cout << data[i] << " ";
        }
        cout << endl;
        for(int i = 0; i < N; i++){
            if(i % sqrtN == 0) cout << bucketSum[i] << " ";
            else cout << "  "; 
        }
        cout << endl;
    }
};


