    SqrtDecomposition decomp(N);
    while(Q--){
        int c, x, y; cin >> c >> x >> y;
        if(c == 0) decomp.add(x, y);
        else cout << decomp.getSum(x, y + 1) << endl;

        //decomp.debug();
    }

    return 0;
}

