  int n, q;
  cin >> n >> q;

  RangeSumQuery<int> bit(n);

  REP(i, q) {
    int com, x, y;
    cin >> com >> x >> y;
    if (com == 0) {
      bit.add(x-1, y);
    } else if (com == 1) {
      cout << bit.sum(x-1, y) << endl;
    }
  }
  return 0;
}

