template<typename T>
struct Q003 {
   Int n, offset;
   T e;
   std::function<T(T,T)> f;
   std::vector<T> xs;
   Q003(Int n_, T e_, std::function<T(T,T)> f_)
      : n(vecSize(n_)), offset(n/2), e(e_), f(f_), xs(n, e) {}
   static Int vecSize(Int x) {
      Int t = 1;
      while( t < x ) t *= 2;
      return 2 * t;
   }
   void update(Int i, T x) {
      Int k = i + offset;
      xs[k] = x;
      update(k>>1);
   }
   void update(Int i, std::function<T(T)> g) {
      Int k = i + offset;
      xs[k] = g(xs[k]);
      update(k>>1);
   }
   void update(Int k) {
      if( k == 0 ) return;
      xs[k] = f(xs[k<<1], xs[(k<<1)+1]);
      update(k>>1);
   }
   T query(Int x, Int y) {
      return query2(1, x, y, 0, offset);
   }
   T query2(Int k, Int x, Int y, Int a, Int c) {
      if( y <= a or c <= x ) return e;
      if( offset <= k ) return xs[k];
      if( x <= a and c <= y ) return xs[k];
      Int b = (a + c) / 2;
      return f(query2(k<<1, x, y, a, b), query2((k<<1)+1, x, y, b, c));
   }
};

