int tree[1<<18], n, q;

void update(int x, int y, int v, int id=0, int l=0, int r=n)
{
    if (x>=r or y<=l) return;
    if (x<=l and r<=y) {
        tree[id]+=v;
        return;
    }
    int m=l+r>>1;
    int L=2*id+1, R=L+1;
    update(x, y, v, L, l, m);
    update(x, y, v, R, m, r);
    tree[id]=tree[L]+tree[R];
}

int sum(int x, int y, int id=0, int l=0, int r=n)
{
    if (x>=r or y<=l) return 0;
    if (x<=l and r<=y) return tree[id];
    int m=l+r>>1;
    int L=2*id+1, R=L+1;
    return sum(x, y, L, l, m)+sum(x, y, R, m, r);
}

