	while ((n - 1) >> k) k++;
	n_add = (1 << k) - 1;
	for (int i = 0; i < n_add * 2; ++i) {
		dat[i] = 0;
	}
}

void add(int x, int y) {
	x += n_add;
	while (x > 0) {
		dat[x] += y;
		x = x / 2;
	}
