template <class T>
class BinaryIndexedTree {
    int N;
    vector <T> bit;

public:
    BinaryIndexedTree(int n) : N(n), bit(n + 1, 0) {}

    BinaryIndexedTree(vector <T> ary) : N(ary.size()), bit(ary) {
        for (int x = 0; x < N - 1; x++) bit[x + (x & -x)] += bit[x];
