using std::vector;

template <class T>
struct FenwickTree
{
    vector<T> dat;

    explicit FenwickTree(int size): dat(++size, 0) {}

    void add(int i, const T &v)
    { while (i < dat.size()) dat[i]+=v, i += i&-i;
    }

    T sum(int i) {
        T ret = 0;
        while (i > 0) ret+=dat[i], i -= i&-i;
        return ret;
    }
    inline T sum(int s, int t) { return sum(t) - sum(s-1); }
};

int main()
{
    int n, q;
    int com, x, y;
    scanf("%d %d", &n, &q);

    FenwickTree<int> ft(n);

    while(q--) {
        scanf("%d %d %d", &com, &x, &y);
        if (com == 0) ft.add(x, y);
        else printf("%d\n", ft.sum(x, y));
    }

}

#include "bits/stdc++.h"

struct RangeMinimumQuery {
    using type = int;
    static type id() { return INT_MAX; }
    static type op(const type &l, const type &r) { return std::min(l, r); }
};

struct RangeMaximumQuery {
    using type = int;
    static type id() { return -INT_MAX; }
    static type op(const type &l, const type &r) { return std::max(l, r); }
};

struct RangeSumQuery {
    using type = int;
    static type id() { return 0; }
    static type op(const type &l, const type &r) { return l + r; }
};

template <typename M>
class SegmentTree
{
    using T = typename M::type;
    int n;
    std::vector<T> node;

public:
    // v を基に初期化
    SegmentTree(const std::vector<T> &v)
    {
        // n は v.size() 以上の最小の2冪
        n = 1;
        while (n < int(v.size()))
            n *= 2;
        node.resize(2 * n, M::id());

        // i の子 -> 2*i+1, 2*i+2 , 親 -> (i-1)/2
        for (int i = 0; i < int(v.size()); i++)
            node[i + n] = v[i];
        for (int i = n - 1; i >= 0; i--)
            node[i] = M::op(node[2 * i], node[2 * i + 1]);
    }
    // Monoid::id 初期化
    SegmentTree(int _n)
    {
        n = 1;
        while (n < _n)
            n *= 2;
        node.resize(2 * n, M::id());
    }
    // x 番目を val に更新
    void update(int x, T val)
    {
        x += n;
        node[x] = val;
        while (x >>= 1)
        {
            node[x] = M::op(node[2 * x], node[2 * x + 1]);
        }
    }
    // v[x] を M::op(v[x], val) に更新
    void operation(int x, T val)
    {
        x += n;
        node[x] = M::op(node[x], val);
        while (x >>= 1)
        {
            node[x] = M::op(node[2 * x], node[2 * x + 1]);
        }
    }
    // [a, b) の op
    T query(int l, int r)
    {
        l += n;
        r += n;
        T retl = M::id(), retr = M::id();
        while (l < r)
        {
            if (l & 1)
                retl = M::op(retl, node[l++]);
            if (r & 1)
                retr = M::op(node[--r], retr);
            l >>= 1;
            r >>= 1;
        }
        return M::op(retl, retr);
    }
};

using namespace std;

void solve_dsl_2_a()
{ // range min
    int n, q;
    cin >> n >> q;
    SegmentTree<RangeMinimumQuery> st(n);
    while (q--)
    {
        int type;
        cin >> type;
        if (type == 0)
        {
            int index, x;
            cin >> index >> x;
            st.update(index, x);
        }
        else
        {
            int s, t;
            cin >> s >> t;
            t++;
            cout << st.query(s, t) << endl;
            ;
        }
    }
}

void solve_dsl_2_b()
{ // range sum
    int n, q;
    cin >> n >> q;
    SegmentTree<RangeSumQuery> st(n);
    while (q--)
    {
        int type;
        cin >> type;
        if (type == 0)
        {
            int index, x;
            cin >> index >> x;
            index--;
            st.operation(index, x);
        }
        else
        {
            int s, t;
            cin >> s >> t;
            s--;
            cout << st.query(s, t) << endl;
            ;
        }
    }
}

