using namespace std;
typedef long long ll;

struct lst
{
    private:
        int n;
        vector<ll>node;

    public:
        lst(int sz)
        {
            n=1; while (n<sz) n*=2;
            node.resize(2*n-1, 0);
        }
        void update(int k, int v)
        {
            int p=n+k-1;
            while(p>0)
            {
                node[p]+=v;
                p=(p-1)/2;
            }
            node[p]+=v;
        }

        ll get(int qa, int qb, int k=0, int l=0, int r=-1)
        {
            if(r<0) r=n-1;
            if(qb<l || qa>r) return 0;
            if(qa<=l && r<=qb) return node[k];
            else
            {
                int m=(l+r)/2;
                ll ls=get(qa, qb, 2*k+1, l, m);
                ll lr=get(qa, qb, 2*k+2, m+1, r);
                return ls+lr;
            }
        }
};

int main()
{
    int n, q;
    scanf("%d %d", &n, &q);
    lst tree=lst(n);
    for(int i=0; i<q; i++)
    {
        int com, x, y;
        scanf("%d %d %d", &com, &x, &y);
        if(com)
            printf("%lld\n", tree.get(x-1, y-1));
        else
            tree.update(x-1, y);
    }
    return 0;
}

