using namespace std;
using ll = long long;
struct SegmentTree
{
    vector<int> _data;
    int N;
    bool minimum;
    SegmentTree(bool minimum):minimum(minimum){}
    void init_0(int _N){
        N=1;
        while (N < _N)N*=2;
        _data = vector<int>(N*2-1, 0);
    }

    void init_MAX(int _N){
        N=1;
        while (N < _N)N*=2;
        if(minimum)
            _data = vector<int>(N*2-1, INT_MAX);
        else
            _data = vector<int>(N*2-1, INT_MIN);
    }
    void update(int i, int value){
        i += N-1;
        _data[i] = value;
        while (i)
        {
            i = (i-1)/2;
            if (minimum) _data[i] = min(_data[i*2+1], _data[i*2+2]);
            else _data[i] = max(_data[i*2+1], _data[i*2+2]);
        }
    }
    void add(int i, int value){
        i += N-1;
        _data[i] += value;
        while (i)
        {
            i = (i-1)/2;
            _data[i] = _data[i*2+1] + _data[i*2+2];
        }
    }
    void initVector(vector<int> v){
        for (int i = 0; i < v.size(); i++)
            update(i, v[i]);
    }
    int getMin(int left, int right, int l = 0, int r = -1, int k = 0){
        if(r == -1)r=N;
        if(r<=left||right<=l)return INT_MAX;
        if(left<=l&&right>=r)return _data[k];
        int v1=getMin(left,right,l,(l+r)/2,k*2+1);
        int v2=getMin(left,right,(l+r)/2,r,k*2+2);
        return min(v1,v2);
    }
    int getMax(int left, int right, int l = 0, int r = -1, int k = 0){
        if(r == -1)r=N;
        if(r<=left||right<=l)return INT_MIN;
        if(left<=l&&right>=r)return _data[k];
        int v1=getMin(left,right,l,(l+r)/2,k*2+1);
        int v2=getMin(left,right,(l+r)/2,r,k*2+2);
        return max(v1,v2);
    }
    int getSum(int left, int right, int l = 0, int r = -1, int k = 0){
        if(r == -1)r=N;
        if(r<=left||right<=l)return 0;
        if(left<=l&&right>=r)return _data[k];
        int v1=getSum(left,right,l,(l+r)/2,k*2+1);
        int v2=getSum(left,right,(l+r)/2,r,k*2+2);
        return v1 + v2;
    }
};




