template <class T>
class SegTree {
	int n;
	vector<T> data;
	T def;
	function<T(T,T)> operation;
	function<T(T,T)> update;

	// ノードk=[l,r)に着目
	T _query(int a, int b, int k, int l, int r) {
		if (r <= a or b <= l) return def; // 交差しない
		if (a <= l and r <= b) return data[k]; // a,l,r,bの順で完全に含まれる
		else {
			T c1 = _query(a, b, 2*k+1, l, (l+r)/2); // 左の子
			T c2 = _query(a, b, 2*k+2, (l+r)/2, r); // 左の子
			return operation(c1, c2);
		}
	}

	public:
	// _n:必要サイズ，_def:初期値かつ単位元，_operation:クエリ関数，_update:更新関数
	SegTree(size_t _n, T _def, function<T(T, T)> _operation, function<T(T,T)> _update)
		: def(_def), operation(_operation), update(_update) {
			n = 1;
			while (n < _n) {
				n *= 2;
			}
			data = vector<T>(2*n-1, def);
		}
	SegTree(vector<T>& v, T _def, function<T(T, T)> _operation, function<T(T,T)> _update)
		: def(_def), operation(_operation), update(_update) {
			n = 1;
			int _n = v.size();
			while (n < _n) {
				n *= 2;
			}
			data = vector<T>(2*n-1, def);
			for (int i = 0; i < v.size(); i++) {
				data[i+n-1] = v[i];
			}
			for (int i = n-2; i >= 0; i--) {
				data[i] = operation(data[i*2+1], data[i*2+2]);
			}
		}

	// 場所i(0-indexed)の値をxで更新
	void change(int i, T x) {
		i += n-1;
		data[i] = update(data[i], x);
		while (i > 0) {
			i = (i-1)/2;
			data[i] = operation(data[i*2+1], data[i*2+2]);
		}
	}

	// [a,b)の区間クエリを実行
	T query(int a, int b) {
		return _query(a,b,0,0,n);
	}

	// 添字でアクセス
	T operator[](int i) {
		return data[i+n-1];
	}

	friend ostream& operator<<(ostream& os ,const SegTree<T>& sg) {
		return os << sg.data;
	}
};

int main(int argc, char *argv[])
{
	LL n,q;
	cin >> n >> q;
	VL a(n,0);
	SegTree<LL> sg(a, 0, [](int a, int b){return a+b;}, [](int a, int b){return a+b;});
	for (int i = 0; i < q; i++) {
		int b,c,d;
		cin >> b >> c >> d;
		if (b==0) {
			sg.change(c-1, d);
		} else {
			cout << sg.query(c-1, d) << '\n';
		}
	}
	return 0;
}

