#define Seg_Max_N (1<<18) 

using Value = long long int ;
const Value ini = 0;
struct segtree {
	int N;
	vector<Value>dat;

	segtree() {}
	segtree(int n) :dat(2 * Seg_Max_N){
		N = 1;
		while (N < n) N *= 2;
		for (int i = 0; i < 2 * N - 1; i++) {
			dat[i] = ini;
		}
	}
	Value unite(const Value al, const Value ar) {
		return al + ar;
	}
	// update k th element
	void update(int k, Value a) {
		 k += N - 1;
		dat[k] += a;

		while (k > 0) {
			k = (k - 1) / 2;
			const Value al(dat[k * 2 + 1]);
			const Value ar(dat[k * 2 + 2]);
			dat[k] = unite(al, ar);
		}
	}
	// min [a, b)
	Value  query(int a, int b) { return query(a, b, 0, 0, N); }
	Value  query(int a, int b, int k, int l, int r) {
		if (r <= a or b <= l) return ini;
		if (a <= l and r <= b) return dat[k];
		const int m = (l + r) / 2;
		const Value al(query(a, b, k * 2 + 1, l, m));
		const Value ar(query(a, b, k * 2 + 2, m, r));
		return  unite(al, ar);
	}
};
int main() {
	int N, Q; cin >> N >> Q;
	segtree seg(N);
	for (int i = 0; i < Q; ++i) {
		int a, b, c; cin >> a >> b >> c;
		if (!a) {
			b--;
			seg.update(b, c);
		}
		else {
			long long int ans = seg.query(b-1, c);
			cout << ans << endl;
		}
	}
	return 0;
}

