int sz;

vector<int> node;


void update(int index,int val)
{
	index = index + sz - 1;
	node[index] += val;
	while(index > 0)
	{
		index = (index - 1) / 2;
		node[index] = node[index * 2 + 1] + node[index * 2 + 2];
	}
}

int get_sum(int a,int b,int k,int l,int r)
{
	if(r <= a || b <= l) return 0;

	if(a <= l && r <= b) return node[k];

	int vl = get_sum(a,b,2 * k + 1,l,(l + r) / 2);
	int vr = get_sum(a,b,2 * k + 2,(l + r) / 2,r);
	return vl + vr;
}
int main()
{
