// Range Sum Query
// query 1: add
// query 2: range sum
void DSL_2_B() {
    struct SegFunc {
        static int update(int a, int b) { return a + b; };
        static int combine(int a, int b) { return a + b; };
    };

    int N, Q; cin >> N >> Q;
