  for (int i=0; i<q; i++) {
    cin >> com >> x >> y;
    if (com == 0) {
      rsq -> add(x-1, y);
    } else {
      cout << rsq -> getSum(x-1, y-1, 0, 0, rsq->size - 1) << '\n';
    }
  }
  return 0;
}

