i64 pow2_ceil(i64 x) {
    ASSERT(x > 0);
    i64 k = x == 1 ? 64 : __builtin_clzll(x);
    return 1LL << (64-k);
}

struct SegTree {
    i64 n_;
    vector<i64> data_;

    explicit SegTree(i64 n) : n_(pow2_ceil(n)), data_(2*n_,0) {}

    void add(i64 i, i64 x) {
        i64 v = i + n_;
        data_[v] += x;
        while(v > 1) {
            v /= 2;
            data_[v] = data_[2*v] + data_[2*v+1];
        }
    }

    i64 query(i64 a, i64 b) const {
        return query_impl(a, b, 1, 0, n_);
    }

private:
    i64 query_impl(i64 a, i64 b, i64 v, i64 l, i64 r) const {
        if(b <= l || r <= a) return 0;

        if(a <= l && r <= b) return data_[v];

        i64 xl = query_impl(a, b, 2*v, l, (l+r)/2);
        i64 xr = query_impl(a, b, 2*v+1, (l+r)/2, r);
        return xl + xr;
    }
};

void solve() {
    i64 N = RD();
    i64 Q = RD();

    SegTree seg(N);
    REP(_, Q) {
        i64 cmd = RD();
        if(cmd == 0) {
            i64 i = RD1();
            i64 x = RD();
            seg.add(i, x);
        }
        else if(cmd == 1) {
            i64 x = RD1();
            i64 y = RD1();
            i64 ans = seg.query(x, y+1);
            PRINTLN(ans);
        }
        else {
            ASSERT(false);
        }
    }

    //PRINTLN(ans);
}

signed main() {


    solve();

    return 0;
}

