const int MAX_N=10000000;

int n;
int dat[MAX_N*2-1];

void init(){
    int i=n;
    n=2;

	while (n<i)n*=2;

	fill(dat,dat+n*2,0);
}

void update(int i,int x){
	i+=n-1;
	while(i>0){
		dat[i]+=x;
		i=(i-1)/2;
	}
}

long long int query(int a,int b,int k,int l,int r){
	if(r<a||b<l)return 0;
	if(a<=l&&r<=b) return dat[k];
	else{
		int vl=query(a,b,k*2+1,l,(l+r)/2);
		int vr=query(a,b,k*2+2,(l+r)/2+1,r);
	    return vl+vr;
	}
}

