				if(i*sz + j < n)
					w[i] = f(w[i], v[i*sz + j]);
	}
	void point_set(int a, int x){
		v[a] = x;
		int b = a / sz;
		w[b] = e;
		for(int i=0; i<sz&&b*sz+i<n; ++i)
