void add(int t, int l, int r, int p, int x) {
	sum[t] += x;
	if (l == r)
		return;
	int mid = (l + r) / 2;
	if (p <= mid)
		add(t << 1, l, mid, p, x);
	else
		add(t << 1 | 1, mid + 1, r, p, x);
}

int getsum(int t, int l, int r, int x, int y) {
	if (x <= l && r <= y)
		return sum[t];
	if (x > r || y < l)
		return 0;
	int mid = (l + r) / 2;
	return
		getsum(t << 1, l, mid, x, y) + 
		getsum(t << 1 | 1, mid + 1, r, x, y);
}

