template<typename T>
struct SegmentTree {

	SegmentTree(int _n) : n(_n) { 
		t.resize(n * 4); 
	}

	SegmentTree(vector<T>& a) {
		n = (int)a.size();
		t.resize(4 * n);
		build(a, 1, 1, n);
	}

	int n;
	vector<T> t;

	void build(vector<T>& a, int v, int tl, int tr) {
	    if (tl == tr) {
	        t[v] = a[tl - 1];
	    } else {
	        int tm = (tl + tr) / 2;
	        build(a, v*2, tl, tm);
	        build(a, v*2+1, tm+1, tr);
	        t[v] = t[v*2] + t[v*2+1];
	    }
	}

	T query(int l, int r) {
		assert(l >= 1 && r <= n && l <= r);
		return _query(1, 1, n, l, r);
	}

	T _query(int v, int tl, int tr, int l, int r) {
	    if (l > r) 
	        return 0;
	    if (l == tl && r == tr) {
	        return t[v];
	    }
	    int tm = (tl + tr) / 2;
	    return _query(v*2, tl, tm, l, min(r, tm))
	           + _query(v*2+1, tm+1, tr, max(l, tm+1), r);
	}

	void update(int pos, T new_val) {
		assert(pos >= 1 && pos <= n);
		_update(1, 1, n, pos, new_val);
	}

	void _update(int v, int tl, int tr, int pos, T new_val) {
	    if (tl == tr) {
	        t[v] += new_val;
	    } else {
	        int tm = (tl + tr) / 2;
	        if (pos <= tm)
	            _update(v*2, tl, tm, pos, new_val);
	        else
	            _update(v*2+1, tm+1, tr, pos, new_val);
	        t[v] = t[v*2] + t[v*2+1];
	    }
	}
};

