template<typename T, int MAX_N>
struct BIT {
    int N;
    T arr[MAX_N];

    BIT (int n) : N(n) {
        for (int i = 0; i <= N; ++i) {
            arr[i] = (T)0;
        }
    }

    void update (int i, T a) {
        for (int x = i; x <= N; x += x & -x) {
            arr[x] += a;
        }
    }

    T query(int i) {
        T val = 0;
        for (int x = i; x > 0; x -= x & -x) {
            val += arr[i];
        }
        return val;
    }
};

