template<class T>
struct SegTree {
    std::vector<T> tree;
    T INF;
    size_t N;
    std::function<T(T,T)> eval;

    SegTree(size_t size, T inf, std::function<T(T,T)> e) {
        INF = inf;
        eval = e;

        N = 1;
        while( N < size ) {
            N <<= 1;
        }
        tree.resize(2*N-1, INF);
    }

    void update(int i, int x) {
        i += N - 1;
        tree[i] = x;
        while(i > 0) {
            i = (i-1)/2;
            tree[i] = eval(tree[i*2+1],tree[i*2+2]);
        }
    }

    T query(size_t a, size_t b) {
        auto x = query(a, b, 0, 0, N);
        return x;
    }
    T query(size_t a, size_t b, size_t k, size_t l, size_t r) {
        if( r <= a || b <= l ) {
            return INF;
        }
        if( a <= l && r <= b ) {
            return tree[k];
        } else {
            T vl = query(a, b, k*2+1, l, (l+r)/2);
            T vr = query(a, b, k*2+2, (l+r)/2, r);
            return eval(vl, vr);
        }
    }
};

