    void change(ll i, T x) {
        i += n - 1;
        data[i] = update(data[i], x);
        while (i > 0) {
            i = (i - 1) / 2;
            data[i] = operation(data[i * 2 + 1], data[i * 2 + 2]);
        }
    }

    T _query(ll a, ll b, ll k, ll l, ll r) {
        if (r <= a || b <= l)
            return def;
        if (a <= l && r <= b) {
            return data[k];
        } else {
            T vl = _query(a, b, 2 * k + 1, l, (l + r) / 2);
            T vr = _query(a, b, 2 * k + 2, (l + r) / 2, r);
            return operation(vr, vl);
        }
    }

    T query(ll a, ll b) {
        return _query(a, b, 0, 0, n);
    }

    T operator[](ll i) {
        return data[i + n - 1];
    }
};


int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(15);
    ll n;
    ll q;
    cin>>n>>q;
    SegmentTree<ll> sg(n,0,[](ll a,ll b){return a+b;},[](ll a,ll b){return a+b;});
    rep(i,q){
        ll c,x,y;
        cin>>c>>x>>y;
        if(c==0){
            sg.change(x-1,y);
        }
        else{
            cout<<sg.query(x-1,y)<<endl;
        }
    }
    return 0;
}

