class RSQ {
	const int N = 0, sqrtN = 320;
	int B = 0;
	vector<LL> A, Sum;

	void UpdateSum(int i) {
		int l = i * sqrtN, r = (i + 1) * sqrtN;
		Sum[i] = accumulate(A.begin() + l, A.begin() + r, 0LL);
	}

public:
	RSQ(int _N) :N(_N), B((_N + sqrtN - 1) / sqrtN) {
		A.resize(sqrtN * B);
		Sum.resize(B);
	}
	void add(int i, LL x) {
		A[i] += x;
		UpdateSum(i / sqrtN);
	}
	//[s, t)
	LL get(int s, int t) {
		LL ret = 0;
		for (int i = 0; i < B; i++) {
			//Sum[i]の範囲 [l, r)
			int l = i * sqrtN, r = (i + 1) * sqrtN;

			if (r <= s || t <= l) {
				continue;
			} else if (s <= l && r <= t) {
				ret += Sum[i];
			} else {
				for (int j = max(s, l); j < min(t, r); j++) {
					ret += A[j];
				}
			}
		}
		return ret;
	}
};


int main() {
	int n, q; cin >> n >> q;
	RSQ rmq(n);
	while (q--) {
		int com, x, y;
		cin >> com >> x >> y;
		if (com == 0) {
			rmq.add(x - 1, y);
		} else if (com == 1) {
			cout << rmq.get(x - 1, y) << endl;
		}
	}
}

