struct BinaryIndexedTree {
private:
  std::vector<T> node;

public:
  BinaryIndexedTree(int n_) { node.resize(n_, 0); }
  void add(int k, T x) {
    for (int j = k + 1; j <= node.size(); j += j & -j) node[j-1] += x;
