  srand(time(NULL));

  int n,q;
  Treap t;

  cin >> n >> q;
  for(int i=0;i<n;i++)t.insert(i,0);

  int com,x,y;
  for(int i=0;i<q;i++){
    cin >> com >> x >> y;
    x--;
    if(com==0)t.add(x,y);
    else if(com==1)cout << t.rangeSumQuery(x,y) << endl;
  }

  return 0;
}

