struct SegmentTree {
private:
	int n;
	vector<int> node;
public:
	SegmentTree(vector<int> v) {
		int sz = (int)v.size();
		n = 1; while (n < sz)n *= 2;
		node.resize(2 * n - 1, 0);

		//葉にもともとの配列をセット
		for (int i = 0; i < sz; i++)node[i + n - 1] = v[i];

		//葉から根に向かって更新していく
		for (int i = n - 2; i >= 0; i--)node[i] = node[i * 2 + 1] + node[i * 2 + 2];
	}

	void add(int k, int val) {

		//葉の番号は+(n-1)すれば求まる
		k += (n - 1);

		//葉に値を足す
		node[k] += val;

		//上りながら更新する
		while (k > 0) {
			k = (k - 1) / 2;
			node[k] = node[2 * k + 1] + node[2 * k + 2];
		}
	}

	//根から完全に覆えるまで降りていく感じ
	int getsum(int a, int b, int k = 0,int l = 0, int r = -1) {

		//初回の呼び出しのみr=nにする。
		if (r < 0)r = n;

		//[a b] [l r]
		//[l r] [a b]
		//みたいな状況だったら和の単位元の0を返す
		if (b <= l || r <= a) return 0;

		//完全に覆われてたら、計算済みの値を返す
		if (a <= l && r <= b)return node[k];

		//そうでなかったら左の子と右の子へ再帰で投げて
		//帰ってきた値を足す
		int vl = getsum(a, b, 2 * k + 1, l, (l + r) / 2);
		int vr = getsum(a, b, 2 * k + 2, (l + r) / 2, r);

		return vl + vr;
	}

};

int main() {
	int n, q; cin >> n >> q;

	//配列に初期値があればそれを受け取って渡す、今回は全部0
	SegmentTree seg(vector<int>(n, 0));

	for (int i = 0; i < q; i++) {
		int c, x, y; cin >> c >> x >> y;
		if (c == 0)seg.add(x - 1, y);
		else cout << seg.getsum(x - 1, y) << endl;
	}

	return 0;
}

