	node *seg = nullptr;
	while (q--) {
		int com, x, y;
		cin >> com >> x >> y; x--;
		if (com == 0) {
			seg = update(seg, x, y, 0, n);
		}
		else {
			printf("%d\n", find(seg, x, y, 0, n));
		}
	}
	return 0;
}

