	static size_type getsize(const size_type size) {
		size_type ret = 1;
		while (ret < size)
			ret <<= 1;
		return ret;
	}

public:
	fenwick_tree() : base_size(0), c() {}
	explicit fenwick_tree(const size_type size)
		: base_size(getsize(size)), c(size + 1, value_structure::identity()) {}

	bool empty() const { return size() == 0; }
	size_type size() const { return c.size() - 1; }

	value_type fold(size_type last) const {
		assert(last <= size());
		value_type ret = value_structure::identity();
		for (; last; last &= last - 1)
			ret = value_structure::operation(c[last], ret);
		return ret;
	}
	template <class F> size_type search(const F &f) const {
		if (f(value_structure::identity()))
			return 0;
		size_type i = 0, k = base_size;
		value_type acc = value_structure::identity();
		while (k >>= 1)
			if ((i | k) < c.size() && !f(value_structure::operation(acc, c[i | k])))
				acc = value_structure::operation(acc, c[i |= k]);
		return i + 1;
	}

	void update(size_type index, const value_type &diff) {
		assert(index < size());
		for (++index; index < c.size(); index += index & ~index + 1)
			c[index] = value_structure::operation(c[index], diff);
	}
};

template <class T> class plus_monoid {
public:
	using value_type = T;
	static value_type operation(const value_type &x, const value_type &y) {
		return x + y;
	}
	static value_type identity() { return value_type(0); }
	static value_type reverse(const value_type &x) { return x; }
};

