            else if(targetl <= nowl && targetr >= nowr) return result[nownum];
            else {
                long long int tmp1 = getsum(targetl, targetr, 2 * nownum, nowl, (nowl + nowr) / 2);
                long long int tmp2 = getsum(targetl, targetr, 2 * nownum + 1, (nowl + nowr) / 2 + 1, nowr);
                return tmp1 + tmp2;
            }
        }

