template<class value_type> class dynamic_memory_allocation_segtree{
private:
    class node{
    public:
        value_type value;
        int64_t left,right;
        node *left_child,*right_child;
        node(const value_type &value_,const int64_t left_,const int64_t right_){
            value=value_;
            left=left_;
            right=right_;
            left_child=right_child=NULL;
        }
    };
    value_type id,initial_value;
    std::function<value_type(value_type,value_type)> fun;
    node root;

    value_type update(node *node_,const int64_t index,const value_type &new_value){
        if(node_->right-node_->left==1) return node_->value=new_value;
        const int64_t mid=(node_->left+node_->right)/2;
        value_type left_value=id,right_value=id;
        if(index<mid){
            if(node_->left_child==NULL) node_->left_child=new node(id,node_->left,mid);
            if(node_->right_child!=NULL) right_value=node_->right_child->value;
            left_value=update(node_->left_child,index,new_value);
        }else{
            if(node_->left_child!=NULL) left_value=node_->left_child->value;
            if(node_->right_child==NULL) node_->right_child=new node(id,mid,node_->right);
            right_value=update(node_->right_child,index,new_value);
        }
        return node_->value=fun(left_value,right_value);
    }

    value_type query(node* node_,const int64_t left,const int64_t right){
        if(left<=node_->left and node_->right<=right) return node_->value;
        if(node_->right<=left or right<=node_->left) return id;
        value_type left_value=id,right_value=id;
        if(node_->left_child!=NULL) left_value=fun(left_value,query(node_->left_child,left,right));
        if(node_->right_child!=NULL) right_value=fun(right_value,query(node_->right_child,left,right));
        return fun(left_value,right_value);
    }

public:
    dynamic_memory_allocation_segtree()=default;
    dynamic_memory_allocation_segtree(const int64_t left,const int64_t right,const std::function<value_type(value_type,value_type)> &fun_,const value_type &id_,const value_type &initial_value_):
    root(id_,left,right){ init(left,right,fun_,id_,initial_value_); }

    void init(const int64_t left,const int64_t right,const std::function<value_type(value_type,value_type)> &fun_,const value_type &id_,const value_type &initial_value_){
        root=node(id_,left,right);
        id=id_;
        fun=fun_;
        initial_value=initial_value_;
    }

    void update(int64_t index,const value_type &new_value){ update(&root,index,new_value); }
    void add(int64_t index,const value_type &add_value){
        const value_type current_value=query(&root,index,index+1);
        update(&root,index,current_value+add_value);
    }
    value_type query(const int64_t left,const int64_t right){ return query(&root,left,right); }
};

void solve(){
    int n,q;
    cin >> n >> q;
    dynamic_memory_allocation_segtree<int> seg(0,infll,[](int x,int y){ return x+y; },0,0);
