template <class T>
class SegTree{
    int n; //葉の数(要素数)
    vector<T> data; //データ格納用
    T def; //初期値で単位元
    function<T(T,T)> operation; //区間クエリ使用
    function<T(T,T)> update; //点更新で使用

    //区間[a,b)の総和
    T _query(int a,int b,int k,int l,int r){
        if(r<=a||b<=l)return def; //範囲外だから
        if(a<=l&&r<=b)
            return data[k]; //a,l,r,bで完全に含まれる
        else {
            T c1=_query(a,b,2*k+1,l,(l+r)/2); //左の子
            T c2=_query(a,b,2*k+2,(l+r)/2,r); //右の子
            return operation(c1,c2);
        }
    }

  public:
    // _n:必要サイズ, _def:初期値かつ単位元, _operation:クエリ関数,
    // _update:更新関数
    SegTree(size_t _n,T _def,function<T(T,T)> _operation,function<T(T,T)> _update)
        :  def(_def),operation(_operation),update(_update){
            n=1;
            while(n<_n){
                n*=2;
            }
            data=vector<T>(2*n-1,def);
    }

    // 場所i(0-indexed)の値をxで更新
    void change(int i,T x){
        i+=n-1;
        data[i]=update(data[i],x);
        while(i>0){
            i=(i-1)/2;
            data[i]=operation(data[i*2+1],data[i*2+2]);
        }
    }

    //[a,b)の区間クエリを実行
    T query(int a,int b){
        return _query(a,b,0,0,n);
    }

    T operator[](int i){
        return data[i+n-1];
    }
};

int main(void){
  int N,Q;
  cin>>N>>Q;
  SegTree<ll> st(N,0,
                 [](ll a,ll b){return a+b;},
