template<class T, T monoid>
class SegmentTree{
public:
  vector<T> dat;
  int _n;

  SegmentTree(int size) : _n{1}{
    while(size > _n) _n *= 2;
    dat.resize(2*_n-1, monoid);
  } 

  void update(int k, int a){
    k += _n-1;
    dat[k] += a;

    while(k > 0){
      k = (k-1) / 2;
      dat[k] = dat[k * 2 + 1] + dat[k * 2 + 2];
    }
  }

  T query(int a, int b){
    return _query(a, b, 0, 0, _n);
  }

  void print(){
    for(const auto& v: dat) cout << v << " ";
    cout << endl;
  }
private:
  T _query(int a, int b, int k, int l, int r){
    if(r <= a || b <= l) {
      return monoid;
    }
    if(a <= l && r <= b) {
      return dat[k];
    }
    else {
      T v1 = _query(a, b, k * 2 + 1, l, (l + r) / 2);
      T v2 = _query(a, b, k * 2 + 2, (l + r) / 2, r);

      return v1 + v2;
    }
  }
};

