class BIT {
private:
	vll bi;
	int n;
	ll sum_0start(int t) {
		int x = 1, p = t;
		ll ret = 0;
		while (p > 0) {
			if (x & t) {
				ret += bi[p];
				p -= x;
			}
			x <<= 1;
		}
		return ret;
	}
public:
	BIT(vll a) {
		n = a.size();
		vll s(n + 1, 0);
		Loop1(i, n) {
			s[i] = s[i - 1] + a[i - 1];
		}
		bi.resize(n + 1, 0);
		Loop1(i, n) {
			int x = i;
			x = x & (x*(-1));
			bi[i] = s[i] - s[i - x];
		}
	}
	ll sum(int s, int t) {
		return sum_0start(t) - sum_0start(s);
	}
	void add(int k, int x) {
		k++;
		do {
			bi[k] += x;
			k += k&(k*(-1));
		} while (k <= n);
	}
};

