#define N (300000)
#define M (1000000000)
long long a[N];
long long laz[N];
int sl[N];
int sr[N];
int l[N];
int r[N];
int nx;

//初期化
void init(void){
	f(i, N){
		a[i] = 0;
		laz[i] = 0;
		sl[i] = -1;
		sr[i] = -1;
	}
	l[0] = 0;
	r[0] = M;
	nx = 1;
	return;
}




long long ranchange(int ll, int rr, int k, long long x){
	long long vl, vr;
	if (rr <= l[k] || r[k] <= ll)return 0;
	else if (ll <= l[k] && r[k] <= rr){
		laz[k] += x;
		return (x*(r[k]-l[k]));
	}
	else{
		int mm = (l[k] + r[k]) / 2;
		if (l[k] < rr&&ll < mm){
			if (sl[k] == -1){
				l[nx] = l[k];
				r[nx] = mm;
				sl[k] = nx;
				nx++;
			}
			vl=ranchange(ll, rr, sl[k], x);
		}
		else vl = 0;

		if (mm < rr&&ll < r[k]){
			if (sr[k] == -1){
				l[nx] = mm;
				r[nx] = r[k];
				sr[k] = nx;
				nx++;
			}
			vr=ranchange(ll, rr, sr[k], x);
		}
		else vr = 0;
		a[k] += (vl + vr);
		return (vl + vr);
	}
}


//探索(0<=l<r<=n)範囲は(l<=x<r)初期は(l,r,0)
long long sum_search(int ll, int rr, int k){
	if (laz[k] > 0){
		a[k] += laz[k]*(r[k]-l[k]);
		int mm = (l[k] + r[k]) / 2;
		if (sl[k] == -1){
			l[nx] = l[k];
			r[nx] = mm;
			sl[k] = nx;
			nx++;
		}
		laz[sl[k]] += laz[k];
		if (sr[k] == -1){
			l[nx] = mm;
			r[nx] = r[k];
			sr[k] = nx;
			nx++;
		}
		laz[sr[k]] += laz[k];
		laz[k] = 0;
	}

	long long vl, vr;
	if (rr <= l[k] || r[k] <= ll)return 0;
	else if (ll <= l[k] && r[k] <= rr) return a[k];
	else{
		if (sl[k] != -1)vl = sum_search(ll, rr, sl[k]);
		else vl = 0;
		if (sr[k] != -1)vr = sum_search(ll, rr, sr[k]);
		else vr = 0;
		if (sl[k] == -1){
			if (sr[k] == -1){
				a[k] = 0;
			}
			else{
				a[k] = a[sr[k]];
			}
		}
		else{
			if (sr[k] == -1){
				a[k] = a[sl[k]];
			}
			else{
				a[k] = a[sl[k]] + a[sr[k]];
			}
		}
		return (vl+vr);
	}
}


int main(void){
	int q;
	int c, x, y;
	long long k;
	init();
	scanf("%d %d", &c, &q);
	f(qq, q){
		scanf("%d", &c);
		if (c == 0){
			scanf("%d %lld", &x, &k);
			ranchange(x - 1, x, 0, k);
		}
		else if (c == 1){
			scanf("%d %d", &x, &y);
			k = sum_search(x - 1, y, 0);
			printf("%lld\n", k);
		}
	}

	return 0;
}

