#include <bits/stdc++.h>
using namespace std;

const int id = 0;

int op(int l, int r) {
	return l + r;
}

struct node {
	int pos, val, all;
	node *lch, *rch;
	node(int p, int v)
		: pos(p), val(v), all(v), lch(nullptr), rch(nullptr) {}
};

void update_up(node* t) {
	t->all = op(op((t->lch ? t->lch->all : id), t->val), (t->rch ? t->rch->all : id));
}

node *update(node* t, int p, int val, int lb, int ub) {
	if (!t) return new node(p, val);
	if (t->pos == p) {
		t->val += val;
		update_up(t);
		return t;
	}
	int m = (lb + ub) >> 1;
	if (p < m) {
		if (t->pos < p) {
			swap(t->pos, p);
			swap(t->val, val);
			update_up(t);
		}
		t->lch = update(t->lch, p, val, lb, m);
	}
	else {
		if (t->pos > p) {
			swap(t->pos, p);
			swap(t->val, val);
			update_up(t);
		}
		t->rch = update(t->rch, p, val, m, ub);
	}
	update_up(t);
	return t;
}

int find(node* t, int l, int r, int lb, int ub) {
	if (!t || r <= lb || ub <= l) return id;
	if (l <= lb && ub <= r) return t->all;
	int m = (lb + ub) >> 1;
	int val = l <= t->pos && t->pos < r ? t->val : id;
	return op(op(find(t->lch, l, r, lb, m), val), find(t->rch, l, r, m, ub));
}

