// Monoid: operator^
struct Monoid {
  ll d;
  const ll e = 0;
  Monoid() { d = 0; }
  Monoid(ll d) : d(d) {}
  void operator=(const ll& x) { d = x; }
  void operator=(const Monoid& x) { d = x.d; }
  void operator^=(const Monoid& x) { d = x.d + d; }
  Monoid operator^(const Monoid& x) { return Monoid(x.d + d); }
};

struct MinMonoid {
  ll d;
  const ll e = INF;
  MinMonoid() { d = 0; }
  MinMonoid(ll d) : d(d) {}
  void operator=(const ll& x) { d = x; }
  void operator=(const MinMonoid& x) { d = x.d; }
  void operator^=(const MinMonoid& x) { d = min(x.d, d); }
  MinMonoid operator^(const MinMonoid& x) { return MinMonoid(min(x.d, d)); }
};

struct MaxMonoid {
  ll d;
  const ll e = -INF;
  MaxMonoid() { d = 0; }
  MaxMonoid(ll d) : d(d) {}
  void operator=(const ll& x) { d = x; }
  void operator=(const MaxMonoid& x) { d = x.d; }
  void operator^=(const MaxMonoid& x) { d = max(x.d, d); }
  MaxMonoid operator^(const MaxMonoid& x) { return MaxMonoid(max(x.d, d)); }
};

// SegmentTree
template <typename Monoid1, typename Monoid2>
class AbstractSegmentTree {
  using F = function<Monoid2(Monoid1, ll)>;
  ll n;
  vector<Monoid1> data;
  F f;
public:
  AbstractSegmentTree(vector<Monoid1> _data, F f) : f(f) {
    n = 1;
    while ((ll)_data.size() > n) n *= 2;
    data.resize(2*n);
    for (ll i = 0; i < (ll)_data.size(); i++) data[n+i] = _data[i];
    for (ll i = n-1; i > 0; i--) data[i] = data[2*i] ^ data[2*i+1];
  }
  Monoid1 at(ll num) { return data[n+num]; }
  void add(ll num, Monoid1 x) {
    num += n;
    data[num] ^= x;
    num /= 2;
    while (num > 0) data[num] = data[2*num] ^ data[2*num+1], num /= 2;
  }
  void update(ll num, Monoid1 x) {
    num += n;
    data[num] = x;
    num /= 2;
    while (num > 0) data[num] = data[2*num] ^ data[2*num+1], num /= 2;
  }
  // [a, b)
  Monoid2 query(ll a, ll b, ll num = 1, ll s = 0, ll t = -1) {
    if (t == -1) t = n;
    if (a <= s && t <= b) return f(data[num], num);
    ll mid = (s + t) / 2;
    if (b <= mid) return query(a, b, 2*num, s, mid);
    if (mid <= a) return query(a, b, 2*num+1, mid, t);
    return query(a, b, 2*num, s, mid) ^ query(a, b, 2*num+1, mid, t);
  }
};

template <typename T> function<T(T, ll)> _segmentTreeIdentity = [](T t, ll num) { return t; };
//T _segmentTreeIdentity(T t, ll num) { return t; }

template <typename Monoid>
class SegmentTree : public AbstractSegmentTree<Monoid, Monoid> {
public:
  SegmentTree(vector<Monoid> _data) : AbstractSegmentTree<Monoid, Monoid>(_data, _segmentTreeIdentity<Monoid>) {}
};

