class RSQ
{
public:
    vector<int> data;
    int n;

    RSQ(int _n)
    {
        data.resize(4*_n);
        for(n=1;n<_n;n<<=1);
        fill(data.begin(),data.end(),0);
    }

    void add(int p,int l,int r,int x,int a,int b)
    {
        if(a>=r||b<=l) return;
        if(a<=l&&r<=b)
        {
            data[p]+=x;
            return;
        }

        int mid=(l+r)/2;
        add(p*2+1,l,mid,x,a,b);
        add(p*2+2,mid,r,x,a,b);
        data[p]=data[2*p+1]+data[2*p+2];
    }

    int getSum(int p,int l,int r,int a,int b)
    {
        int sum=0;
        if(a>=r||b<=l){
            sum=0;
        }else if(a<=l&&r<=b)
        {
            sum=data[p];
        }else
        {
            int mid=(l+r)/2;
            sum=getSum(p*2+1,l,mid,a,b)+getSum(p*2+2,mid,r,a,b);
        }
        return sum;
    }
};

