	}
};
struct SUM {
	int64 e;
	int64 s;
	SUM() { set(); }
	SUM(int64 x, int64 y) { e = x;s = y; }
	void set() { e = 0; s = 1; }
	void reverse(void) {
		return;
	}
	SUM operator+(const SUM &other) {
		return  SUM(e + other.e, s + other.s);
	};
	SUM operator*(const SUB &other) {
		if (other.a) return SUM(s*other.e, s);
		return *this;
	}
};
