void add(const int &index, const int &value, std::vector<int> &vec){
	vec.at(index) += value;
	if (index != 0){
		add((index - 1) >> 1, value, vec);
	}
}
int get_sum(const int &start, const int &end, const std::vector<int> &vec){
	if (start == end){
		return vec.at(start);
	}else if (start > end){
		return 0;
	}else{
		int sum = get_sum(start  >> 1, ((end - 1) >> 1) - 1, vec);
		if (start % 2 == 0){
			sum += vec.at(start);
		}
		if (end % 2 == 1){
			sum += vec.at(end);
		}
		return sum;
	}
}
