template<typename T>class segment_tree:private std::vector<T>{
private:
    using typename std::vector<T>::size_type;
    using std::vector<T>::data;
    using std::vector<T>::size;
    using std::vector<T>::resize;
    std::function<T(T,T)>operation;
    T identity;
public:
    segment_tree(size_type n,std::function<T(T,T)>opr,T id):operation(opr),identity(id)
    {
        size_type _n=1;while(_n<n)_n<<=1;
        resize(_n*2-1,identity);
    }
    T&operator[](size_type idx)
    {
        return data()[idx+size()/2];
    }
    void update()
    {
        for(size_type i=size()/2-1;i>=0;--i){
            data()[i]=operation(data()[i*2+1],data()[i*2+2]);
        }
    }
    void update(size_type idx,T val)
    {
        idx+=size()/2;
        data()[idx]=val;
        while(idx>0){
            idx=(idx-1)/2;
            data()[idx]=operation(data()[idx*2+1],data()[idx*2+2]);
        }
    }
    T query(size_type l,size_type r)const
    {
        l+=size()/2;r+=size()/2;
        T L=identity,R=identity;
        while(l<r){
            if(l%2==0)L=operation(L,data()[l++]);
            if(r%2==0)R=operation(data()[--r],R);
            l>>=1;
            r>>=1;
        }
        return operation(L,R);
    }
    static segment_tree<T>sum(size_type n)
    {
        return segment_tree<T>(n,std::plus<T>(),static_cast<T>(0));
    }
    static segment_tree<T>product(size_type n)
    {
        return segment_tree<T>(n,std::multiplies<T>(),static_cast<T>(1));
    }
    static segment_tree<T>max(size_type n,T id=std::numeric_limits<T>::min())
    {
        return segment_tree<T>(n,static_cast<const T&(*)(const T&,const T&)>(std::max),id);
    }
    static segment_tree<T>min(size_type n,T id=std::numeric_limits<T>::max())
    {
        return segment_tree<T>(n,static_cast<const T&(*)(const T&,const T&)>(std::min),id);
    }
};

