struct SegmentTree {
  private:
    int n;
    vector<ll> node;

  public:
    SegmentTree(vector<ll> v) {
        int sz = v.size();
        n = 1;
        while(n < sz) {
            n *= 2;
        }
        node.resize(2 * n - 1, 0);
        //最下段に値をいれる
        for(int i = 0; i < sz; i++) {
            node[i + n - 1] = v[i];
        }
        // 下の段から順番に値を入れる
        for(int i = n - 2; i >= 0; i--) {
            //最小値を管理する
            node[i] = node[2 * i + 1] + node[2 * i + 2];
        }
    }
    //もとの配列で場所xの値をvalにupdateする
    void update(int x, ll val) {
        {
            //最下段のノードにアクセスする
            x += (n - 1);
            node[x] = val;
            while(x > 0) {
                x = (x - 1) / 2;
                node[x] = node[2 * x + 1] + node[2 * x + 2];
            }
        }
    }
    //もとの配列で場所xの値をval追加する
    void add(int x, ll val) {
        {
            //最下段のノードにアクセスする
            x += (n - 1);
            node[x] += val;
            while(x > 0) {
                x = (x - 1) / 2;
                node[x] = node[2 * x + 1] + node[2 * x + 2];
            }
        }
    }

    // 対象区間 : 各ノードがカバーしている区間
    // 要求区間 [a, b) 中の要素の最小値を答える
    // k := 自分がいるノードのインデックス
    // 対象区間は [l, r) にあたる
    ll getsum(int a, int b, int k = 0, int l = 0, int r = -1) {
        //最初に呼び出された時の対象区間は[0, n)
        if(r < 0) {
            r = n;
        }
        if(r <= a || b <= l) {
            //[l.r) \cap [a, b)_= \emptyset
            //要求区間が対象区間と交わらない->適当に返す
            return 0;
        }
        if(a <= l and r <= b) {
            //要求区間が対象区間を完全にconver
            //[l, r) \subset [a, b)
            return node[k];
        }
        //
        //左側の子がvl
        //右側の子がvr
        //新しい対象区間は，現在の対象
        ll vl = getsum(a, b, 2 * k + 1, l, (l + r) / 2);
        ll vr = getsum(a, b, 2 * k + 2, (l + r) / 2, r);
        return vl + vr;
    }
};

