struct fenwicktree
{
    vector<int> tree;
    fenwicktree(int n):tree(n+1) {}

    int sum(int pos)
    {
        int ret=0;
        while(pos>0)
        {
            ret += tree[pos];
            pos &= (pos-1);
        }
        return ret;
    }

    void add(int pos,int value)
    {
        while(pos < tree.size())
        {
            tree[pos] += value;
            pos += (pos & -pos);
        }
    }
};

