template <typename T> struct BIT {
    vector<T> v;
    BIT(int n) { v.assign(n + 1, 0); }
    // [0, k]
    T sum(int k) {
        T res = 0;
        for(++k; k > 0; k -= k & -k) {
            res += v[k];
        }
        return res;
    }
    // [l, r)
    T sum(int l, int r) {
        return (l == 0 ? sum(r - 1) : sum(r - 1) - sum(l - 1));
    }
    void add(int k, T x) {
        for(++k; k < v.size(); k += k & -k) {
            v[k] += x;
        }
    }
};

