i64 BIT_CLZ(i64 x) {
    if(x == 0) return 64;
    return __builtin_clzll(x);
}

i64 BIT_CTZ(i64 x) {
    if(x == 0) return 64;
    return __builtin_ctzll(x);
}

i64 BIT_POP(i64 x) {
    return __builtin_popcountll(x);
}

i64 pow2_ceil(i64 x) {
    assert(x > 0);
    return 1LL << (64 - BIT_CLZ(x-1));
}

i64 pow2_floor(i64 x) {
    assert(x > 0);
    return 1LL << (63 - BIT_CLZ(x));
}

