  vector<ll> ans;
  for (int i = 0; i < q; i++) {
    if (query[i][0] == 0) { // update
      st.update(query[i][1]-1, query[i][2]);
    }
    else { // findMin
      ans.push_back(st.query(query[i][1]-1, query[i][2]));
    }
  }

  for (auto &x: ans) cout << x << endl;

  return 0;
}

