operator fun IntRange.contains(target: IntRange): Boolean = this.first <= target.first && target.last <= this.last
infix fun IntRange.separates(other: IntRange): Boolean = this.last < other.first || other.last < this.first
val IntRange.endExclusive
    get() = this.last + 1

class SegTree(val size: Int, val zero: Int, val op: (Int, Int) -> Int) {
    val v = IntArray(size){zero}
    val n = run {
        var n = 1
        while (n < size) n *= 2
        n
    }
    val node = IntArray(2*n-1){zero}
    init {
        for (i in 0 until v.size) node[i+n-1] = v[i]
        for (i in n-2 downTo 0) node[i] = op(node[2*i+1], node[2*i+2])
    }

    operator fun get(x_: Int) = node[x_ + n - 1]

    operator fun set(x_: Int, value: Int) {
        var x = x_ + n - 1
        node[x] = value
        while (x > 0) {
            x = (x - 1) / 2
            node[x] = op(node[2*x+1], node[2*x+2])
        }
    }

    operator fun get(query: IntRange): Int = getrec(query, 0, 0 until n)

    fun getrec(query: IntRange, k: Int, range: IntRange): Int {
        if (query separates range) return zero
        if (range in query) return node[k]
        val vl = getrec(query, 2*k+1, with(range){first until (first+endExclusive)/2})
        val vr = getrec(query, 2*k+2, with(range){(first+endExclusive)/2 until endExclusive})
        return op(vl, vr)
    }
}

class IO {
    val printable = 33..126
    val buffer = ByteArray(1024)
    var ptr = 0
    var buflen = 0
    val out = PrintWriter(System.out)
    fun hasNextByte(): Boolean {
        if (ptr < buflen) {
            return true
        } else {
            ptr = 0
            buflen = System.`in`.read(buffer)
            if (buflen <= 0) {
                return false
            }
        }
        return true
    }
    fun readByte(): Byte {
        return if (hasNextByte()) buffer[ptr++] else return -1
    }
    fun hasNext(): Boolean {
        while (hasNextByte() && buffer[ptr] !in printable) ptr++
        return hasNextByte()
    }
    fun string(): String {
        if (!hasNext()) throw NoSuchElementException()
        val sb = StringBuilder()
        var b = readByte()
        while (b in printable) {
            sb.appendCodePoint(b.toInt())
            b = readByte()
        }
        return sb.toString()
    }
    fun long(): Long {
        if (!hasNext()) throw NoSuchElementException()
        var n = 0L
        var minus = false
        var b = readByte()
        if (b == '-'.toByte()) {
            minus = true
            b = readByte()
        }
        if (b !in '0'.toByte()..'9'.toByte()) {
            throw NumberFormatException()
        }
        while (true) {
            if (b in '0'.toByte()..'9'.toByte()) {
                n *= 10
                n += b - '0'.toByte()
            } else if (b == (-1).toByte() || b !in printable) {
                return if (minus) -n else n
            } else {
                throw NumberFormatException()
            }
            b = readByte()
        }
    }
    fun int(): Int {
        val nl = long()
        if (nl !in Integer.MIN_VALUE..Integer.MAX_VALUE) throw NumberFormatException()
        return nl.toInt()
    }
    fun double(): Double {
        return string().toDouble()
    }
    fun print(obj: Any) = out.print(obj)
    fun print(i: Int) = out.print(i)
    fun print(l: Long) = out.print(l)
    fun println(obj: Any) = out.println(obj)
    fun println(i: Int) = out.println(i)
    fun println(l: Long) = out.println(l)
    inline fun exec(block: IO.() -> Unit) {
        block()
        out.flush()
    }
}

