	static class segTreesum{
		int size;
		long[] dat;
		public segTreesum(int n) {
			int n_=1;
			while (n_<n) {
				n_*=2;
			}
			size=n_;
			dat=new long[2*n_-1];
		}
		void update(int k,long a) {
			k += size-1;
			dat[k]+=a;
			while (k>0) {
				k=(k-1)/2;//親
				dat[k]+=a;
			}
		}
		long getsum(int a,int b,int k,int l,int r) {//kが節点番号,l rがその節点番号の範囲
			if (r<=a||b<=l) {
				return 0;
			}
			if (a<=l&&r<=b) {
				return dat[k];
			}
			else {
				long vl=this.getsum(a, b, k*2+1,l,(l+r)/2);
				long vr=this.getsum(a, b, k*2+2, (l+r)/2, r);
				return (vl+vr);
			}
		}//getsum(x, y, 0, 0, size)で呼ぶ
	}
	static class InputReader { 
		private InputStream in;
		private byte[] buffer = new byte[1024];
		private int curbuf;
		private int lenbuf;
		public InputReader(InputStream in) {
			this.in = in;
			this.curbuf = this.lenbuf = 0;
		}

		public boolean hasNextByte() {
			if (curbuf >= lenbuf) {
				curbuf = 0;
				try {
					lenbuf = in.read(buffer);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (lenbuf <= 0)
					return false;
			}
			return true;
		}

		private int readByte() {
			if (hasNextByte())
				return buffer[curbuf++];
			else
				return -1;
		}

		private boolean isSpaceChar(int c) {
			return !(c >= 33 && c <= 126);
		}

		private void skip() {
			while (hasNextByte() && isSpaceChar(buffer[curbuf]))
				curbuf++;
		}

		public boolean hasNext() {
			skip();
			return hasNextByte();
		}

		public String next() {
			if (!hasNext())
				throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b = readByte();
			while (!isSpaceChar(b)) {
				sb.appendCodePoint(b);
				b = readByte();
			}
			return sb.toString();
		}

		public int nextInt() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			int res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public long nextLong() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			long res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public double nextDouble() {
			return Double.parseDouble(next());
		}

		public int[] nextIntArray(int n) {
			int[] a = new int[n];
			for (int i = 0; i < n; i++)
				a[i] = nextInt();
			return a;
		}

		public long[] nextLongArray(int n) {
			long[] a = new long[n];
			for (int i = 0; i < n; i++)
				a[i] = nextLong();
			return a;
		}

		public char[][] nextCharMap(int n, int m) {
			char[][] map = new char[n][m];
			for (int i = 0; i < n; i++)
				map[i] = next().toCharArray();
			return map;
		}
	}
}

import java.io.InputStream;
import java.io.PrintStream;
import java.util.Arrays;
import java.util.Scanner;

class SegmentTree {
	int[] node;
	int d = 0;
	int n;

	public SegmentTree(int[] arr) {
		int s = arr.length;
		int m = 2;
		while (s > m) {
			m *= 2;
		}
		this.n = m;
		node = new int[2 * n - 1];

		Arrays.fill(node, d);
		System.arraycopy(arr, 0, node, n - 1, arr.length);
		for (int i = n - 2; i >= 0; i--) {
			node[i] = node[2 * i + 1] + node[2 * i + 2];
		}
	}

	public void add(int i, int val) {
		int x = n - 1 + i;
		node[x] += val;

		while (x > 0) {
			x = (x - 1) / 2;
			node[x] = node[2 * x + 1] + node[2 * x + 2];
		}

	}

	// [a,b) の合計を返す
	public int getSum(int a, int b) {
		return getSum(a, b, 0, 0, n);
	}

	private int getSum(int a, int b, int k, int l, int r) {
		// 範囲がかぶっていなければ、単位元を返す
		if (r <= a || l >= b) {
			return d;
		}

		// 範囲が一致していれば、node[k]を返す
		if (a <= l && r <= b) {
			return node[k];
		}

		int vl = getSum(a, b, 2 * k + 1, l, (r + l) / 2);
		int vr = getSum(a, b, 2 * k + 2, (r + l) / 2, r);
		return vl + vr;
	}

}

public class Main {
	InputStream in = System.in;
	PrintStream out = System.out;

	public void _main(String[] args) {
		Scanner sc = new Scanner(in);

		int n = sc.nextInt();
