	static void update(int i,int a){
		i += n-1;
		seg[i] += a;
		while (i > 0) {
			i = (i-1)/2;
			seg[i] = seg[2*i+1] + seg[2*i+2];
		}
	}

	static int query(int a,int b,int i,int l,int r){
		if (r<a || b<l)
			return 0;
		if (a<=l && r<=b){
			return seg[i];
		}else {
			int vl = query(a,b,i*2+1,l,(l+r)/2);
			int vr = query(a,b,i*2+2,(l+r+1)/2,r);
			return vl+vr;
		}
	}
}

