		int sum = 0;
		for (int i=x+n, j=y+n; i<=j; i=(i+1)>>1, j=(j-1)>>1) {
			if ((i&1)==1) {
				sum += rsq[i];
			}
			if ((j&1)==0) {
				sum += rsq[j];
			}
		}
		System.out.println(sum);
	}
