/**
 * モノイドを乗せられるセグメントツリーの抽象クラス<br>
 * operator メソッドをオーバライドすることで二項演算を定義する<br>
 * データの1点更新と区間に対する質問クエリをO(log(N))で行う
 */
abstract class SegmentTree<T> {

    /** 単位元 */
    protected T e;

    protected int n;
    protected ArrayList<T> tree;


    abstract protected T operator(T x, T y);

    /**
     * 要素eで埋められた要素数nmemb個のセグ木を生成
     * @param nmemb 要素数
     * @param e 初期要素(単位元であること)
     */
    public SegmentTree(int nmemb, T e) {
        this.e = e;

        n = 1;
        while (n < nmemb) {
            n *= 2;
        }

        tree = new ArrayList<T>(2 * n - 1);
        for (int i = 0; i < 2 * n - 1; i++) {
            tree.add(e);
        }
    }

    /**
     * データを更新する.<br>
     * O(log(N))
     * @param k データの位置
     * @param dat 更新データ
     */
    public void update(int k, T dat) {
        k += n - 1;

        tree.set(k, dat);

        while(k > 0) {
            k = (k - 1) / 2;
            tree.set(k, operator(tree.get(k * 2 + 1), tree.get(k * 2 + 2)));
        }
    }

    /**
     * [l, r)区間の二項演算の結果を返す.<br>
     * O(log(N))
     * @param l 区間の左
     * @param r 区間の右
     * @return 演算結果
     */
    public T query(int l, int r) {
        l += n - 1;
        r += n - 1;

        T d = e;
        while (l < r) {
            if (l % 2 == 0) {
                d = operator(d, tree.get(l));
                l++;
            }
            if (r % 2 == 0) {
                r--;
                d = operator(d, tree.get(r));
            }

            l = (l - 1) / 2;
            r = (r - 1) / 2;
        }

        return d;
    }

    /**
     * デバッグ情報の出力
     */
    public void debugPrint() {
        int cnt = 1;
        int i = 0;

        System.err.printf("n:%d tree.size():%d\n", n, tree.size());

        while (i < 2 * n - 1) {
            for (int j = 0; j < cnt; i++, j++) {
                System.err.printf(" [%d]: ", i);
                System.err.print(tree.get(i));
            }
            System.err.println("");

            cnt *= 2;
        }
    }
}

public class Main {

	public void run(java.io.InputStream in, java.io.PrintStream out) {
		final java.util.Scanner sc = new java.util.Scanner(in);
		final RankInADynamicSubset lis = new RankInADynamicSubset(sc.nextInt());
		final int q = sc.nextInt();

		for (int i = 0; i < q; ++i) {
			final int com = sc.nextInt();
			final int x = sc.nextInt();
			final int y = sc.nextInt();

			if (com == 0) {
				lis.add(x, y);
			} else if (com == 1) {
				out.println(lis.currentRankOf(x, y));
			}
		}

		sc.close();
	}

	public static void main(String[] args) {
		(new Main()).run(System.in, System.out);
	}

	private static class RankInADynamicSubset {
		private int[] d;
		private int   n;

		public RankInADynamicSubset(int n) {
			this.n = 1;
			while (this.n < n) {
				this.n *= 2;
			}
			d = new int[this.n * 2];
			java.util.Arrays.fill(d, 0);
		}

		public void add(int i, int x) {
			i = n + i;
			d[i] = x;
			while (i != 1) {
				i /= 2;
				d[i] = d[i * 2] + d[i * 2 + 1];
			}
		}

		public int currentRankOf(int s, int t) {
			return currentRankOf(s, t, 0, n - 1, 1);
		}

		private int currentRankOf(int s, int t, int lb, int ub, int i) {
			final int m = (lb + ub) / 2;
			int res;

			if (s <= lb && ub <= t) {
				return (d[i]);
			}

			res = 0;
			if (s <= m) {
				res += currentRankOf(s, t, lb, m, i * 2);
			}
			if (m + 1 <= t) {
				res += currentRankOf(s, t, m + 1, ub, i * 2 + 1);
			}

			return (res);
		}
	}

}

