class ArrayManager {
	private int[] array;
	private int n;
	private final int INIT = 0;
//	private int origin = 1;

	public ArrayManager(int n){
		this.n = n;
		array = new int[n + 1];



		Arrays.fill(array, INIT);
	}

	public void update(int index, int num){
		array[index] = num;
	}

	public int findMin(int s, int t){
		int min = Integer.MAX_VALUE;

		for(int i = s ; i <= t; i++){
			if(min > array[i]){
				min = array[i];
			}
		}

		return min;
