	// Binary Indexed Tree
	private static class BIT {
		// [0,n-1]
		int[] bit;
		int n;
		// [1,n]
		BIT(int n) {
			this.n = n;
			bit = new int[this.n];
		}

		// i:1-indexed
		void add(int i, int x) {
			while (i <= n) {
				bit[i - 1] += x;
				i += i & (-i);
			}
		}

		// i:1-indexed
		// [1,i]
		int query(int i) {
			int sum = 0;
			while (i > 0) {
				sum += bit[i - 1];
				i -= i & (-i);
			}

			return sum;
		}
	}

