class Sum implements SegmentTree.Monoide<Integer>{
	@Override
	public Integer apply(Integer l, Integer r) {
		return l + r;
	}

	@Override
	public Integer identify() {
		return 0;
	}
}

@SuppressWarnings("unchecked")
class SegmentTree<T>{
	int n;
	T[] x;
	Monoide<T> mono;
	interface Monoide<T> {
		T apply(T l, T r);
		T identify();
	}
	SegmentTree(T[] input, Monoide<T> mono){
		this.mono = mono; 
		n = input.length;
		x = (T[]) new Object[2 * n];
		Arrays.fill(x, mono.identify());
		for(int i=0;i<n;i++) {
			x[i + n] = input[i];
		}
		for(int i=n-1;i>0;i--) {
			x[i] = mono.apply(x[i << 1], x[i << 1 | 1]);
		}
	}
	SegmentTree(int n, Monoide<T> mono){
		this.mono = mono; 
		this.n = n;
		x = (T[]) new Object[2 * n];
		Arrays.fill(x, mono.identify());
	}

	void add(int p, T value) {
		for(x[p += n] = mono.apply(x[p], value); p > 1; p >>= 1) {
			x[p >> 1] = mono.apply(x[p], x[p^1]);
		}
	}

	void update(int p, T value){
		for(x[p += n] = value; p > 1; p >>= 1) {
			x[p >> 1] = mono.apply(x[p], x[p^1]);
		}
	}

	T query(int l, int r) {
		T res = mono.identify();
		for(l += n, r += n; l < r; r >>= 1, l >>= 1) {
			if((l & 1) == 1) res = mono.apply(res, x[l++]);
			if((r & 1) == 1) res = mono.apply(res, x[--r]);
		}
		return res;
	}

}

