	public BITree(int n, boolean d) {
		debug = d;
		bit = new int[n + 10];
	}

	public int getSum(int x1, int x2) {
		return nSum(x2) - nSum(x1 - 1);
	}

	private int nSum(int x) {
		int r = 0;
		for (int i = x; i > 0; i -= i & -i)
			r += bit[i];
		if (debug)
			System.out.println(x + " " + r);
		return r;
	}

