	/**
	 * 0-indexed BinaryIndexTree
	 * */
	static class BIT {
		private int n;
		private long[] bit;

		public BIT(int n) {
			this.n = n;
			bit = new long[n + 1];
		}

		public void clear() {
			Arrays.fill(bit, 0);
		}

		public void add(int i, long x) {
			while (i <= n) {
				bit[i] += x;
				i |= i + 1;
			}
		}

		public long query(int l, int r) {
			return l <= r ? query(r) - query(l - 1) : 0;
		}

		private long query(int i) {
			long s = 0;
			while (i >= 0) {
				s += bit[i];
				i = (i & (i + 1)) - 1;
			}
			return s;
		}
	}

