		rsq[i] += x;
		if(i == 0)
			return;
		i = (i-1) / 2;
		while(i >= 0){
			rsq[i] += x;
			i = (i-1)/2;
                        if(i == 0)
				break;
		}
	}
	public static long getSum(long rsq[], int s, int t, int left, int right, int i){
		if(right <= s || left > t)
			return 0;
		else if(left >= s && right <= t+1)
			return rsq[i];
		else
			return getSum(rsq,s,t,left,(left+right)/2,2*i+1) + getSum(rsq,s,t,(left+right)/2,right,2*i+2);
	}
