class BinaryIndexedTree{
	int n;
	int[] node;

	/* 初期値は0 */
	public BinaryIndexedTree(int n){
		this.n = n;
		node = new int[n+1];
	}

	/* 1-indexed */
	public void add(int x, int val){
		for(int i = x; i <= n; i += (i & -i)){
			node[i] += val;
		}
	}

	/* 
	 * [1,a], 1-indexed
	 * sum(0) == 0
	 */
	public int sum(int a){
		int res = 0;
		for(int i = a; i > 0; i -= (i & -i)){
			res += node[i];
		}
		return res;
	}

	/* [a,b], 1-indexed */
	public int sum(int a, int b){
		return sum(b) - sum(a-1);
	}

