            size = 1;

            while (size < n) size *= 2;

            segment = new int[2 * size];
        }

        static void Update(int i, int a)
        {
            i += size - 1;
            segment[i] += a;

            while (i > 0)
            {
                i = (i - 1) / 2;
                segment[i] += a;
            }
        }

        static int Query(int a, int b, int k, int l, int r)
        {
            if (r <= a || b <= l) return 0;

            if (a <= l && r <= b) return segment[k];
            else
            {
                int vl = Query(a, b, k * 2 + 1, l, (l + r) / 2);
                int vr = Query(a, b, k * 2 + 2, (l + r) / 2, r);

                return vl + vr;
            }
        }
    }
}

