public class RangeSumBIT
{
    int N;
    int[] buffer;

    public RangeSumBIT(int size)
    {
        N = size;
        buffer = new int[size + 1];
    }

    public void Add(int index, int value)
    {
        for (int i = index + 1; i <= N; i += i & -i) buffer[i] += value;
    }

    public int Sum(int index)//[0,index)
    {
        int ret = 0;
        for (int i = index; i > 0; i -= i & -i) ret += buffer[i];
        return ret;
    }
}

