public class Avl{
	public class Nd{
		public int h=1,c=1;
		public readonly int n;
		public long d,ds;
		public Nd l,r;
		public Nd(int n,long d,Nd du){this.n=n;this.d=d;ds=d;l=du;r=du;}
	}
	public Nd root,du;
	public int cnt=0;
	public Avl(){
		du=new Nd(int.MinValue,0,du);du.h=0;du.c=0;
		root=du;
	}
	public void Ud(int n,long d){
		if(root==du){root=new Nd(n,d,du);cnt++;}
		else if(root.n==n){root.d+=d;root.ds+=d;}
		else if(Fu(root,n,d)){
			if(Abs(root.l.h-root.r.h)>1){root=Rotate(root);}
			cnt++;
		}
	}
	private bool Fu(Nd t,int n,long d){
		t.ds+=d;
		bool bo=false;
		if(t.n>n){
			if(t.l!=du){
				if(t.l.n==n){t.l.d+=d;t.l.ds+=d;}
				else if(bo=Fu(t.l,n,d)){
					t.c++;
					if(Abs(t.l.l.h-t.l.r.h)>1){t.l=Rotate(t.l);}
					t.h=Max(t.l.h,t.r.h)+1;
				}
			}
			else{t.l=new Nd(n,d,du);bo=true;t.c++;t.h=Max(t.l.h,t.r.h)+1;}
		}
		else{
			if(t.r!=du){
				if(t.r.n==n){t.r.d+=d;t.r.ds+=d;}
				else if(bo=Fu(t.r,n,d)){
					t.c++;
					if(Abs(t.r.l.h-t.r.r.h)>1){t.r=Rotate(t.r);}
					t.h=Max(t.l.h,t.r.h)+1;
				}
			}
			else{t.r=new Nd(n,d,du);bo=true;t.c++;t.h=Max(t.l.h,t.r.h)+1;}
		}
		return bo;
	}
	private Nd Rotate(Nd t){
		Nd nd=du;
		if(t.l.h>t.r.h){
			if(t.l.l.h>t.l.r.h){
				nd=t.l;t.l=t.l.r;nd.r=t;
				Ft(t);
			}
			else{
				nd=t.l.r;
				t.l.r=nd.l;nd.l=t.l;
				Ft(t.l);
				t.l=nd.r;nd.r=t;
				Ft(t);
			}
		}
		else{
			if(t.r.l.h>t.r.r.h){
				nd=t.r.l;
				t.r.l=nd.r;nd.r=t.r;
				Ft(t.r);
				t.r=nd.l;nd.l=t;
				Ft(t);
			}
			else{
				nd=t.r;t.r=t.r.l;nd.l=t;
				Ft(t);
			}
		}
		Ft(nd);
		return nd;
	}
	private void Ft(Nd t){
		t.h=Max(t.l.h,t.r.h)+1;
		t.c=t.l.c+t.r.c+1;
		t.ds=t.l.ds+t.r.ds+t.d;
	}
	public bool Dl(int n){
		if(cnt==0){return false;}
		Nd t=root;
		if(t.n==n){
			root=Fd2(root);
			if(cnt==0){return true;}
			else if(Abs(root.l.h-root.r.h)>1){root=Rotate(root);}
			else{Ft(root);}
			return true;
		}
		bool bo=Fd1(root,n);
		if(Abs(root.l.h-root.r.h)>1){root=Rotate(root);}
		else{Ft(root);}
		return bo;
	}
	private bool Fd1(Nd t,int n){
		if(t.n>n){
			if(t.l==du){return false;}
			else if(t.l.n!=n){
				bool bo=Fd1(t.l,n);
				if(Abs(t.l.l.h-t.l.r.h)>1){t.l=Rotate(t.l);}
				else{Ft(t.l);}
				return bo;
			}
			else{
				t.l=Fd2(t.l);
				Ft(t);
				return true;
			}
		}
		else{
			if(t.r==du){return false;}
			else if(t.r.n!=n){
				bool bo=Fd1(t.r,n);
				if(Abs(t.r.l.h-t.r.r.h)>1){t.r=Rotate(t.r);}
				else{Ft(t.r);}
				return bo;
			}
			else{
				t.r=Fd2(t.r);
				Ft(t);
				return true;
			}
		}
	}
	private Nd Fd2(Nd dn){
		cnt--;
		if(dn.l==du){return dn.r;}
		if(dn.r==du){return dn.l;}
		Nd u=dn.l;
		if(u.r==du){
			u.r=dn.r;
			Ft(u);
			return u;
		}
		u=Fd3(u,dn);
		if(Abs(dn.l.l.h-dn.l.r.h)>1){u.l=Rotate(dn.l);}
		else{Ft(dn.l);}
		Ft(u);
		return u;
	}
	private Nd Fd3(Nd u,Nd dn){
		if(u.r.r!=du){
			Nd v=Fd3(u.r,dn);
			if(Abs(u.r.l.h-u.r.r.h)>1){u.r=Rotate(u.r);}
			else{Ft(u.r);}
			return v;
		}
		else{
			Nd v=u.r;u.r=u.r.l;v.l=dn.l;v.r=dn.r;
			return v;
		}
	}
	public Nd Hs(int n){
		Nd t=root;
		if(cnt==0){return null;}
		if(t.n==n){return t;}
		Nd a=null;
		while(true){
			if(t.n>n){
				if(t.l==du){break;}
				else if(t.l.n!=n){t=t.l;}
				else{a=t.l;break;}
			}
			else{
				if(t.r==du){break;}
				else if(t.r.n!=n){t=t.r;}
				else{a=t.r;break;}
			}
		}
		return a;
	}
	public Nd Ra(int n){return cnt>=n?Fr(root,n):null;}
	private Nd Fr(Nd t,int n){
		if(t.l.c>n-1){return Fr(t.l,n);}
		if(t.l.c<n-1){return Fr(t.r,n-t.l.c-1);}
		return t;
	}
	public Nd Lb(int n){return cnt!=0?Flb(root,n):null;}
	private Nd Flb(Nd t,int n){
		if(t.n<n){
			if(t.r==du){return null;}
			return Flb(t.r,n);
		}
		if(t.n>n){
			if(t.l==du){return t;}
			Nd u=Flb(t.l,n);
			return u==null?t:u;
		}
		return t;
	}
	public Nd Ub(int n){return cnt!=0?Fub(root,n):null;}
	private Nd Fub(Nd t,int n){
		if(t.n>n){
			if(t.l==du){return null;}
			return Fub(t.l,n);
		}
		if(t.n<n){
			if(t.r==du){return t;}
			Nd u=Fub(t.r,n);
			return u==null?t:u;
		}
		return t;
	}
	public int Rg(int a,int b){return cnt!=0?Frg(root,a,b,false,false):0;}
	private int Frg(Nd t,int a,int b,bool l,bool r){
		if(t.h==0){return 0;}
		if(l&&r){return t.c;}
		if(t.n<a){return Frg(t.r,a,b,t.n>=a,r);}
		if(t.n>b){return Frg(t.l,a,b,l,t.n<=b);}
		return Frg(t.l,a,b,l,t.n<=b)+Frg(t.r,a,b,t.n>=a,r)+1;
	}
	public long Rd(int a,int b){return cnt!=0?Frd(root,a,b,false,false):0;}
	private long Frd(Nd t,int a,int b,bool l,bool r){
		if(t.h==0){return 0;}
		if(l&&r){return t.ds;}
		if(t.n<a){return Frd(t.r,a,b,t.n>=a,r);}
		if(t.n>b){return Frd(t.l,a,b,l,t.n<=b);}
		return Frd(t.l,a,b,l,t.n<=b)+Frd(t.r,a,b,t.n>=a,r)+t.d;
	}
	public void Ad(int n,int d){
		Nd t=root;
		if(cnt==0){return;}
		if(t.n==n){t.d+=d;t.ds+=d;return;}
		while(true){
			t.ds+=d;
			if(t.n>n){
				if(t.l==du){break;}
				else if(t.l.n!=n){t=t.l;}
				else{t.l.d+=d;t.l.ds+=d;break;}
			}
			else{
				if(t.r==du){break;}
				else if(t.r.n!=n){t=t.r;}
				else{t.r.d+=d;t.r.ds+=d;break;}
			}
		}
	}
}

