namespace ConsoleApplication1
{
    class Program
    {
        static int[] segment;
        static int size;

        static void Main(string[] args)
        {
            string[] input1 = Console.ReadLine().Split(' ');
            int n = int.Parse(input1[0]);
            int q = int.Parse(input1[1]);

            Init(n);

            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < q; i++)
            {
                string[] input2 = Console.ReadLine().Split(' ');
                int c = int.Parse(input2[0]);
                int x = int.Parse(input2[1]);
                int y = int.Parse(input2[2]);

                if (c == 0) Add(x, y);
                else
                {
                    sb.AppendLine(GetSum(x, y + 1, 0, 0, size).ToString());
                }
            }
            Console.Write(sb);
        }

        static void Init(int n)
        {
            size = 1;

            while (size < n) size *= 2;

            segment = new int[2 * size];
        }

        static void Add(int x, int val)
        {
            x += size - 1;
            segment[x] += val;

            while (x > 0)
            {
                x = (x - 1) / 2;
                segment[x] = segment[x * 2 + 1] + segment[x * 2 + 2];
            }
        }

        static int GetSum(int a, int b, int k, int l, int r)
        {
            if (r <= a || b <= l) return 0;

            if (a <= l && r <= b) return segment[k];
            else
            {
                int vl = GetSum(a, b, k * 2 + 1, l, (l + r) / 2);
                int vr = GetSum(a, b, k * 2 + 2, (l + r) / 2, r);

                return vl + vr;
            }
        }
    }
}

