            this.n = 1;
            while(n < nArr) {
                this.n *= 2;
            }

            nodes = new int[2 * this.n];
        }

        public void Add(int i, int x) {
            nodes[this.n + i - 1] += x;

            var cur = this.n + i - 1;

            while(cur > 1) {
                var p = cur / 2;
                nodes[p] += x;
                cur = p;
            }
        }

