            return Find(l, r, 1, 1, n + 1);
        }

        private int Find(int l, int r, int cur, int nowL, int nowR) {
            if (r <= nowL || nowR <= l) {
                return 0;
            }

            if (l <= nowL && nowR <= r) {
                return nodes[cur];
            }

            return Find(l, r, 2 * cur, nowL, (nowL + nowR) / 2) + Find(l, r, 2 * cur + 1, (nowL + nowR) / 2, nowR);
        }
    }

    public void Run() {
        var nq = ReadLib.ReadAsIntArray();
        var tree = new SegTree(nq[0]);
        for (int i = 0; i < nq[1]; i++) {
            var cxy = ReadLib.ReadAsIntArray();
            if (cxy[0] == 0) {
                tree.Add(cxy[1], cxy[2]);
            }

            if (cxy[0] == 1) {
                Console.WriteLine(tree.Find(cxy[1], cxy[2] + 1));
            }
        }
    }
}



