type SegTree []int

func MakeSegTree(n_ int) SegTree {
	n := 1
	for n < n_ {
		n <<= 1
	}
	return make([]int, n<<1)
}

func (t SegTree) Add(i, x int) {
	i += len(t) >> 1
	for i > 0 {
		t[i] += x
		i >>= 1
	}
}

func (t SegTree) getSum(a, b int) int {
	return t.getSumRecur(a, b, 1, 0, len(t)>>1)
}
func (t SegTree) getSumRecur(a, b, k, l, r int) int {
	if b <= l || r <= a {
		return 0
	}
	if a <= l && r <= b {
		return t[k]
	}
	sum := 0
	sum += t.getSumRecur(a, b, k<<1, l, (l+r)>>1)
	sum += t.getSumRecur(a, b, k<<1+1, (l+r)>>1, r)
	return sum
}

