func NewRMQ(size int) *RMQ {
	s := 1
	for s < size {
		s *= 2

	}
	r := make([]int, s*2)
	for i := 0; i < s*2; i++ {
		r[i] = MIN
	}
	return &RMQ{data: r, size: s}
}

func (r *RMQ) update(k, a int) {
	k += r.size - 1
	r.data[k] = a
	for k > 0 {
		k = (k - 1) / 2
		r.data[k] = r.data[k*2+1] + r.data[k*2+2]
	}

}

