func stringsToInts(s, sep string) []int {
	ss := strings.Split(s, sep)
	ints := make([]int, 0)
	for _, c := range ss {
		i, _ := strconv.Atoi(c)
		ints = append(ints, i)
	}
	return ints
}

func sum(tree []int, targetL, targetR, currentL, currentR, idx int) int {
	if targetL <= currentL && currentR <= targetR {
		return tree[idx]
	}

	if (targetR < currentL) || (currentR < targetL) {
		return 0
	}

	sum := sum(tree, targetL, targetR, currentL, (currentL+currentR)/2, idx*2+1) + sum(tree, targetL, targetR, (currentL+currentR)/2+1, currentR, idx*2+2)
	return sum
}

func compute(tree []int, com, x, y, size int) {
	switch com {
	case 0: // add(x, y)
		x = x - 1
		treeidx := size + x - 1
		tree[treeidx] += y
		for treeidx != 0 {
			treeidx = (treeidx - 1) / 2
			tree[treeidx] += y
		}
	case 1: // getSum(x,y)
		sum := sum(tree, x-1, y-1, 0, size-1, 0)
		fmt.Println(sum)
	}
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	line := scanner.Text()
	ints := stringsToInts(line, " ")
	n, q := ints[0], ints[1]

	pow := math.Ceil(math.Log2(float64(n)))
	leafSize := int(math.Pow(2, pow))
	binaryTree := make([]int, int(math.Pow(2, pow+1)-1))

	for i := 0; i < q; i++ {
		scanner.Scan()
		line := scanner.Text()
		ints := stringsToInts(line, " ")
		com, x, y := ints[0], ints[1], ints[2]
		compute(binaryTree, com, x, y, leafSize)
	}
}

