type Tree struct {
	n   int
	bit []int
}

func New(n int) *Tree {
	return &Tree{
		n:   n,
		bit: make([]int, n+1),
	}
}

func (t *Tree) Add(i, x int) {
	for i <= t.n {
		t.bit[i] += x
		i |= i + 1
	}
}

func (t *Tree) Query(l, r int) int {
	var ret int
	if l <= r {
		ret = t.query(r) - t.query(l-1)
	}
	return ret
}

func (t *Tree) query(i int) int {
	var ret int
	for i >= 0 {
		ret += t.bit[i]
		i = (i & (i + 1)) - 1
	}
	return ret
}

