type segment [][]int

func newSegment(n int) segment {
	seg := make(segment, 0)
	for n > 1 {
		seg = append(seg, make([]int, n))
		n = (n + 1) >> 1
	}
	seg = append(seg, make([]int, 1))
	return seg
}

func (s segment) assign(h, i int, v interface{}) {
	s[h][i] = v.(int)
}
func (s segment) height() int {
	return len(s)
}
func (s segment) width(h int) int {
	return len(s[h])
}
func (s segment) at(h, i int) interface{} {
	return s[h][i]
}
func (s segment) f(x, y interface{}) interface{} {
	return x.(int) + y.(int)
}

type segtree interface {
	assign(h, i int, v interface{})
	height() int
	width(h int) int
	at(h, i int) interface{}
	f(x, y interface{}) interface{}
}

func update(s segtree, i int) {
	for h := 1; h < s.height(); h++ {
		i >>= 1
		if i<<1+1 < s.width(h-1) {
			s.assign(h, i, s.f(s.at(h-1, i<<1), s.at(h-1, i<<1+1)))
		} else {
			s.assign(h, i, s.at(h-1, i<<1))
		}
	}
}
func query(s segtree, l, r int, v interface{}) interface{} {
	for h := 0; h < s.height() && l < r; h++ {
		if l&1 == 1 {
			v = s.f(v, s.at(h, l))
			l++
		}
		l >>= 1
		if r&1 == 1 {
			v = s.f(v, s.at(h, r-1))
		}
		r >>= 1
	}
	return v
}

