func NewMemo(n int) Memo {
	valueList := make([]int, n)
	list := make([]int, int(math.Ceil(float64(n)/float64(math.Floor(math.Sqrt(float64(n)))))))
	for i := range valueList {
		valueList[i] = DEF_VAL
	}
	for i := range list {
		list[i] = DEF_VAL
	}
	m := Memo{list, valueList, int(math.Floor(math.Sqrt(float64(n))))}
	return m
}

