class BinaryIndexTree {
    private int[] _bit;

    this(int n) {
        _bit = new int[n + 1];
    }

    int sum(int p) {
        int s = 0;
        while (p > 0) {
            s += _bit[p];
            p -= p & -p;
        }
        return s;
    }

    void add(int p, int x) {
        while (p < _bit.length) {
            _bit[p] += x;
            p += p & -p;
        }
    }
}

