struct SqrtDecomp {
    private {
        int N, K;
        enum sqrtN = 512;
        int[] bucketSum;
        int[] data;
    }

    this(int n) {
        N = n;
        K = (N + sqrtN - 1) / sqrtN;
        bucketSum = new int[](K);
        data = new int[](K * sqrtN);
    }

    void add(int i, int x) {
        int k = i / sqrtN;
        data[i] += x;
        bucketSum[k] += x;
    }

    int sum(int l, int r) {
        int res;
        foreach (k ; 0 .. K) {
            int bl = k * sqrtN, br = (k + 1) * sqrtN;
            if (r <= bl || br <= l) continue;
            if (l <= bl && br <= r) {
                res += bucketSum[k];
            }
            else {
                foreach (i ; max(l, bl) .. min(r, br)) {
                    res += data[i];
                }
            }
        }
        return res;
    }
}



