class BIT():
    """数列aに対して以下の操作がO(log n) でできる
    - add(i,x): a[i] += x
    - sum_1_to_i(i): 区間[1, i]のaの総和

    sum_i_to_j(i,j): 区間[i,j]のaの総和
    数列aは0に初期化されているとする"""
    def __init__(self, n:int):
        self.n = n
        self.bit = [0]*(n+1)

    def add(self, i:int, x:int):
        """i番目(1-idexed)にxを加算"""
        while i<=self.n:
            self.bit[i] += x
            i += i&-i

    def sum_1_to_i(self, i:int)->int: 
        """1番目からi番目(含む)までの総和"""
        s=0
        while i>0:
            s += self.bit[i]
            i -= i&-i
        return s

    def sum_i_to_j(self, i:int, j:int):
        """i番目からj番目(含む)までの総和"""
        return self.sum_1_to_i(j) - self.sum_1_to_i(i-1)

