"""
Segment-Tree
    maxval:入力されるデータ以上の値
    offset:根と枝の数(n=1のときは根1つ葉2つの木)
    init_array(array):配列で初期化
    update(k,x):k番目をxに変更
    min_query(p,q):[p,q)の範囲の最小値
"""
class SegmentTree():
    def __init__(self,n):
        self.offset=self.setOffset(n)
        self.segTree=[0]*(2*self.offset+1)

    def init_array(self,array):
        for i in range(len(array)):
            self.segTree[i+self.offset]=array[i]
        for i in range(offset-1,-1,-1):
            self.segTree[i]=self.sumChild(i)

    def setOffset(self,n):
        if n==1:
            return 1
        else:
            return 2**(n-1).bit_length()-1

    def update(self,k,x):
        k+=self.offset
        self.segTree[k]+=x
        while k:
            k=(k-1)//2
            self.segTree[k]+=x

    def sum_query(self,p,q):
        if p>=q:
            return

        p+=self.offset
        q+=self.offset-1
        segsum=0

        while q-p>1:
            #p%2==0
