impl<T: SEGimpl> SEG<T> {
    #[allow(dead_code)]
    fn new(n: usize, init: T::Elem) -> SEG<T> {
        let n = (1..).map(|i| 1 << i).find(|&x| x >= n).unwrap();
        SEG {
            n: n,
