struct SegmentTree{
    node : Vec<i64>,
    size : usize,
}

impl SegmentTree{
    fn new(size : usize)->SegmentTree{
        let mut x:usize =1;
        while x<size{
            x*=2;
        }
        SegmentTree{
            node : vec![0;2*x-1],
            size : x,
        }
    }
    fn add(&mut self, mut k:usize,x:i64){
        k+=self.size-1;
        self.node[k]+=x;
        while k>0{
            k=(k-1)/2;
            self.node[k]+=x;
        }
    }

    fn getsum( &self,a:usize,b:usize,k:usize,l:usize,r:usize)->i64{
        if r<=a || b<=l{
            return 0;
        }
        if a<=l && r<=b{
            return self.node[k];
        }
        let lx=self.getsum(a,b,2*k+1,l,(l+r)/2);
        let rx=self.getsum(a,b,2*k+2,(l+r)/2,r);
        lx+rx
    }
    fn get_sum(&self,a:usize,b:usize)->i64{
        self.getsum(a,b,0,0,self.size)
    }
}



