    data: Vec<i64>,
}

impl BIT {
    fn new(n: usize) -> BIT {
        let mut vec = vec![0; n+1];
        BIT {
            n: n, 
            data: vec
        }
    }

    fn add(&mut self, i: usize, x: i64) {
        let mut i: i32 = i as i32;
        while i <= (self.n as i32) {
            self.data[i as usize] += x;
            i = i + (i & -i);
        }
    }

    // [1, i] での和
    fn sum(&mut self, i: usize) -> i64 {
        let mut i: i32 = i as i32;
        let mut ret: i64 = 0;
        while i > 0 {
            ret += self.data[i as usize];
            i = i - (i & -i);
        }
        return ret
    }
}

