type Sum = usize;

impl Monoid for Sum {
    fn mempty() -> Sum {
        0
    }
    fn mappend(a: Sum, b: Sum) -> Sum {
        a + b
    }
}
impl SegmentTree<Sum> {
    pub fn add(&mut self, k: usize, a: Sum) {
        let b = self.data[k + self.n - 1];
        self.update(k, Sum::mappend(b, a));
    }
}

pub trait Monoid: Copy {
    fn mempty() -> Self;
    fn mappend(a: Self, b: Self) -> Self;
}
pub struct SegmentTree<M> {
    n: usize,
    data: Vec<M>,
}
impl<M: Monoid> SegmentTree<M> {
    pub fn new(n: usize) -> SegmentTree<M> {
        let mut m = 1;
        while m <= n {
            m *= 2;
        }

        SegmentTree {
            n: m,
            data: vec![M::mempty(); 2 * m],
        }
    }
    pub fn update(&mut self, k: usize, a: M) {
        let mut k = k + self.n - 1;
        self.data[k] = a;
        while k > 0 {
            k = (k - 1) / 2;
            self.data[k] = M::mappend(self.data[k * 2 + 1], self.data[k * 2 + 2]);
        }
    }
    pub fn query(&self, l: usize, r: usize) -> M {
        self.query_range(l, r, 0, 0, self.n)
    }
    pub fn query_range(&self, a: usize, b: usize, k: usize, l: usize, r: usize) -> M {
        if r <= a || b <= l {
            M::mempty()
        } else if a <= l && r <= b {
            self.data[k]
        } else {
            let vl = self.query_range(a, b, k * 2 + 1, l, (l + r) / 2);
            let vr = self.query_range(a, b, k * 2 + 2, (l + r) / 2, r);
            M::mappend(vl, vr)
        }
    }
}

use std::io;
use std::io::prelude::*;
use std::iter::repeat;

struct SumSegTree {
    n: usize,
    nodes: Vec<i32>,
}

impl SumSegTree {
    fn init(n: usize) -> SumSegTree {
        let n = 1 << f64::log2(n as f64).ceil() as usize;
        SumSegTree {
            n,
            nodes: repeat(0).take(2 * n - 1).collect(),
        }
    }

    fn update1(&mut self, idx: usize) {
        self.nodes[idx] = self.nodes[2 * idx + 1] + self.nodes[2 * idx + 2];
    }

    fn update_rec(&mut self, idx: usize) {
        self.update1(idx);
        if idx > 0 {
            self.update_rec((idx - 1) / 2);
        }
    }

    fn add(&mut self, i: usize, x: i32) {
        let ni = self.n + i - 1;
        self.nodes[ni] += x;
        if self.n > 1 {
            self.update_rec((ni - 1) / 2);
        }
    }

    fn get_sum(&self, i: usize, j: usize, ni: usize, l: usize, r: usize) -> i32 {
        if i <= l && r <= j {
            self.nodes[ni]
        } else if r <= i || j <= l {
            0
        } else {
            self.get_sum(i, j, 2 * ni + 1, l, (l + r) / 2)
                + self.get_sum(i, j, 2 * ni + 2, (l + r) / 2, r)
        }
    }
}

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    let line0 = lines.next().unwrap().unwrap();
    let n = line0.split_whitespace().next().unwrap().parse().unwrap();

    let mut mst = SumSegTree::init(n);

    for l in lines.map(Result::unwrap) {
        let mut words = l.split_whitespace();
        let com = words.next().unwrap().parse().unwrap();
        let x: usize = words.next().unwrap().parse().unwrap();
        let y: usize = words.next().unwrap().parse().unwrap();
        match com {
            0 => mst.add(x - 1, y as i32),
            1 => println!("{}", mst.get_sum(x - 1, y, 0, 0, mst.n)),
            _ => (),
        }
    }
}

