struct SEG {
    buf: Vec<u64>,
    n: usize,
}

impl SEG {
    fn new(size: usize) -> SEG {
        let n = (1..).map(|i| 1 << i).find(|&x| x > size).unwrap();

        SEG {
            buf: vec![0; 2 * n],
            n: n,
        }
    }

    fn add(&mut self, i: usize, x: u64) {
        let mut i = self.n + i - 1;
        self.buf[i] += x;
        while i > 0 {
            i = (i - 1) / 2;
            self.buf[i] = self.buf[i * 2 + 1] + self.buf[i * 2 + 2];
        }
    }

    fn sum(&self, a: usize, b: usize, k: usize, l: usize, r: usize) -> u64 {
        if r <= a || b <= l {
            return 0;
        }

        if a <= l && r <= b {
            return self.buf[k];
        }

        let vl = self.sum(a, b, k * 2 + 1, l, (l + r) / 2);
        let vr = self.sum(a, b, k * 2 + 2, (l + r) / 2, r);

        vl + vr
    }
}

