pub fn clp(mut x: usize) -> usize {
    x -= 1;
    x = x | (x >>  1);
    x = x | (x >>  2);
    x = x | (x >>  4);
    x = x | (x >>  8);
    x = x | (x >> 16);
    x = x | (x >> 32);
    x + 1
}

struct SegmentTree<T, F> where
    T: Copy,
    F: Fn(T, T) -> T
{
    n: usize,
    f: F,
    unit: T,
    a: Vec<T>
}

impl<T, F> SegmentTree<T, F> where
    T: Copy,
    F: Fn(T, T) -> T
{
    pub fn new(m: usize, f: F, unit: T) -> SegmentTree<T, F> {
        let n = clp(m);
        SegmentTree {
            n: n,
            f: f,
            unit: unit,
            a: vec![unit; 2 * n - 1]
        }
    }

    pub fn update(&mut self, mut i: usize, x: T) {
        i += self.n - 1;
        self.a[i] = x;
        while i != 0 {
            i = (i - 1) / 2;
            self.a[i] = (self.f)(self.a[2 * i + 1], self.a[2 * i + 2]);
        }
    }

    fn _query(&self, query_first: usize, query_last: usize, node: usize, node_first: usize, node_last: usize) -> T {
        if (node_last <= query_first || query_last <= node_first) {
            self.unit
        } else if (query_first <= node_first && node_last <= query_last) {
            self.a[node]
        } else {
            let node_mid: usize = (node_first + node_last) / 2;
            let vl: T = self._query(query_first, query_last, node * 2 + 1, node_first, node_mid);
            let vr: T = self._query(query_first, query_last, node * 2 + 2, node_mid, node_last);
            (self.f)(vl, vr)
        }
    }

    pub fn query(&self, query_first: usize, query_last: usize) -> T {
        self._query(query_first, query_last, 0, 0, self.n)
    }
}

