trait Monoid {
    type T: Clone;
    fn id() -> Self::T;
    fn op(a: &Self::T, b: &Self::T) -> Self::T;
}

#[derive(Debug)]
struct SegmentTree<M: Monoid> {
    n: usize,
    vec: Vec<M::T>,
}

impl<M: Monoid> SegmentTree<M> {
    fn new(n: usize) -> Self {
        let n = n.next_power_of_two();
        SegmentTree {
            n: n,
            vec: vec![M::id().clone(); 2 * n - 1],
        }
    }

    // vec[k] = a
    fn update(&mut self, k: usize, a: M::T) {
        let mut k = k + self.n - 1;
        self.vec[k] = a;
        self.up(k);
    }

    // vec[k] = op(vec[k], a)
    fn add(&mut self, k: usize, a: M::T) {
        let mut k = k + self.n - 1;
        self.vec[k] = M::op(&self.vec[k], &a);
        self.up(k);
    }

    fn up(&mut self, mut k: usize) {
        while k > 0 {
            k = (k - 1) / 2;
            self.vec[k] = M::op(&self.vec[2 * k + 1], &self.vec[2 * k + 2]);
        }
    }

    fn query_sub(&self, a: usize, b: usize, k: usize, l: usize, r: usize) -> M::T {
        if r <= a || b <= l {
            M::id()
        } else if a <= l && r <= b {
            self.vec[k].clone()
        } else {
            M::op(
                &self.query_sub(a, b, k * 2 + 1, l, (l + r) / 2),
                &self.query_sub(a, b, k * 2 + 2, (l + r) / 2, r),
            )
        }
    }

    // op [a, b)
    fn query(&self, a: usize, b: usize) -> M::T {
        self.query_sub(a, b, 0, 0, self.n)
    }

    // vec[k]
    fn get(&self, k: usize) -> M::T {
        self.vec[k + self.n - 1].clone()
    }
}

