struct SegmentTree<Monoid, Operator> {
    size: usize,
    node: Vec<Monoid>,
    f: Operator,
    e: Monoid,
}

impl<Monoid, Operator> SegmentTree<Monoid, Operator>
where
    Operator: Fn(Monoid, Monoid) -> Monoid,
    Monoid: Copy,
{
    pub fn new(n: usize, f: Operator, e: Monoid) -> Self {
        let mut size = 1;
        while size < n {
            size *= 2
        }

        SegmentTree {
            size: size,
            node: vec![e; size * 2],
            f: f,
            e: e,
        }
    }

    pub fn update(&mut self, idx: usize, x: Monoid) {
        let mut k = idx + self.size - 1;
        self.node[k] = x;
        while k > 0 {
            k = (k - 1) / 2;
            self.node[k] = (self.f)(self.node[2 * k + 1], self.node[2 * k + 2]);
        }
    }

    pub fn query(&self, a: usize, b: usize) -> Monoid {
        return self._query(a, b, 0, 0, self.size);
    }

    fn _query(&self, a: usize, b: usize, idx: usize, l: usize, r: usize) -> Monoid {
        if r <= a || b <= l {
            return self.e;
        }

        if a <= l && r <= b {
            return self.node[idx];
        }

        let xl: Monoid = self._query(a, b, 2 * idx + 1, l, (l + r) / 2);
        let xr: Monoid = self._query(a, b, 2 * idx + 2, (r + l) / 2, r);

        return (self.f)(xl, xr);
    }
}

fn main() {
    let (n, q): (usize, usize) = (read(), read());
    let mut seg = SegmentTree::<i32, _>::new(n, |x, y| x + y, 0);

    for _ in 0..q {
        let (com, x, y): (usize, usize, usize) = (read(), read(), read());

        if com == 0 {
            seg.update(x, y as i32);
        } else {
            println!("{}", seg.query(x, y + 1));
        }
    }
}

