pub trait Monoid {
    type T: Clone + Debug;
    fn op(lhs: &Self::T, rhs: &Self::T) -> Self::T;
    fn identity() -> Self::T;
}

#[derive(Debug)]
pub struct SegmentTree<M: Monoid> {
    size: usize,
    node: Vec<M::T>,
}

impl<M: Monoid> SegmentTree<M> {
    pub fn new(n: usize) -> SegmentTree<M> {
        let mut size = 1;
        while size < n {
            size *= 2;
        }

        SegmentTree {
            size: size,
            node: vec![M::identity(); size * 2],
        }
    }

    pub fn set(&mut self, a: usize, v: M::T) {
        self.node[a + self.size] = v;
    }

    pub fn build(&mut self) {
        for k in self.size - 1..0 {
            self.node[k] = M::op(&self.node[k * 2], &self.node[k * 2 + 1]);
        }
    }

    pub fn update(&mut self, a: usize, v: M::T) {
        let mut k = a + self.size;
        self.node[k] = v;
        while k > 1 {
            k >>= 1;
            self.node[k] = M::op(&self.node[k * 2], &self.node[k * 2 + 1]);
        }
    }

    pub fn query(&self, a: usize, b: usize) -> M::T {
        let mut vleft = M::identity();
        let mut vright = M::identity();
        let mut left = self.size + a;
        let mut right = self.size + b;

        while left < right {
            if (left & 1) == 1 {
                vleft = M::op(&vleft, &self.node[left]);
                left += 1;
            }

            if (right & 1) == 1 {
                right -= 1;
                vright = M::op(&self.node[right], &vright);
            }

            left >>= 1;
            right >>= 1;
        }

        return M::op(&vleft, &vright);
    }

    pub fn debug(&self) {
        println!("{:?}", self.node);
    }
}

